// Helper for generating parts of the case
const generateCasePart = async (
    coreCase: PatientCase, 
    discipline: string, 
    difficulty: string, 
    language: string, 
    taskDescription: string, 
    responseSchema: any
) => {
    const ai = getAiClient();
    const difficultyInstructions = getDifficultyInstructions(difficulty);

    const coreCaseContext = `
        **Patient Case Context:**
        - **Title:** ${coreCase.title}
        - **Profile:** ${coreCase.patientProfile}
        - **Complaint:** ${coreCase.presentingComplaint}
        - **History:** ${coreCase.history}
    `;

    const prompt = `
        Based on the provided patient case context, generate the specific sections requested.
        Please provide the entire response in the following language: ${language}.

        ${coreCaseContext}

        **Crucially, tailor the content for a student in **${discipline}**.

        ${difficultyInstructions}

        ${SYNTHESIS_GUIDELINE}

        **Your task is to generate ONLY the following sections:**
        ${taskDescription}

        **FINAL OUTPUT FORMAT:**
        Your entire response MUST be a single JSON object strictly adhering to the specified schema.
  `;

    const response: GenerateContentResponse = await retryWithBackoff(() => ai.models.generateContent({
        model: THINKING_MODEL,
        contents: prompt,
        config: {
            ...THINKING_CONFIG,
            responseMimeType: "application/json",
            responseSchema: responseSchema,
        },
    }));

    return JSON.parse(response.text);
};


export const generateMainDetails = (coreCase: PatientCase, discipline: string, difficulty: string, language: string) => 
    generateCasePart(coreCase, discipline, difficulty, language, "- biochemicalPathway\n- multidisciplinaryConnections", mainDetailsSchema);

export const generateManagementAndContent = (coreCase: PatientCase, discipline: string, difficulty: string, language: string) => 
    generateCasePart(coreCase, discipline, difficulty, language, "- disciplineSpecificConsiderations\n- educationalContent (1-2 items)", managementAndContentSchema);

export const generateEvidenceAndQuiz = (coreCase: PatientCase, discipline: string, difficulty: string, language: string) => 
    generateCasePart(coreCase, discipline, difficulty, language, "- traceableEvidence (3-4 items)\n- furtherReadings\n- quiz (5 questions)", evidenceAndQuizSchema);

export const generateKnowledgeMap = async (coreCase: PatientCase, discipline: string, difficulty: string, language: string): Promise<KnowledgeMapData> => {
    const rawMapData = await generateCasePart(coreCase, discipline, difficulty, language, "- A knowledge map with 8-12 nodes and their links, including concise summaries for each node.", knowledgeMapSchema);

    // Validate links to ensure they connect to existing nodes
    if (!rawMapData || !rawMapData.nodes || !rawMapData.links) {
        throw new Error("Model did not return valid knowledge map data.");
    }

    const validNodeIds = new Set(rawMapData.nodes.map((n: KnowledgeNode) => n.id));
    const validLinks = rawMapData.links.filter((l: KnowledgeLink) => validNodeIds.has(l.source) && validNodeIds.has(l.target));

    return {
        nodes: rawMapData.nodes,
        links: validLinks,
    };
};

// --- END: Parallel Generation Functions ---


export const enrichCaseWithWebSources = async (patientCase: PatientCase, language: string): Promise<{ newEvidence: TraceableEvidence[]; newReadings: FurtherReading[]; groundingSources: any[] }> => {
    const ai = getAiClient();

    const prompt = `
        Regarding the patient case titled "${patientCase.title}", which involves "${patientCase.presentingComplaint}", please act as a medical research assistant.
        Use Google Search to find the most recent, high-quality medical information to provide the following:
        1.  **Two (2) Traceable Evidence items:** Each item must be a specific clinical claim relevant to the case, supported by a citable source found in your search.
        2.  **Two (2) Further Reading suggestions:** These should be recent, relevant review articles or clinical guidelines.

        **CRITICAL:** Format your entire response as a single JSON object inside a markdown code block (\`\`\`json ... \`\`\`). Do not include any other text outside this block.
        The JSON object must have two keys: "traceableEvidence" and "furtherReadings".

        JSON structure example:
        \`\`\`json
        {
          "traceableEvidence": [
            { "claim": "A relevant clinical claim...", "source": "Citation from a top-tier journal or guideline, e.g., NEJM, The Lancet, UpToDate" },
            { "claim": "Another relevant clinical claim...", "source": "Another high-quality source" }
          ],
          "furtherReadings": [
            { "topic": "A specific topic for deeper study...", "reference": "Full citation or name of the article/guideline" },
            { "topic": "Another specific topic...", "reference": "Another reference" }
          ]
        }
        \`\`\`

        Please provide the response in the following language: ${language}.
    `;

    const response: GenerateContentResponse = await retryWithBackoff(() => ai.models.generateContent({
        model: FAST_MODEL,
        contents: prompt,
        config: {
            tools: [{ googleSearch: {} }],
            temperature: 0.2,
        },
    }));

    const groundingSources = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];

    try {
        // Extract JSON from markdown code block
        const text = response.text;
        const jsonMatch = text.match(/```json\n([\s\S]*?)\n```/);
        if (!jsonMatch || !jsonMatch[1]) {
            throw new Error("Model did not return a valid JSON code block.");
        }

        const parsedData = JSON.parse(jsonMatch[1]);
        const newEvidence = parsedData.traceableEvidence || [];
        const newReadings = parsedData.furtherReadings || [];

        return { newEvidence, newReadings, groundingSources };

    } catch (error) {
        console.error("Failed to parse grounded search results:", error);
        // Return empty arrays but still provide the sources if they exist
        return { newEvidence: [], newReadings: [], groundingSources };
    }
};

export const searchForSource = async (sourceQuery: string, language: string): Promise<{ summary: string; sources: any[] }> => {
    const ai = getAiClient();

    const prompt = `
        Please act as a medical research assistant. Use Google Search to find information about the following medical source: "${sourceQuery}".

        Provide a brief summary (2-3 sentences) of this source. If possible, identify its type (e.g., Randomized Controlled Trial, Systematic Review, Clinical Guideline) and its main conclusions or purpose.

        If you can find direct links to the source, please prioritize them.

        Respond in the following language: ${language}.
    `;

    const response: GenerateContentResponse = await retryWithBackoff(() => ai.models.generateContent({
        model: FAST_MODEL,
        contents: prompt,
        config: {
            tools: [{ googleSearch: {} }],
            temperature: 0.1,
        },
    }));

    const summary = response.text;
    const sources = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];

    return { summary, sources };
};

export interface EcgFindings {
    rate?: string;
    rhythm?: string;
    pr?: string;
    qrs?: string;
    qtc?: string;
    stSegment?: string;
    other?: string;
}

export const interpretEcg = async (findings: EcgFindings, imageBase64: string | null, imageMimeType: string | null, language: string): Promise<string> => {
    const ai = getAiClient();

    const textParts = [
        `You are an expert cardiologist providing an educational interpretation of an ECG for a medical professional. Provide a systematic, step-by-step interpretation based on the provided data. Your response should be in Markdown format, using headings for each section.`,
        `## ECG Findings Provided:`,
        `- **Rate:** ${findings.rate || 'Not provided'} bpm`,
        `- **Rhythm:** ${findings.rhythm || 'Not provided'}`,
        `- **PR Interval:** ${findings.pr || 'Not provided'} ms`,
        `- **QRS Duration:** ${findings.qrs || 'Not provided'} ms`,
        `- **QTc Interval:** ${findings.qtc || 'Not provided'} ms`,
        `- **ST Segment:** ${findings.stSegment || 'Not provided'}`,
        `- **Other Findings/Context:** ${findings.other || 'None'}`,
        `\n## Systematic Interpretation Request:`,
        `Based on the data and the provided ECG image (if any), please generate a report covering:`,
        `1.  **Rhythm and Rate:** Analyze the rhythm and confirm the rate.`,
        `2.  **Axis:** Determine the axis if possible from the image.`,
        `3.  **Intervals:** Analyze PR, QRS, and QTc intervals.`,
        `4.  **Morphology:** Systematically comment on P waves, QRS complexes, ST segments, and T waves.`,
        `5.  **Summary / Impression:** Provide a primary interpretation and list 2-3 likely differential diagnoses.`,
        `\n**Disclaimer:** This is an AI-generated interpretation for educational purposes and should not be used for clinical decision-making. All findings must be verified by a qualified human physician.`,
        `\nPlease provide the entire response in ${language}.`
    ];
    const textPrompt = textParts.join('\n');

    const contentParts: any[] = [{ text: textPrompt }];

    if (imageBase64 && imageMimeType) {
        contentParts.push({
            inlineData: {
                data: imageBase64,
                mimeType: imageMimeType,
            },
        });
    }

    // ECG Interpretation benefits from thinking mode
    const response: GenerateContentResponse = await retryWithBackoff(() => ai.models.generateContent({
        model: THINKING_MODEL,
        contents: { parts: contentParts },
        config: { 
            ...THINKING_CONFIG 
        }
    }));

    return response.text;
};


export const generateVisualAid = async (prompt: string): Promise<string> => {
    const ai = getAiClient();
    try {
        const response = await retryWithBackoff<GenerateImagesResponse>(() => ai.models.generateImages({
            model: 'imagen-4.0-generate-001',
            prompt: prompt,
            config: {
              numberOfImages: 1,
              outputMimeType: 'image/png',
              aspectRatio: '4:3',
            },
        }));

        if (response.generatedImages && response.generatedImages.length > 0) {
            return response.generatedImages[0].image.imageBytes;
        } else {
            throw new Error("No image was generated by the API.");
        }
    } catch (error) {
        console.error("Error generating visual aid:", error);
        throw new Error("Failed to generate visual aid. The model may have refused the prompt.");
    }
};

export const checkDrugInteractions = async (drugNames: string[], language: string): Promise<string> => {
    const ai = getAiClient();

    const prompt = `
        As an expert clinical pharmacologist, analyze the following list of paediatric drugs for potential interactions. For each clinically significant interaction you identify, provide a concise summary in Markdown format.
        The user is a medical professional and requires clear, actionable information. Please respond in ${language}.

        Drugs to check:
        - ${drugNames.join('\n- ')}

        For each interaction, use the following structure:
        ### Interaction: [Drug A] & [Drug B]
        **Mechanism:** A brief explanation of the pharmacokinetic or pharmacodynamic mechanism.
        **Clinical Significance:** Describe the potential clinical outcome (e.g., increased risk of toxicity, reduced efficacy) and provide a brief management recommendation (e.g., "Monitor ECG," "Adjust dose," "Avoid combination if possible").

        If no significant interactions are found, respond with only this exact phrase: "No significant interactions were found for the selected drugs."
    `;

    const response: GenerateContentResponse = await retryWithBackoff(() => ai.models.generateContent({
        model: FAST_MODEL,
        contents: prompt,
        config: {
            temperature: 0.2,
        },
    }));

    return response.text;
};

export const generateSpeech = async (text: string, voiceName: string): Promise<string> => {
    const ai = getAiClient();
    try {
        const response = await retryWithBackoff<GenerateContentResponse>(() => ai.models.generateContent({
            model: "gemini-2.5-flash-preview-tts",
            contents: [{ parts: [{ text }] }],
            config: {
                responseModalities: [Modality.AUDIO],
                speechConfig: {
                    voiceConfig: {
                        prebuiltVoiceConfig: { voiceName },
                    },
                },
            },
        }));

        const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
        if (!base64Audio) {
            throw new Error("No audio data received from API.");
        }
        return base64Audio;

    } catch (error) {
        console.error("Error generating speech:", error);
        throw new Error("Failed to generate audio. Please try again.");
    }
};

export const getConceptConnectionExplanation = async (conceptA: string, conceptB: string, caseContext: string, language: string): Promise<string> => {
    const ai = getAiClient();
    const prompt = `
        For a medical student studying a patient case about "${caseContext}", explain the pathophysiological or clinical connection between "${conceptA}" and "${conceptB}".
        Keep the explanation concise (2-3 sentences, around 70-90 words) and focused on the most critical link between them in this specific medical context.
        The tone should be educational and clear.

        ${SYNTHESIS_GUIDELINE}

        Please provide the response in the following language: ${language}.
    `;
    const response: GenerateContentResponse = await retryWithBackoff(() => ai.models.generateContent({
        model: THINKING_MODEL,
        contents: prompt,
        config: {
            ...THINKING_CONFIG,
        },
    }));
    return response.text;
};

export const generateDiagramForDiscussion = async (prompt: string, chatContext: string, language: string): Promise<DiagramData> => {
    const ai = getAiClient();

    const fullPrompt = `
        You are an assistant creating educational visual aids for a medical student during a tutoring session.
        Based on the student's request below, and the preceding conversation for context, generate structured diagram data (nodes and links) for a simple, clear, interactive diagram.
        The diagram should visually explain the concept requested by the student.
        - Nodes should represent key entities (e.g., molecules, cells, organs, concepts).
        - Links should represent the relationships or processes connecting them.
        - Keep the diagram focused and uncluttered, with 4 to 8 nodes being ideal for clarity.

        The entire response MUST be in the following language: ${language}.

        ---
        Conversation Context:
        ${chatContext}
        ---
        Student's Request for Diagram:
        "${prompt}"
        ---

        Now, generate the JSON object for the diagramData. It must not be null.
    `;

    const response: GenerateContentResponse = await retryWithBackoff(() => ai.models.generateContent({
        model: THINKING_MODEL,
        contents: fullPrompt,
        config: {
            ...THINKING_CONFIG,
            responseMimeType: "application/json",
            responseSchema: diagramDataSchema,
        },
    }));

    const parsedResponse = JSON.parse(response.text);

    // Basic validation
    if (!parsedResponse || !parsedResponse.nodes || !parsedResponse.links) {
        throw new Error("Model did not return valid diagram data.");
    }

    return parsedResponse as DiagramData;
};

import React, { useState, useEffect, useRef } from 'react';
import type { DisciplineSpecificConsideration, ChatMessage } from '../types';
import { GoogleGenAI, Chat, GenerateContentResponse, Content } from "@google/genai";
import { retryWithBackoff, generateDiagramForDiscussion } from '../services/geminiService';
import { InteractiveDiagram } from './InteractiveDiagram';
import { MarkdownRenderer } from './MarkdownRenderer';

const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
const isSpeechRecognitionSupported = !!SpeechRecognition;

// Helper to map app language to BCP-47 for speech recognition
const getBCP47Language = (lang: string): string => {
    const map: Record<string, string> = {
        'en': 'en-US',
        'es': 'es-ES',
        'fr': 'fr-FR',
        'zh': 'zh-CN',
        'hi': 'hi-IN',
        'sw': 'sw-KE',
        'ar': 'ar-SA',
        'pt': 'pt-PT',
        'ru': 'ru-RU',
        'el': 'el-GR',
    };
    // Fallback to English for languages where standard speech engines might not have a locale
    return map[lang] || 'en-US';
};

interface DiscussionModalProps {
    isOpen: boolean;
    onClose: () => void;
    topic: DisciplineSpecificConsideration;
    topicId: string;
    caseTitle: string;
    language: string;
    T: Record<string, any>;
    initialHistory?: ChatMessage[];
    onSaveDiscussion: (topicId: string, messages: ChatMessage[]) => void;
}

const LoadingSpinner: React.FC = () => (
    <div className="flex space-x-1.5">
        <div className="w-2 h-2 bg-gray-500 rounded-full animate-bounce" style={{ animationDelay: '0s' }}></div>
        <div className="w-2 h-2 bg-gray-500 rounded-full animate-bounce" style={{ animationDelay: '0.1s' }}></div>
        <div className="w-2 h-2 bg-gray-500 rounded-full animate-bounce" style={{ animationDelay: '0.2s' }}></div>
    </div>
);

export const DiscussionModal: React.FC<DiscussionModalProps> = ({ 
    isOpen, onClose, topic, topicId, caseTitle, language, T, initialHistory, onSaveDiscussion 
}) => {
    const [messages, setMessages] = useState<ChatMessage[]>([]);
    const [userInput, setUserInput] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [isGeneratingDiagram, setIsGeneratingDiagram] = useState(false);
    const [diagramPrompt, setDiagramPrompt] = useState('');
    const [isSaved, setIsSaved] = useState(false);
    const [showShareMenu, setShowShareMenu] = useState(false);
    const chatRef = useRef<Chat | null>(null);
    const messagesEndRef = useRef<HTMLDivElement | null>(null);
    const shareMenuRef = useRef<HTMLDivElement | null>(null);

    // Voice Input State
    const [isListening, setIsListening] = useState(false);
    const [micError, setMicError] = useState<string | null>(null);
    const recognitionRef = useRef<any>(null);

    useEffect(() => {
        if (isOpen) {
            const systemInstruction = `You are an expert medical tutor. A student is reviewing a patient case about "${caseTitle}". They want to discuss the following management consideration: "(${topic.aspect}) ${topic.consideration}". Your role is to facilitate a deep, Socratic discussion. Answer their questions clearly, challenge their understanding, and help them explore alternatives and rationale. Keep your responses concise and educational.

            **Guideline:** When discussing concepts, equations, graphs, and diagrams, examples from traceable references may be used to enhance clarification. If there is synthesis of any of the above mentioned, the bases (evidence) must be provided and a synthesis label (e.g., "[Synthesis]") must be attached to the synthesised item.

            **Molecular Formulas & Clinical Notations:** 
            Always use Unicode subscript characters (e.g., ₀, ₁, ₂, ₃, ₄, ₅, ₆, ₇, ₈, ₉) and superscript characters (e.g., ⁰, ¹, ², ³, ⁴, ⁵, ⁶, ⁷, ⁸, ⁹, ⁺, ⁻) for all formulas. 
            - Examples: CO₂, SpO₂, SaO₂, H₂O, C₆H₁₂O₆, Na⁺, Cl⁻, Ca²⁺, HCO₃⁻, PO₄³⁻. 
            - **CRITICAL:** DO NOT use LaTeX symbols ($), math mode, or markdown bolding for chemical/molecular/clinical formulas. Use plain text with Unicode subscripts/superscripts only.

            **Formatting:** Use standard LaTeX formatting for complex mathematical equations, formulas, and physics concepts ONLY.
            - Inline math: Enclose in single dollar signs, e.g., $E = mc^2$.
            - Block math: Enclose in double dollar signs.

            When providing factual information or clinical guidance, you MUST cite traceable, high-quality evidence (e.g., from systematic reviews, RCTs, or major clinical guidelines). Use a clear citation format like '[Source: JAMA 2023]'. Respond in the following language: ${language}.`;

            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

            let chatHistory: Content[] | undefined = undefined;

            // Restore history if provided
            if (initialHistory && initialHistory.length > 0) {
                setMessages(initialHistory);
                chatHistory = initialHistory
                    .filter(m => m.role === 'user' || m.role === 'model')
                    .map(m => ({
                        role: m.role as 'user' | 'model',
                        parts: [{ text: m.text }]
                    }));
                setIsSaved(true);
            } else {
                setMessages([{ role: 'system', text: T.chatWelcomeMessage }]);
                setIsSaved(false);
            }

            chatRef.current = ai.chats.create({
              model: 'gemini-3-pro-preview',
              config: { 
                  systemInstruction,
                  thinkingConfig: { thinkingBudget: 32768 }
              },
              history: chatHistory
            });

        } else {
            // Reset on close
            chatRef.current = null;
            setIsSaved(false);
            setShowShareMenu(false);
            setMicError(null);
            if (recognitionRef.current) {
                recognitionRef.current.onend = null;
                recognitionRef.current.abort();
                recognitionRef.current = null;
            }
        }
    }, [isOpen, topic, caseTitle, language, T, initialHistory, topicId]);

    const handleMicClick = () => {
        if (!isSpeechRecognitionSupported) return;

        if (isListening && recognitionRef.current) {
            recognitionRef.current.stop();
            return;
        }

        setMicError(null);

        // Create a FRESH instance per click for better "not-allowed" error handling & cross-browser compatibility
        const recognition = new SpeechRecognition();
        recognition.continuous = false;
        recognition.interimResults = false;
        recognition.lang = getBCP47Language(language);

        recognition.onstart = () => {
            setIsListening(true);
        };

        recognition.onend = () => {
            setIsListening(false);
            recognitionRef.current = null;
        };

        recognition.onerror = (event: any) => {
            console.error('Discussion Mic Error:', event.error);
            if (event.error === 'not-allowed' || event.error === 'service-not-allowed') {
                setMicError(T.micPermissionError);
            } else {
                setMicError(T.micGenericError);
            }
            setIsListening(false);
        };

        recognition.onresult = (event: any) => {
            const transcript = event.results[0][0].transcript;
            setUserInput(prev => (prev ? `${prev} ${transcript}` : transcript));
        };

        try {
            recognitionRef.current = recognition;
            recognition.start();
        } catch (err: any) {
            console.error("Mic start failed:", err);
            setMicError(T.micGenericError);
            setIsListening(false);
        }
    };

    useEffect(() => {
        messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }, [messages, isLoading]);

    // Close share menu on click outside
    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (shareMenuRef.current && !shareMenuRef.current.contains(event.target as Node)) {
                setShowShareMenu(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    const handleSendMessage = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!userInput.trim() || isLoading || !chatRef.current) return;

        const newUserMessage: ChatMessage = { role: 'user', text: userInput, timestamp: Date.now() };
        setMessages(prev => [...prev, newUserMessage]);
        setUserInput('');
        setIsLoading(true);
        setIsSaved(false); // Unsaved changes

        try {
            const result = await retryWithBackoff<AsyncIterable<GenerateContentResponse>>(() => chatRef.current!.sendMessageStream({ message: userInput }));

            let currentResponse = '';
            setMessages(prev => [...prev, { role: 'model', text: '', timestamp: Date.now() }]);

            for await (const chunk of result) {
                currentResponse += chunk.text;
                setMessages(prev => {
                    const newMessages = [...prev];
                    newMessages[newMessages.length - 1] = { role: 'model', text: currentResponse, timestamp: Date.now() };
                    return newMessages;
                });
            }
        } catch (error: any) {
            console.error("Chat error:", error);
            if (error.message && (error.message.includes("API key not valid") || error.message.includes("Requested entity was not found") || error.message.includes("API_KEY"))) {
                setMessages(prev => [...prev, { role: 'system', text: T.errorService }]);
            } else {
                setMessages(prev => [...prev, { role: 'system', text: T.errorChat }]);
            }
        } finally {
            setIsLoading(false);
        }
    };

    const handleGenerateDiagram = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!diagramPrompt.trim() || isLoading) return;

        const chatContext = messages.map(m => `${m.role}: ${m.text}`).join('\n');
        const userRequestMessage: ChatMessage = { role: 'system', text: `(Generating diagram: "${diagramPrompt}")` };

        setMessages(prev => [...prev, userRequestMessage]);
        setIsLoading(true);
        setIsGeneratingDiagram(false);

        try {
            const diagramData = await generateDiagramForDiscussion(diagramPrompt, chatContext, language);
            const diagramMessage: ChatMessage = {
                role: 'model',
                text: `Here is a diagram illustrating "${diagramPrompt}":`,
                diagramData: diagramData,
                timestamp: Date.now()
            };
            setMessages(prev => [...prev, diagramMessage]);
            setDiagramPrompt(''); // Clear prompt on success
            setIsSaved(false);
        } catch (error) {
            console.error("Diagram generation error:", error);
            setMessages(prev => [...prev, { role: 'system', text: "Sorry, I couldn't generate that diagram. Please try a different description." }]);
        } finally {
            setIsLoading(false);
        }
    };

    const handleSave = () => {
        onSaveDiscussion(topicId, messages);
        setIsSaved(true);
    };

    const formatTranscript = () => {
        const header = `Discussion Topic: ${topic.aspect}\nContext: ${topic.consideration}\nDate: ${new Date().toLocaleDateString()}\n\n`;
        const body = messages
            .filter(m => m.role !== 'system') 
            .map(m => {
                const speaker = m.role === 'user' ? 'Student' : 'AI Tutor';
                return `[${speaker}]: ${m.text}`;
            })
            .join('\n\n');
        return header + body;
    };

    const handleCopyTranscript = () => {
        const text = formatTranscript();
        navigator.clipboard.writeText(text).then(() => {
            alert(T.transcriptCopied);
            setShowShareMenu(false);
        });
    };

    const handleDownloadTranscript = () => {
        const text = formatTranscript();
        const blob = new Blob([text], { type: 'text/plain' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `Discussion_${topic.aspect.replace(/\s+/g, '_').substring(0, 20)}.txt`;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
        setShowShareMenu(false);
    };

    const handleNativeShare = () => {
        const text = formatTranscript();
        if (navigator.share) {
            navigator.share({
                title: `Discussion: ${topic.aspect}`,
                text: text,
            }).catch(console.error);
        }
        setShowShareMenu(false);
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-black bg-opacity-60 flex items-center justify-center z-50 p-4 animate-fade-in" aria-modal="true" role="dialog">
            <div className="bg-white rounded-xl shadow-2xl w-full max-w-lg h-[90vh] sm:h-[85vh] flex flex-col">
                <header className="p-4 border-b border-gray-200 bg-white rounded-t-xl z-10">
                    <div className="flex justify-between items-center">
                        <h2 className="text-lg font-bold text-gray-800">{T.discussionTitle}</h2>
                        <div className="flex items-center gap-2">
                            {initialHistory && initialHistory.length > 0 && (
                                <span className="hidden sm:inline-block text-xs text-green-600 bg-green-50 px-2 py-1 rounded-full font-medium border border-green-100">
                                    History Restored
                                </span>
                            )}

                            <div className="relative" ref={shareMenuRef}>
                                <button 
                                    onClick={() => setShowShareMenu(!showShareMenu)}
                                    className="p-1.5 text-gray-500 hover:text-brand-blue hover:bg-gray-100 rounded-full transition"
                                    title={T.shareDiscussion}
                                >
                                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8.684 13.342C8.886 12.938 9 12.482 9 12c0-.482-.114-.938-.316-1.342m0 2.684a3 3 0 110-2.684m0 2.684l6.632 3.316m-6.632-6l6.632-3.316m0 0a3 3 0 105.367-2.684 3 3 0 00-5.367 2.684zm0 9.316a3 3 0 105.368 2.684 3 3 0 00-5.368-2.684z" />
                                    </svg>
                                </button>
                                {showShareMenu && (
                                    <div className="absolute right-0 mt-2 w-48 bg-white rounded-md shadow-lg border border-gray-200 z-20 animate-fade-in">
                                        <ul className="py-1">
                                            <li>
                                                <button onClick={handleCopyTranscript} className="w-full text-left px-4 py-2 text-sm text-gray-700 hover:bg-gray-100 flex items-center gap-2">
                                                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 5H6a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2v-1M8 5a2 2 0 002 2h2a2 2 0 002-2M8 5a2 2 0 012-2h2a2 2 0 012 2m0 0h2a2 2 0 012 2v3m2 4H10m0 0l3-3m-3 3l3 3"></path></svg>
                                                    {T.copyTranscript}
                                                </button>
                                            </li>
                                            <li>
                                                <button onClick={handleDownloadTranscript} className="w-full text-left px-4 py-2 text-sm text-gray-700 hover:bg-gray-100 flex items-center gap-2">
                                                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4"></path></svg>
                                                    {T.downloadTranscript}
                                                </button>
                                            </li>
                                            {navigator.share && (
                                                <li>
                                                    <button onClick={handleNativeShare} className="w-full text-left px-4 py-2 text-sm text-gray-700 hover:bg-gray-100 flex items-center gap-2">
                                                        <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8"></path></svg>
                                                        {T.shareNative}
                                                    </button>
                                                </li>
                                            )}
                                        </ul>
                                    </div>
                                )}
                            </div>

                            <button onClick={onClose} className="text-gray-400 hover:text-gray-600 transition" aria-label="Close">
                                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg>
                            </button>
                        </div>
                    </div>
                    <p className="text-sm text-gray-600 mt-1 font-semibold truncate">{topic.aspect}</p>
                    <p className="text-xs text-gray-500 mt-1 truncate">{topic.consideration}</p>
                </header>

                <main className="p-4 overflow-y-auto flex-grow bg-gray-50/50">
                    <div className="space-y-4 pb-2">
                        {messages.map((msg, index) => (
                            <div key={index} className={`flex items-end gap-2 ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                                {msg.role === 'model' && <div className="w-6 h-6 bg-brand-blue text-white rounded-full flex items-center justify-center flex-shrink-0 text-xs font-bold">AI</div>}
                                <div className={`max-w-xs md:max-w-sm px-4 py-2 rounded-2xl text-sm ${msg.role === 'user' ? 'bg-brand-blue text-white rounded-br-none' : msg.role === 'model' ? 'bg-gray-200 text-brand-text rounded-bl-none' : 'text-center w-full text-gray-500 italic'}`}>
                                    {msg.role === 'model' ? (
                                        <MarkdownRenderer content={msg.text} />
                                    ) : (
                                        <p className="whitespace-pre-wrap">{msg.text}</p>
                                    )}
                                     {msg.diagramData && (
                                        <div className="mt-2 h-64 w-full rounded-lg border border-gray-300 bg-white">
                                            <InteractiveDiagram data={msg.diagramData} />
                                        </div>
                                    )}
                                </div>
                            </div>
                        ))}
                        {isLoading && (
                            <div className="flex items-end gap-2 justify-start">
                                <div className="w-6 h-6 bg-brand-blue text-white rounded-full flex items-center justify-center flex-shrink-0 text-xs font-bold">AI</div>
                                <div className="px-4 py-3 bg-gray-200 rounded-2xl rounded-bl-none">
                                    <LoadingSpinner />
                                </div>
                            </div>
                        )}
                         <div ref={messagesEndRef} />
                    </div>
                </main>

                <footer className="p-4 border-t border-gray-200 bg-white rounded-b-xl z-10">
                    {micError && (
                        <div className="mb-2 text-xs text-red-600 flex items-start gap-1 bg-red-50 p-2 rounded border border-red-100 animate-fade-in">
                            <svg className="h-4 w-4 flex-shrink-0 mt-0.5" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7 4a1 1 0 11-2 0 1 1 0 012 0zm-1-9a1 1 0 00-1 1v4a1 1 0 102 0V6a1 1 0 00-1-1z" clipRule="evenodd"></path></svg>
                            <span className="leading-tight">{micError}</span>
                        </div>
                    )}
                    {isGeneratingDiagram && (
                        <form onSubmit={handleGenerateDiagram} className="p-2 border border-gray-200 rounded-lg mb-2 bg-gray-50 animate-fade-in">
                            <label htmlFor="diagram-prompt" className="text-xs font-semibold text-gray-600">Describe the diagram or graph you want to see:</label>
                            <div className="flex items-center gap-2 mt-1">
                                <input
                                    id="diagram-prompt"
                                    type="text"
                                    value={diagramPrompt}
                                    onChange={(e) => setDiagramPrompt(e.target.value)}
                                    placeholder={T.diagramPlaceholder}
                                    className="flex-grow p-1.5 border border-gray-300 rounded-md text-sm text-black"
                                    autoFocus
                                />
                                <button type="submit" disabled={isLoading || !diagramPrompt.trim()} className="bg-green-600 hover:bg-green-700 text-white font-bold py-1.5 px-3 rounded-md transition text-sm disabled:bg-gray-400">
                                    Generate
                                </button>
                                 <button type="button" onClick={() => setIsGeneratingDiagram(false)} className="text-gray-500 hover:text-gray-700 text-sm">
                                    {T.cancelButton}
                                </button>
                            </div>
                        </form>
                    )}
                    <form onSubmit={handleSendMessage} className="flex items-center gap-2 mb-3">
                         <button
                            type="button"
                            onClick={() => setIsGeneratingDiagram(prev => !prev)}
                            disabled={isLoading}
                            title="Generate a diagram"
                            className="p-2 rounded-md border border-gray-300 bg-white hover:bg-gray-100 text-gray-600 transition disabled:bg-gray-200 disabled:cursor-not-allowed flex-shrink-0"
                        >
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                                <path d="M15 8a3 3 0 10-2.977-2.63l-4.94 2.47a3 3 0 100 4.319l4.94 2.47a3 3 0 10.895-1.789l-4.94-2.47a3.027 3.027 0 000-.74l4.94-2.47C13.456 7.68 14.19 8 15 8z" />
                            </svg>
                        </button>
                        {isSpeechRecognitionSupported && (
                            <button
                                type="button"
                                onClick={handleMicClick}
                                disabled={isLoading}
                                className={`flex items-center gap-1.5 px-3 py-2 rounded-md border transition flex-shrink-0 ${isListening ? 'text-red-500 border-red-500 bg-red-50 animate-pulse shadow-inner' : 'text-gray-600 border-gray-300 bg-white hover:bg-gray-100 shadow-sm'}`}
                                title="Speech to Text"
                            >
                                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                                    <path fillRule="evenodd" d="M7 4a3 3 0 016 0v4a3 3 0 11-6 0V4zm-1 4a4 4 0 108 0V4a4 4 0 10-8 0v4zM2 11a1 1 0 011-1h1a1 1 0 011 1v.5a.5.5 0 001 0V11a3 3 0 013-3h0a3 3 0 013 3v.5a.5.5 0 001 0V11a1 1 0 011 1h1a1 1 0 110 2h-1a1 1 0 01-1-1v-.5a2.5 2.5 0 00-5 0v.5a1 1 0 01-1 1H3a1 1 0 01-1-1v-2z" clipRule="evenodd" />
                                </svg>
                                <span className="hidden sm:inline text-xs font-bold uppercase tracking-tight">Voice</span>
                            </button>
                        )}
                        <input
                            type="text"
                            value={userInput}
                            onChange={(e) => setUserInput(e.target.value)}
                            placeholder={T.chatPlaceholder}
                            disabled={isLoading}
                            className="flex-grow p-2 border border-gray-300 rounded-md focus:ring-2 focus:ring-brand-blue-light focus:border-brand-blue-light transition w-full bg-gray-50 text-black"
                        />
                        <button type="submit" disabled={isLoading || !userInput.trim()} className="bg-brand-blue hover:bg-blue-800 text-white font-bold p-2 rounded-md transition disabled:bg-gray-400 disabled:cursor-not-allowed flex-shrink-0">
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                                <path d="M10.894 2.553a1 1 0 00-1.788 0l-7 14a1 1 0 001.169 1.409l5-1.428A1 1 0 0010 16h.008a1 1 0 00.724-.316l5-5a1 1 0 00.316-.724V4a1 1 0 00-1-1h-2a1 1 0 00-1 1v.008a1 1 0 00.316.724l-3 3.428z" />
                            </svg>
                        </button>
                    </form>
                    <div className="flex justify-between items-center pt-3 border-t border-gray-100">
                        <span className="text-xs text-gray-400 italic">
                            {isSaved ? "Discussion saved to case." : "Unsaved discussion."}
                        </span>
                        <button 
                            type="button"
                            onClick={handleSave}
                            disabled={isLoading}
                            className={`text-xs px-4 py-2 rounded-md transition font-medium border flex items-center gap-1 shadow-sm ${isSaved ? 'text-green-700 bg-green-50 border-green-200' : 'text-brand-blue bg-blue-50 hover:bg-blue-100 border-blue-200'}`}
                        >
                            {isSaved ? (
                                <>
                                    <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7"></path></svg>
                                    Saved
                                </>
                            ) : (
                                <>
                                    <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 7H5a2 2 0 00-2 2v9a2 2 0 002 2h14a2 2 0 002-2V9a2 2 0 00-2-2h-3m-1 4l-3 3m0 0l-3-3m3 3V4"></path></svg>
                                    Save Discussion
                                </>
                            )}
                        </button>
                    </div>
                </footer>
            </div>
        </div>
    );
};

import React, { useState, useEffect, useRef } from 'react';

interface ControlPanelProps {
  onGenerate: (condition: string, discipline: string, difficulty: string) => void;
  disabled: boolean;
  T: Record<string, any>;
  language: string;
  onSaveCase: () => void;
  onOpenSavedWork: () => void;
  onOpenClinicalTools: () => void;
  isCaseActive: boolean;
  onGenerateNew: () => void;
  mobileView: 'case' | 'map';
  onSetMobileView: (view: 'case' | 'map') => void;
}

const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
const isSpeechRecognitionSupported = !!SpeechRecognition;

const MicButton: React.FC<{ onClick: () => void, isListening: boolean, disabled: boolean, title: string }> = ({ onClick, isListening, disabled, title }) => {
    return (
        <button 
            type="button" 
            onClick={onClick} 
            disabled={disabled} 
            title={title}
            className="absolute right-0 top-0 h-full px-2.5 flex items-center text-gray-400 hover:text-brand-blue-light disabled:text-gray-300 disabled:cursor-not-allowed transition-colors"
        >
            {isListening ? (
                 <svg className="h-5 w-5 text-red-500 animate-pulse" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor">
                    <path d="M10 18a8 8 0 100-16 8 8 0 000 16zM8 8a2 2 0 00-2 2v.001a2 2 0 002 2h4a2 2 0 002-2V10a2 2 0 00-2-2H8z" />
                </svg>
            ) : (
                <svg className="h-5 w-5" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor">
                    <path fillRule="evenodd" d="M7 4a3 3 0 016 0v4a3 3 0 11-6 0V4zm-1 4a4 4 0 108 0V4a4 4 0 10-8 0v4zM2 11a1 1 0 011-1h1a1 1 0 011 1v.5a.5.5 0 001 0V11a3 3 0 013-3h0a3 3 0 013 3v.5a.5.5 0 001 0V11a1 1 0 011 1h1a1 1 0 110 2h-1a1 1 0 01-1-1v-.5a2.5 2.5 0 00-5 0v.5a1 1 0 01-1 1H3a1 1 0 01-1-1v-2z" clipRule="evenodd" />
                </svg>
            )}
        </button>
    );
};

export const ControlPanel: React.FC<ControlPanelProps> = ({ 
    onGenerate, disabled, T, language, onSaveCase, onOpenSavedWork, 
    onOpenClinicalTools, isCaseActive, onGenerateNew, mobileView, onSetMobileView 
}) => {
  const [conditionInput, setConditionInput] = useState("Type 2 Diabetes Mellitus");
  const [disciplineInput, setDisciplineInput] = useState("Medicine");
  const [difficulty, setDifficulty] = useState("intermediate");
  const [history, setHistory] = useState<{ condition: string; discipline: string }[]>([]);
  const [showHistory, setShowHistory] = useState(false);
  const historyRef = useRef<HTMLDivElement>(null);

  const [isListening, setIsListening] = useState(false);
  const [activeInput, setActiveInput] = useState<'condition' | 'discipline' | null>(null);
  const recognitionRef = useRef<any>(null);
  const [micError, setMicError] = useState<string | null>(null);

  const [isSavedWorkMenuOpen, setIsSavedWorkMenuOpen] = useState(false);
  const savedWorkMenuRef = useRef<HTMLDivElement>(null);


  useEffect(() => {
    try {
      const storedHistory = JSON.parse(localStorage.getItem('generationHistory') || '[]');
      if (Array.isArray(storedHistory)) {
        setHistory(storedHistory);
      }
    } catch (e) {
      console.error("Failed to parse history from localStorage", e);
      setHistory([]);
    }
  }, []);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
        if (historyRef.current && !historyRef.current.contains(event.target as Node)) {
            setShowHistory(false);
        }
        if (savedWorkMenuRef.current && !savedWorkMenuRef.current.contains(event.target as Node)) {
            setIsSavedWorkMenuOpen(false);
        }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => {
        document.removeEventListener("mousedown", handleClickOutside);
    };
  }, []);

  const handleMicClick = (targetInput: 'condition' | 'discipline') => {
      if (!isSpeechRecognitionSupported) return;

      if (isListening && activeInput === targetInput && recognitionRef.current) {
          recognitionRef.current.stop();
          return;
      }

      setMicError(null);
      setActiveInput(targetInput);

      // Create a FRESH instance per click for better "not-allowed" error handling & cross-browser compatibility
      const recognition = new SpeechRecognition();
      recognition.continuous = false;
      recognition.interimResults = false;
      // ChiBemba fallback to English
      recognition.lang = language === 'bem' ? 'en-US' : language;

      recognition.onstart = () => {
          setIsListening(true);
      };

      recognition.onend = () => {
          setIsListening(false);
          setActiveInput(null);
          recognitionRef.current = null;
      };

      recognition.onerror = (event: any) => {
          console.error('Main Mic Error:', event.error);
          if (event.error === 'not-allowed' || event.error === 'service-not-allowed') {
              setMicError(T.micPermissionError);
          } else {
              setMicError(T.micGenericError);
          }
          setIsListening(false);
          setActiveInput(null);
      };

      recognition.onresult = (event: any) => {
          const transcript = event.results[0][0].transcript;
          if (targetInput === 'condition') {
              setConditionInput(transcript);
          } else if (targetInput === 'discipline') {
              setDisciplineInput(transcript);
          }
      };

      try {
          recognitionRef.current = recognition;
          recognition.start();
      } catch (err: any) {
          console.error("Mic start failed:", err);
          setMicError(T.micGenericError);
          setIsListening(false);
          setActiveInput(null);
      }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const condition = conditionInput.trim();
    const discipline = disciplineInput.trim();
    if (condition && discipline && !disabled) {
      onGenerate(condition, discipline, difficulty);

      setHistory(prevHistory => {
        const newEntry = { condition, discipline };
        const isDuplicate = prevHistory.some(
          item => item.condition.toLowerCase() === newEntry.condition.toLowerCase() && item.discipline.toLowerCase() === newEntry.discipline.toLowerCase()
        );
        if (isDuplicate) return prevHistory;

        const updatedHistory = [newEntry, ...prevHistory].slice(0, 15); // Keep last 15 unique entries
        localStorage.setItem('generationHistory', JSON.stringify(updatedHistory));
        return updatedHistory;
      });
    }
  };

  const handleSelectHistory = (item: { condition: string; discipline: string }) => {
    setConditionInput(item.condition);
    setDisciplineInput(item.discipline);
    setShowHistory(false);
  };

  const handleClearHistory = () => {
    setHistory([]);
    localStorage.removeItem('generationHistory');
    setShowHistory(false);
  };

  return (
    <div className="bg-white p-4 rounded-lg shadow-md border border-gray-200">
      {!isCaseActive ? (
        <>
            <form onSubmit={handleSubmit} className="flex flex-col sm:flex-row sm:flex-wrap gap-4 sm:items-end">
            <div className="flex flex-col sm:flex-1 sm:min-w-[240px]">
                <label htmlFor="condition-input" className="font-semibold text-gray-700 text-sm mb-1">
                    {T.conditionLabel}
                </label>
                <div className="relative">
                    <input
                    type="text"
                    id="condition-input"
                    value={conditionInput}
                    onChange={(e) => setConditionInput(e.target.value)}
                    disabled={disabled}
                    placeholder={T.conditionPlaceholder}
                    className="p-2 border border-gray-300 rounded-md focus:ring-2 focus:ring-brand-blue-light focus:border-brand-blue-light transition w-full bg-gray-50 text-black pr-10"
                    />
                    {isSpeechRecognitionSupported && (
                        <MicButton
                            onClick={() => handleMicClick('condition')}
                            isListening={isListening && activeInput === 'condition'}
                            disabled={disabled || (isListening && activeInput !== 'condition')}
                            title="Use voice input for condition"
                        />
                    )}
                </div>
            </div>

            <div className="flex flex-col sm:flex-1 sm:min-w-[240px]">
                <label htmlFor="discipline-input" className="font-semibold text-gray-700 text-sm mb-1">
                    {T.disciplineLabel}
                </label>
                <div className="relative">
                    <input
                    type="text"
                    id="discipline-input"
                    value={disciplineInput}
                    onChange={(e) => setDisciplineInput(e.target.value)}
                    disabled={disabled}
                    placeholder={T.disciplinePlaceholder}
                    className="p-2 border border-gray-300 rounded-md focus:ring-2 focus:ring-brand-blue-light focus:border-brand-blue-light transition w-full bg-gray-50 text-black pr-10"
                    />
                    {isSpeechRecognitionSupported && (
                        <MicButton
                            onClick={() => handleMicClick('discipline')}
                            isListening={isListening && activeInput === 'discipline'}
                            disabled={disabled || (isListening && activeInput !== 'discipline')}
                            title="Use voice input for discipline"
                        />
                    )}
                </div>
            </div>

            <div className="flex flex-col w-full sm:w-auto">
                <label htmlFor="difficulty-select" className="font-semibold text-gray-700 text-sm mb-1">
                {T.difficultyLabel}
                </label>
                <div className="relative">
                <select
                    id="difficulty-select"
                    value={difficulty}
                    onChange={(e) => setDifficulty(e.target.value)}
                    disabled={disabled}
                    className="appearance-none w-full bg-gray-50 p-2 border border-gray-300 rounded-md focus:ring-2 focus:ring-brand-blue-light focus:border-brand-blue-light transition h-[42px] pr-8 text-black"
                >
                    <option value="beginner">{T.difficultyBeginner}</option>
                    <option value="intermediate">{T.difficultyIntermediate}</option>
                    <option value="advanced">{T.difficultyAdvanced}</option>
                </select>
                <div className="pointer-events-none absolute inset-y-0 right-0 flex items-center px-2 text-gray-700">
                    <svg className="fill-current h-4 w-4" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20"><path d="M9.293 12.95l.707.707L15.657 8l-1.414-1.414L10 10.828 5.757 6.586 4.343 8z"/></svg>
                </div>
                </div>
            </div>

            <div className="w-full sm:w-auto flex items-end space-x-2">
                <div className="relative" ref={historyRef}>
                    <button
                        type="button"
                        onClick={() => setShowHistory(s => !s)}
                        disabled={disabled}
                        title={T.historyButtonTitle}
                        aria-label={T.historyButtonTitle}
                        className="h-[42px] bg-gray-100 hover:bg-gray-200 text-gray-700 font-bold p-2 rounded-md transition duration-300 ease-in-out disabled:bg-gray-300 disabled:cursor-not-allowed flex items-center justify-center"
                    >
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                        <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm1-12a1 1 0 10-2 0v4a1 1 0 00.293.707l2.828 2.829a1 1 0 101.414-1.415L11 9.586V6z" clipRule="evenodd" />
                        </svg>
                    </button>
                    {showHistory && (
                        <div className="absolute bottom-full mb-2 right-0 w-80 bg-white rounded-lg shadow-2xl border border-gray-200 z-20 max-h-80 overflow-y-auto animate-fade-in">
                            <div className="p-3 border-b border-gray-200 flex justify-between items-center sticky top-0 bg-white">
                                <h4 className="font-semibold text-gray-800">{T.historyTitle}</h4>
                                {history.length > 0 && (
                                    <button onClick={handleClearHistory} className="text-xs text-red-500 hover:text-red-700 font-medium">{T.clearHistoryButton}</button>
                                )}
                            </div>
                            {history.length === 0 ? (
                                <p className="p-4 text-sm text-gray-500 text-center">{T.noHistoryMessage}</p>
                            ) : (
                                <ul className="divide-y divide-gray-100">
                                    {history.map((item, index) => (
                                        <li key={index} onClick={() => handleSelectHistory(item)} className="p-3 hover:bg-gray-50 cursor-pointer transition">
                                            <p className="font-medium text-sm text-gray-800 truncate">{item.condition}</p>
                                            <p className="text-xs text-gray-500 truncate">{item.discipline}</p>
                                        </li>
                                    ))}
                                </ul>
                            )}
                        </div>
                    )}
                </div>
                <button
                    type="submit"
                    disabled={disabled || !conditionInput.trim() || !disciplineInput.trim()}
                    className="flex-grow h-[42px] bg-brand-blue hover:bg-blue-800 text-white font-bold py-2 px-4 rounded-md transition duration-300 ease-in-out disabled:bg-gray-400 disabled:cursor-not-allowed flex items-center justify-center space-x-2"
                >
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 3v2m6-2v2M9 19v2m6-2v2M5 9H3m2 6H3m18-6h-2m2 6h-2M12 6V3m0 18v-3"></path></svg>
                    <span>{T.generateButton}</span>
                </button>
            </div>
            </form>
            {micError && (
                <div className="mt-2 text-xs text-red-600 flex items-center gap-1">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 flex-shrink-0" viewBox="0 0 20 20" fill="currentColor">
                        <path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7 4a1 1 0 11-2 0 1 1 0 012 0zm-1-9a1 1 0 00-1 1v4a1 1 0 102 0V6a1 1 0 00-1-1z" clipRule="evenodd" />
                    </svg>
                    <span>{micError}</span>
                </div>
            )}
        </>
      ) : (
        <div className="flex items-center justify-between">
            <div className="flex flex-wrap items-center gap-2">
                <div className="relative" ref={savedWorkMenuRef}>
                    <button
                        onClick={() => setIsSavedWorkMenuOpen(prev => !prev)}
                        disabled={disabled}
                        title={T.savedWorkButton}
                        className="bg-gray-600 hover:bg-gray-700 text-white font-bold py-2 px-2 sm:px-4 rounded-md transition duration-300 ease-in-out disabled:bg-gray-400 disabled:cursor-not-allowed flex items-center justify-center sm:space-x-2 text-sm"
                    >
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                            <path d="M2 6a2 2 0 012-2h5l2 2h5a2 2 0 012 2v6a2 2 0 01-2 2H4a2 2 0 01-2-2V6z" />
                        </svg>
                        <span className="hidden sm:inline">{T.savedWorkButton}</span>
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 hidden sm:inline" viewBox="0 0 20 20" fill="currentColor">
                            <path fillRule="evenodd" d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z" clipRule="evenodd" />
                        </svg>
                    </button>
                    {isSavedWorkMenuOpen && (
                        <div className="absolute top-full mt-2 left-0 w-56 bg-white rounded-md shadow-lg border border-gray-200 z-20 animate-fade-in">
                            <ul className="py-1">
                                <li>
                                    <button
                                        onClick={() => { onSaveCase(); setIsSavedWorkMenuOpen(false); }}
                                        disabled={disabled || !isCaseActive}
                                        title={!isCaseActive ? T.saveCaseDisabledTooltip : T.saveCaseButton}
                                        className="w-full text-left px-4 py-2 text-sm text-gray-700 hover:bg-gray-100 disabled:text-gray-400 disabled:cursor-not-allowed flex items-center space-x-3"
                                    >
                                        <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                                            <path d="M5 4a2 2 0 012-2h6a2 2 0 012 2v12a1 1 0 01-1.447.894L10 14.586l-3.553 2.308A1 1 0 015 16V4z" />
                                        </svg>
                                        <span>{T.saveCaseButton}</span>
                                    </button>
                                </li>
                                <li>
                                    <button
                                        onClick={() => { onOpenSavedWork(); setIsSavedWorkMenuOpen(false); }}
                                        disabled={disabled}
                                        className="w-full text-left px-4 py-2 text-sm text-gray-700 hover:bg-gray-100 disabled:text-gray-400 flex items-center space-x-3"
                                    >
                                        <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                                            <path fillRule="evenodd" d="M2 5a2 2 0 012-2h12a2 2 0 012 2v10a2 2 0 01-2 2H4a2 2 0 01-2-2V5zm2-1a1 1 0 00-1 1v10a1 1 0 001 1h12a1 1 0 001-1V5a1 1 0 00-1-1H4z" clipRule="evenodd" />
                                            <path d="M6 9a1 1 0 011-1h6a1 1 0 110 2H7a1 1 0 01-1-1z" />
                                        </svg>
                                        <span>{T.viewSavedWorkButton}</span>
                                    </button>
                                </li>
                            </ul>
                        </div>
                    )}
                </div>
                <button
                onClick={onOpenClinicalTools}
                disabled={disabled}
                title={T.clinicalToolsButton}
                className="bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-2 px-2 sm:px-4 rounded-md transition duration-300 ease-in-out disabled:bg-gray-400 disabled:cursor-not-allowed flex items-center justify-center sm:space-x-2 text-sm"
                >
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                        <path fillRule="evenodd" d="M11.49 3.17c-.38-1.56-2.6-1.56-2.98 0a1.532 1.532 0 01-2.286.948c-1.372-.836-2.942.734-2.106 2.106.54.886.061 2.042-.947 2.287-1.561.379-1.561 2.6 0 2.978a1.532 1.532 0 01.947 2.287c-.836 1.372.734 2.942 2.106 2.106a1.532 1.532 0 012.287.947c.379 1.561 2.6 1.561 2.978 0a1.532 1.532 0 012.287-.947c1.372.836 2.942-.734 2.106-2.106a1.532 1.532 0 01-.947-2.287c1.561-.379-1.561-2.6 0-2.978a1.532 1.532 0 01.947-2.287c.836-1.372-.734-2.942-2.106-2.106a1.532 1.532 0 01-2.287-.947zM10 13a3 3 0 100-6 3 3 0 000 6z" clipRule="evenodd" />
                    </svg>
                <span className="hidden sm:inline">{T.clinicalToolsButton}</span>
                </button>
            </div>

            <div className="lg:hidden">
                <div className="flex items-center bg-gray-200 p-0.5 rounded-full">
                    <button
                        onClick={() => onSetMobileView('case')}
                        aria-pressed={mobileView === 'case'}
                        aria-label={T.caseTab}
                        className={`p-1.5 rounded-full transition-colors ${mobileView === 'case' ? 'bg-white text-brand-blue shadow-sm' : 'text-gray-500'}`}
                    >
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" /></svg>
                    </button>
                    <button
                        onClick={() => onSetMobileView('map')}
                        aria-pressed={mobileView === 'map'}
                        aria-label={T.mapTab}
                        className={`p-1.5 rounded-full transition-colors ${mobileView === 'map' ? 'bg-white text-brand-blue shadow-sm' : 'text-gray-500'}`}
                    >
