export const KnowledgeMap = forwardRef<any, KnowledgeMapProps>(({
    data, onNodeClick, selectedNodeInfo, onClearSelection, isMapFullscreen, setIsMapFullscreen, caseTitle, language, T, onDiscussNode
}, ref) => {
    const svgRef = useRef<SVGSVGElement | null>(null);
    const containerRef = useRef<HTMLDivElement | null>(null);
    const simulationRef = useRef<any>(null);
    const zoomRef = useRef<any>(null);
    const gRef = useRef<any>(null);

    const nodes = useMemo(() => data.nodes.map(n => ({ ...n })), [data.nodes]);
    const links = useMemo(() => data.links.map(l => ({ ...l })), [data.links]);

    useImperativeHandle(ref, () => ({
        async captureAsImage() { return svgRef.current ? await svgToDataURL(svgRef.current) : ''; }
    }));

    const resetZoom = useCallback(() => {
        if (!svgRef.current || !gRef.current || !containerRef.current || !zoomRef.current) return;
        const svg = d3.select(svgRef.current);
        const { width, height } = containerRef.current.getBoundingClientRect();
        const bounds = gRef.current.node().getBBox();
        if (bounds.width === 0) return;
        const scale = 0.8 / Math.max(bounds.width / width, bounds.height / height);
        const transform = d3.zoomIdentity.translate(width/2 - scale*(bounds.x+bounds.width/2), height/2 - scale*(bounds.y+bounds.height/2)).scale(scale);
        svg.transition().duration(750).call(zoomRef.current.transform, transform);
    }, []);

    useEffect(() => {
        if (!svgRef.current || !containerRef.current) return;
        const { width, height } = containerRef.current.getBoundingClientRect();
        const svg = d3.select(svgRef.current);
        svg.selectAll('*').remove();
        const g = svg.append('g');
        gRef.current = g;

        const zoom = d3.zoom().scaleExtent([0.1, 4]).on('zoom', (e: any) => g.attr('transform', e.transform));
        zoomRef.current = zoom;
        svg.call(zoom).on("click", onClearSelection);

        simulationRef.current = d3.forceSimulation(nodes)
            .force('link', d3.forceLink(links).id((d: any) => d.id).distance(200))
            .force('charge', d3.forceManyBody().strength(-1500))
            .force('center', d3.forceCenter(width / 2, height / 2))
            .force('collide', d3.forceCollide().radius(70));

        const linkLines = g.append("g").selectAll("line").data(links).join("line").attr("stroke", "#cbd5e1").attr("stroke-width", 2);

        const node = g.append('g').selectAll('g').data(nodes).join('g').attr('class', 'cursor-pointer')
            .on('click', (e: any, d: any) => { e.stopPropagation(); onNodeClick(d); })
            .call(d3.drag().on('start', (e: any, d: any) => { if (!e.active) simulationRef.current.alphaTarget(0.3).restart(); d.fx = d.x; d.fy = d.y; }).on('drag', (e: any, d: any) => { d.fx = e.x; d.fy = e.y; }).on('end', (e: any, d: any) => { if (!e.active) simulationRef.current.alphaTarget(0); d.fx = null; d.fy = null; }));

        node.append('circle').attr('r', 16)
            .attr('fill', (d: any) => DisciplineColors[d.discipline] || '#94a3b8')
            .attr('stroke', '#fff').attr('stroke-width', 2);

        node.append('text').text((d: any) => d.label).attr('x', 20).attr('y', 5).attr('font-size', '14px').attr('font-weight', 'bold').attr('fill', '#334155').style("text-shadow", "0 0 4px #fff");

        simulationRef.current.on('tick', () => {
            linkLines.attr('x1', (d: any) => d.source.x).attr('y1', (d: any) => d.source.y).attr('x2', (d: any) => d.target.x).attr('y2', (d: any) => d.target.y);
            node.attr('transform', (d: any) => `translate(${d.x}, ${d.y})`);
        });

        setTimeout(resetZoom, 500);
        return () => simulationRef.current.stop();
    }, [data, nodes, links, resetZoom]);

    return (
        <div ref={containerRef} className={`w-full h-full bg-slate-50 border border-gray-200 overflow-hidden ${isMapFullscreen ? 'fixed inset-0 z-50' : 'relative rounded-xl shadow-inner'}`}>
            <svg ref={svgRef} className="w-full h-full"></svg>
            <MapControls onZoomIn={() => d3.select(svgRef.current).transition().call(zoomRef.current.scaleBy, 1.3)} onZoomOut={() => d3.select(svgRef.current).transition().call(zoomRef.current.scaleBy, 0.7)} onReset={resetZoom} onToggleFullscreen={() => setIsMapFullscreen(!isMapFullscreen)} isFullscreen={isMapFullscreen} />
            {selectedNodeInfo && <ConceptCard nodeInfo={selectedNodeInfo} onClose={onClearSelection} onDiscuss={onDiscussNode} T={T} />}
        </div>
    );
});

