declare const d3: any;

const DisciplineColors: Record<string, string> = {
    "Biochemistry": '#4A90E2',
    "Pharmacology": '#50E3C2',
    "Physiology": '#B8E986',
    "Psychology": '#F5A623',
    "Sociology": '#F8E71C',
    "Pathology": '#D0021B',
    "Immunology": '#BD10E0',
    "Genetics": '#9013FE',
    "Diagnostics": '#417505',
    "Treatment": '#7ED321',
    "Physiotherapy": '#E0A410',
    "Occupational Therapy": '#03A9F4',
};

interface KnowledgeMapProps {
    data: KnowledgeMapData;
    onNodeClick: (node: KnowledgeNode) => void;
    selectedNodeInfo: { node: KnowledgeNode; abstract: string; loading: boolean } | null;
    onClearSelection: () => void;
    isMapFullscreen: boolean;
    setIsMapFullscreen: (val: boolean) => void;
    caseTitle: string;
    language: string;
    T: Record<string, any>;
}

export const KnowledgeMap = forwardRef<any, KnowledgeMapProps>(({
    data, onNodeClick, selectedNodeInfo, onClearSelection, isMapFullscreen, setIsMapFullscreen, T
}, ref) => {
    const svgRef = useRef<SVGSVGElement | null>(null);
    const containerRef = useRef<HTMLDivElement | null>(null);
    const simulationRef = useRef<any>(null);
    const gRef = useRef<any>(null);

    const nodes = useMemo(() => data.nodes.map(n => ({ ...n })), [data.nodes]);
    const links = useMemo(() => data.links.map(l => ({ ...l })), [data.links]);

    useImperativeHandle(ref, () => ({
        async captureAsImage() { return ''; }
    }));

    useEffect(() => {
        if (!svgRef.current || !containerRef.current) return;
        const { width, height } = containerRef.current.getBoundingClientRect();
        const svg = d3.select(svgRef.current);
        svg.selectAll('*').remove();
        const g = svg.append('g');
        gRef.current = g;

        simulationRef.current = d3.forceSimulation(nodes)
            .force('link', d3.forceLink(links).id((d: any) => d.id).distance(150))
            .force('charge', d3.forceManyBody().strength(-1000))
            .force('center', d3.forceCenter(width / 2, height / 2));

        const linkLines = g.append("g").selectAll("line").data(links).join("line").attr("stroke", "#cbd5e1").attr("stroke-width", 2);

        const node = g.append('g').selectAll('g').data(nodes).join('g').attr('class', 'cursor-pointer').on('click', (e: any, d: any) => { e.stopPropagation(); onNodeClick(d); });

        node.append('circle').attr('r', 15).attr('fill', (d: any) => DisciplineColors[d.discipline] || '#94a3b8');
        node.append('text').text((d: any) => d.label).attr('x', 18).attr('y', 4).attr('font-size', '12px');

        simulationRef.current.on('tick', () => {
            linkLines.attr('x1', (d: any) => d.source.x).attr('y1', (d: any) => d.source.y).attr('x2', (d: any) => d.target.x).attr('y2', (d: any) => d.target.y);
            node.attr('transform', (d: any) => `translate(${d.x}, ${d.y})`);
        });

        return () => simulationRef.current.stop();
    }, [data, nodes, links]);

    return (
        <div ref={containerRef} className={`w-full h-full bg-slate-50 border border-gray-200 overflow-hidden relative rounded-xl`}>
            <svg ref={svgRef} className="w-full h-full"></svg>
            {selectedNodeInfo && <ConceptCard nodeInfo={selectedNodeInfo} onClose={onClearSelection} T={T} />}
        </div>
    );
});

