                            const diagramMatch = msg.text.match(/\[DIAGRAM: (.*?)\]/);
                            const graphMatch = msg.text.match(/\[GRAPH: (.*?)\]/);

                            const textWithoutTags = msg.text
                                .replace(/\[ILLUSTRATE:.*?\]/g, '')
                                .replace(/\[DIAGRAM:.*?\]/g, '')
                                .replace(/\[GRAPH:.*?\]/g, '')
                                .trim();

