interface KnowledgeMapProps {
    data: KnowledgeMapData;
    onNodeClick: (node: KnowledgeNode) => void;
    selectedNodeInfo: { node: KnowledgeNode; abstract: string; loading: boolean } | null;
    onClearSelection: () => void;
    isMapFullscreen: boolean;
    setIsMapFullscreen: (isFullscreen: boolean) => void;
    caseTitle: string;
    language: string;
    T: Record<string, any>;
    onDiscussNode: (nodeInfo: { node: KnowledgeNode; abstract: string; loading: boolean }) => void;
}

export const KnowledgeMap = forwardRef<any, KnowledgeMapProps>(({
    data,
    onNodeClick,
    selectedNodeInfo,
    onClearSelection,
    isMapFullscreen,
    setIsMapFullscreen,
    caseTitle,
    language,
    T,
    onDiscussNode
}, ref) => {
    const svgRef = useRef<SVGSVGElement | null>(null);
    const containerRef = useRef<HTMLDivElement | null>(null);
    const [isLoading, setIsLoading] = useState(true);
    const simulationRef = useRef<any>(null);
    const zoomRef = useRef<any>(null);
    const gRef = useRef<any>(null);

    const [contextMenu, setContextMenu] = useState<{ position: { x: number; y: number }; node: KnowledgeNode } | null>(null);
    const [explanationModal, setExplanationModal] = useState<{ source: KnowledgeNode; target: KnowledgeNode } | null>(null);

    const nodes = useMemo(() => data.nodes.map(n => ({ ...n })), [data.nodes]);
    const links = useMemo(() => data.links.map(l => ({ ...l })), [data.links]);

    useImperativeHandle(ref, () => ({
        async captureAsImage(): Promise<string> {
            if (svgRef.current) {
                return await svgToDataURL(svgRef.current);
            }
            return '';
        }
    }));

    const handleNodeRightClick = (event: MouseEvent, node: KnowledgeNode) => {
        event.preventDefault();
        setContextMenu({ position: { x: event.clientX, y: event.clientY }, node });
    };

    const handleExplainConnection = (targetNode: KnowledgeNode) => {
        if (contextMenu) {
            setExplanationModal({ source: contextMenu.node, target: targetNode });
        }
    };

    const resetZoom = useCallback(() => {
        if (!svgRef.current || !gRef.current || !containerRef.current || !zoomRef.current) return;
        const svg = d3.select(svgRef.current);
        const g = gRef.current;

        const bounds = g.node().getBBox();
        const parent = svg.node().parentElement;
        if (!parent) return;

        const fullWidth = parent.clientWidth;
        const fullHeight = parent.clientHeight;
        const { width, height, x, y } = bounds;

        if (width === 0 || height === 0) return;

        const midX = x + width / 2;
        const midY = y + height / 2;
        const scale = 0.85 / Math.max(width / fullWidth, height / fullHeight); // Slightly zoomed out initial view
        const translate = [fullWidth / 2 - scale * midX, fullHeight / 2 - scale * midY];

        const transform = d3.zoomIdentity.translate(translate[0], translate[1]).scale(scale);

        svg.transition().duration(750).call(zoomRef.current.transform, transform);
    }, []);

    const handleZoomIn = useCallback(() => {
        if (zoomRef.current && svgRef.current) {
            d3.select(svgRef.current).transition().duration(250).call(zoomRef.current.scaleBy, 1.2);
        }
    }, []);

    const handleZoomOut = useCallback(() => {
        if (zoomRef.current && svgRef.current) {
            d3.select(svgRef.current).transition().duration(250).call(zoomRef.current.scaleBy, 0.8);
        }
    }, []);

    useEffect(() => {
        const observer = new ResizeObserver(() => {
            resetZoom();
        });
        if (containerRef.current) {
            observer.observe(containerRef.current);
        }
        return () => {
            observer.disconnect();
        };
    }, [resetZoom]);

    useEffect(() => {
        if (!svgRef.current || !containerRef.current) return;

        setIsLoading(true);

        const svg = d3.select(svgRef.current);
        svg.selectAll('*').remove(); // Clear previous render

        const defs = svg.append("defs");

        // Define Arrow Marker
        defs.append("marker")
            .attr("id", "arrow-head-map")
            .attr("viewBox", "0 -5 10 10")
            .attr("refX", 30) // Node radius 18 + gap + stroke safety
            .attr("refY", 0)
            .attr("markerWidth", 8)
            .attr("markerHeight", 8)
            .attr("orient", "auto")
            .attr("markerUnits", "userSpaceOnUse")
            .append("path")
            .attr("d", "M0,-5L10,0L0,5")
            .attr("fill", "#9ca3af")
            .attr("fill-opacity", 0.8);

        // Define Drop Shadow Filter for pseudo-3D effect
        const filter = defs.append("filter")
            .attr("id", "drop-shadow")
            .attr("height", "140%");

        filter.append("feGaussianBlur")
            .attr("in", "SourceAlpha")
            .attr("stdDeviation", 3)
            .attr("result", "blur");

        filter.append("feOffset")
            .attr("in", "blur")
            .attr("dx", 2)
            .attr("dy", 2)
            .attr("result", "offsetBlur");

        const feMerge = filter.append("feMerge");
        feMerge.append("feMergeNode").attr("in", "offsetBlur");
        feMerge.append("feMergeNode").attr("in", "SourceGraphic");


        const { width, height } = containerRef.current.getBoundingClientRect();

        const g = svg.append('g');
        gRef.current = g;

        const zoom = d3.zoom().scaleExtent([0.1, 4]).on('zoom', (event: any) => {
            g.attr('transform', event.transform);
        });
        zoomRef.current = zoom;
        svg.call(zoom);
        svg.on("click", onClearSelection);

        // Optimized physics for reduced clutter
        simulationRef.current = d3.forceSimulation(nodes)
            .force('link', d3.forceLink(links).id((d: any) => d.id).distance(220).strength(0.3)) // Longer, slightly looser links
            .force('charge', d3.forceManyBody().strength(-2500)) // Very strong repulsion to push nodes apart
            .force('center', d3.forceCenter(width / 2, height / 2))
            .force('collide', d3.forceCollide().radius(80).iterations(3)) // High collision radius to avoid text overlap
            .on('end', () => {
                setIsLoading(false);
                resetZoom();
            });

        // --- Links (Lines) ---
        const linkLines = g.append("g")
            .attr("class", "links")
            .selectAll("line")
            .data(links)
            .join("line")
            .attr("stroke", "#9ca3af")
            .attr("stroke-opacity", 0.6)
            .attr("stroke-width", 1.5)
            .attr("marker-end", "url(#arrow-head-map)"); // Add arrows

        // --- Link Labels (Parallel text with background) ---
        const linkLabels = g.append("g")
            .attr("class", "link-labels")
            .selectAll("g")
            .data(links)
            .join("g");

        // Background pill for text readability
        linkLabels.append("rect")
            .attr("rx", 10) // Rounded corners like a pill
            .attr("ry", 10)
            .attr("fill", "white")
            .attr("fill-opacity", 0.95)
            .attr("stroke", "#e5e7eb")
            .attr("stroke-width", 1);

        // The text itself
        linkLabels.append("text")
            .text((d: any) => d.description)
            .attr("font-size", "16px") // Increased font size
            .attr("fill", "#4b5563")
            .attr("text-anchor", "middle")
            .attr("dy", "0.35em")
            .attr("font-family", "sans-serif")
            .attr("pointer-events", "none") // Click through to select links if needed
            .each(function(d: any) {
                // Calculate width for the background rect
                // @ts-ignore
                const bbox = this.getBBox();
                d.width = bbox.width + 14;
                d.height = bbox.height + 8;
            });

        // Apply dimensions to rects after text rendering
        linkLabels.select("rect")
            .attr("width", (d: any) => d.width)
            .attr("height", (d: any) => d.height)
            .attr("x", (d: any) => -d.width / 2)
            .attr("y", (d: any) => -d.height / 2);


        // --- Nodes ---
        const node = g.append('g')
            .attr("class", "nodes")
            .selectAll('g')
            .data(nodes)
            .join('g')
            .attr('class', 'node-group cursor-pointer')
            .call(d3.drag()
                .on('start', (event: any, d: any) => {
                    if (!event.active) simulationRef.current.alphaTarget(0.3).restart();
                    d.fx = d.x;
                    d.fy = d.y;
                })
                .on('drag', (event: any, d: any) => {
                    d.fx = event.x;
                    d.fy = event.y;
                })
                .on('end', (event: any, d: any) => {
                    if (!event.active) simulationRef.current.alphaTarget(0);
                    d.fx = null;
                    d.fy = null;
                }))
            .on('click', (event: MouseEvent, d: any) => {
                event.stopPropagation(); 
                onNodeClick(d);
            })
            .on('contextmenu', (event: MouseEvent, d: any) => handleNodeRightClick(event, d));

        // Main circle with shadow (Pseudo-3D)
        node.append('circle')
            .attr('r', 18) 
            .attr('fill', (d: any) => DisciplineColors[d.discipline] || '#ccc')
            .attr('stroke', '#fff')
            .attr('stroke-width', 3)
            .style("filter", "url(#drop-shadow)"); 


        // Label
        node.append('text')
            .text((d: any) => d.label)
            .attr('x', 24)
            .attr('y', 5)
            .attr("font-family", "sans-serif")
            .attr('font-size', '18px') // Increased font size
            .attr('font-weight', 'bold')
            .attr('fill', '#1f2937')
            .style("text-shadow", "2px 2px 0px #fff, -1px -1px 0 #fff, 1px -1px 0 #fff, -1px 1px 0 #fff, 1px 1px 0 #fff");

        simulationRef.current.on('tick', () => {
            // Update Lines
            linkLines
                .attr('x1', (d: any) => d.source.x)
                .attr('y1', (d: any) => d.source.y)
                .attr('x2', (d: any) => d.target.x)
                .attr('y2', (d: any) => d.target.y);

            // Update Labels (Rotation parallel to line)
            linkLabels.attr('transform', (d: any) => {
                if (!d.source.x || !d.target.x) return null;

                const dx = d.target.x - d.source.x;
                const dy = d.target.y - d.source.y;
                const x = (d.source.x + d.target.x) / 2;
                const y = (d.source.y + d.target.y) / 2;

                // Calculate angle in degrees
                let angle = Math.atan2(dy, dx) * 180 / Math.PI;

                // Flip text to be readable (left-to-right)
                if (angle > 90 || angle < -90) {
                    angle += 180;
                }

                return `translate(${x}, ${y}) rotate(${angle})`;
            });

            // Update Nodes
            node.attr('transform', (d: any) => `translate(${d.x}, ${d.y})`);
        });

        return () => {
            simulationRef.current.stop();
        };
    }, [data, nodes, links, onNodeClick, resetZoom, onClearSelection]);

    useEffect(() => {
        if(isMapFullscreen) {
            setTimeout(resetZoom, 100);
        }
    }, [isMapFullscreen, resetZoom]);

    // Effect for highlighting based on selection
    useEffect(() => {
        const nodeElements = d3.selectAll('.node-group');
        const linkElements = d3.selectAll('.links line');
        const labelElements = d3.selectAll('.link-labels g');

        if (selectedNodeInfo) {
            const selectedId = selectedNodeInfo.node.id;

            const linkedNodeIds = new Set([selectedId]);
            const linkedEdgeIds = new Set();

            links.forEach((link: any) => {
                // D3 converts source/target strings to objects, so check .id if available, else check raw
                const sourceId = typeof link.source === 'object' ? link.source.id : link.source;
                const targetId = typeof link.target === 'object' ? link.target.id : link.target;

                if (sourceId === selectedId) {
                    linkedNodeIds.add(targetId);
                    linkedEdgeIds.add(link.index); // Use D3's index or a unique link ID
                } else if (targetId === selectedId) {
                    linkedNodeIds.add(sourceId);
                    linkedEdgeIds.add(link.index);
                }
            });

            nodeElements
                .transition().duration(300)
                .style('opacity', (d: any) => linkedNodeIds.has(d.id) ? 1 : 0.15);

            linkElements
                .transition().duration(300)
                .style('opacity', (d: any) => linkedEdgeIds.has(d.index) ? 1 : 0.1);

            labelElements
                .transition().duration(300)
                .style('opacity', (d: any) => linkedEdgeIds.has(d.index) ? 1 : 0.1);

        } else {
            nodeElements.transition().duration(300).style('opacity', 1);
            linkElements.transition().duration(300).style('opacity', 1);
            labelElements.transition().duration(300).style('opacity', 1);
        }
    }, [selectedNodeInfo, links]);

    return (
        <div
            ref={containerRef}
            className={`w-full h-full bg-slate-50 shadow-inner border border-gray-200 overflow-hidden ${
                isMapFullscreen
                    ? 'fixed inset-0 z-30'
                    : 'relative rounded-lg'
            }`}
        >
            {isLoading && <LoadingSpinner />}
            <svg ref={svgRef} className="w-full h-full"></svg>
            <MapControls
                onZoomIn={handleZoomIn}
                onZoomOut={handleZoomOut}
                onReset={resetZoom}
                onToggleFullscreen={() => setIsMapFullscreen(!isMapFullscreen)}
                isFullscreen={isMapFullscreen}
            />
            {selectedNodeInfo && <ConceptCard nodeInfo={selectedNodeInfo} onClose={onClearSelection} onDiscuss={onDiscussNode} T={T} />}

            <ContextMenu 
                position={contextMenu?.position || null} 
                onClose={() => setContextMenu(null)} 
                onExplainConnection={handleExplainConnection}
                sourceNode={contextMenu?.node || null}
                allNodes={nodes}
            />

            <ConnectionExplanationModal
                isOpen={!!explanationModal}
                onClose={() => setExplanationModal(null)}
                sourceNode={explanationModal?.source || null}
                targetNode={explanationModal?.target || null}
                caseTitle={caseTitle}
                language={language}
                T={T}
            />
        </div>
    );
});

