    language: string;
    T: Record<string, any>;
}

const ConnectionExplanationModal: React.FC<ConnectionExplanationModalProps> = ({ isOpen, onClose, sourceNode, targetNode, caseTitle, language, T }) => {
    const [explanation, setExplanation] = useState('');
    const [isLoading, setIsLoading] = useState(false);

    useEffect(() => {
        if (isOpen && sourceNode && targetNode) {
            const fetchExplanation = async () => {
                setIsLoading(true);
                setExplanation('');
                try {
                    const result = await getConceptConnectionExplanation(sourceNode.label, targetNode.label, caseTitle, language);
                    setExplanation(result);
                } catch (error) {
                    console.error("Failed to get connection explanation", error);
                    setExplanation(T.errorAbstract);
                } finally {
                    setIsLoading(false);
                }
            };
            fetchExplanation();
        }
    }, [isOpen, sourceNode, targetNode, caseTitle, language, T]);

    if (!isOpen) return null;

    return (
         <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center z-[60] p-4 animate-fade-in" onClick={onClose}>
            <div className="bg-white rounded-2xl shadow-2xl w-full max-w-lg overflow-hidden flex flex-col" onClick={e => e.stopPropagation()}>
                 <header className="p-5 border-b border-gray-100 bg-gray-50/50">
                    <h2 className="text-xl font-bold text-gray-900">{T.connectionExplanationTitle}</h2>
                    <div className="flex items-center gap-2 mt-2">
                        <span className="text-sm font-medium text-brand-blue px-2 py-0.5 bg-blue-50 rounded-md">{sourceNode?.label}</span>
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 text-gray-400" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M12.293 5.293a1 1 0 011.414 0l4 4a1 1 0 010 1.414l-4 4a1 1 0 01-1.414-1.414L14.586 11H3a1 1 0 110-2h11.586l-2.293-2.293a1 1 0 010-1.414z" clipRule="evenodd" /></svg>
                        <span className="text-sm font-medium text-indigo-600 px-2 py-0.5 bg-indigo-50 rounded-md">{targetNode?.label}</span>
                    </div>
                 </header>
                 <main className="p-6 min-h-[160px]">
                    {isLoading ? (
                        <div className="flex flex-col items-center justify-center h-full text-gray-400">
                           <LoadingSpinner />
