interface ContextMenuProps {
    position: { x: number, y: number } | null;
    onClose: () => void;
    onExplainConnection: (targetNode: KnowledgeNode) => void;
    sourceNode: KnowledgeNode | null;
    allNodes: KnowledgeNode[];
}

const ContextMenu: React.FC<ContextMenuProps> = ({ position, onClose, onExplainConnection, sourceNode, allNodes }) => {
    const menuRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
                onClose();
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, [onClose]);

    if (!position || !sourceNode) return null;

    return (
        <div ref={menuRef} style={{ top: position.y, left: position.x }} className="absolute bg-white/95 backdrop-blur-md rounded-lg shadow-2xl border border-gray-200 w-56 z-50 animate-fade-in text-sm overflow-hidden">
            <div className="p-3 border-b bg-gray-50/50">
                <p className="font-bold text-gray-900 truncate leading-tight">{sourceNode.label}</p>
                <p className="text-[10px] text-gray-500 uppercase tracking-wide font-semibold mt-0.5">{sourceNode.discipline}</p>
            </div>
            <div className="max-h-60 overflow-y-auto">
                <p className="text-[10px] font-bold uppercase text-gray-400 px-3 pt-3 pb-1">Explain connection to...</p>
                <ul className="pb-2">
                    {allNodes.filter(n => n.id !== sourceNode.id).map(targetNode => (
                         <li key={targetNode.id}>
                             <button onClick={() => { onExplainConnection(targetNode); onClose(); }} className="w-full text-left px-3 py-2 text-gray-700 hover:bg-brand-blue hover:text-white transition-colors truncate">
                                 {targetNode.label}
                             </button>
                         </li>
                    ))}
                </ul>
            </div>
        </div>
    );
};

interface ConnectionExplanationModalProps {
    isOpen: boolean;
    onClose: () => void;
    sourceNode: KnowledgeNode | null;
    targetNode: KnowledgeNode | null;
    caseTitle: string;
    language: string;
    T: Record<string, any>;
}

const ConnectionExplanationModal: React.FC<ConnectionExplanationModalProps> = ({ isOpen, onClose, sourceNode, targetNode, caseTitle, language, T }) => {
    const [explanation, setExplanation] = useState('');
    const [isLoading, setIsLoading] = useState(false);

    useEffect(() => {
        if (isOpen && sourceNode && targetNode) {
            const fetchExplanation = async () => {
                setIsLoading(true);
                setExplanation('');
                try {
                    const result = await getConceptConnectionExplanation(sourceNode.label, targetNode.label, caseTitle, language);
                    setExplanation(result);
                } catch (error) {
                    console.error("Failed to get connection explanation", error);
                    setExplanation(T.errorAbstract);
                } finally {
                    setIsLoading(false);
                }
            };
            fetchExplanation();
        }
    }, [isOpen, sourceNode, targetNode, caseTitle, language, T]);

    if (!isOpen) return null;

    return (
         <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center z-[60] p-4 animate-fade-in" onClick={onClose}>
            <div className="bg-white rounded-2xl shadow-2xl w-full max-w-lg overflow-hidden flex flex-col" onClick={e => e.stopPropagation()}>
                 <header className="p-5 border-b border-gray-100 bg-gray-50/50">
                    <h2 className="text-xl font-bold text-gray-900">{T.connectionExplanationTitle}</h2>
                    <div className="flex items-center gap-2 mt-2">
                        <span className="text-sm font-medium text-brand-blue px-2 py-0.5 bg-blue-50 rounded-md">{sourceNode?.label}</span>
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 text-gray-400" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M12.293 5.293a1 1 0 011.414 0l4 4a1 1 0 010 1.414l-4 4a1 1 0-1.414-1.414L14.586 11H3a1 1 0 110-2h11.586l-2.293-2.293a1 1 0 010-1.414z" clipRule="evenodd" /></svg>
                        <span className="text-sm font-medium text-indigo-600 px-2 py-0.5 bg-indigo-50 rounded-md">{targetNode?.label}</span>
                    </div>
                 </header>
                 <main className="p-6 min-h-[160px]">
                    {isLoading ? (
                        <div className="flex flex-col items-center justify-center h-full text-gray-400">
                           <LoadingSpinner />
                           <p className="mt-4 text-sm font-medium">{T.explainingConnection}</p>
                        </div>
                    ) : (
                        <div className="prose prose-sm max-w-none text-gray-700 leading-relaxed whitespace-pre-wrap">
                            {explanation}
                        </div>
                    )}
                 </main>
                 <footer className="p-4 border-t border-gray-100 text-right bg-gray-50/50">
                    <button onClick={onClose} className="bg-brand-blue hover:bg-blue-800 text-white font-bold py-2 px-8 rounded-xl transition shadow-md hover:shadow-lg">
                        {T.closeButton}
                    </button>
                </footer>
            </div>
        </div>
    );
};

