    [Discipline.GENETICS]: '#EA580C', // Deep Orange
    [Discipline.DIAGNOSTICS]: '#475569', // Professional Slate
    [Discipline.TREATMENT]: '#65A30D', // Fresh Lime
    [Discipline.PHYSIOTHERAPY]: '#06B6D4', // Sky Cyan
    [Discipline.OCCUPATIONAL_THERAPY]: '#9333EA', // Deep Purple
