interface KnowledgeMapProps {
    data: KnowledgeMapData;
    onNodeClick: (node: KnowledgeNode) => void;
    selectedNodeInfo: { node: KnowledgeNode; abstract: string; loading: boolean } | null;
    onClearSelection: () => void;
    isMapFullscreen: boolean;
    setIsMapFullscreen: (isFullscreen: boolean) => void;
    caseTitle: string;
    language: string;
    T: Record<string, any>;
    onDiscussNode: (nodeInfo: { node: KnowledgeNode; abstract: string; loading: boolean }) => void;
}

export const KnowledgeMap = forwardRef<any, KnowledgeMapProps>(({
    data,
    onNodeClick,
    selectedNodeInfo,
    onClearSelection,
    isMapFullscreen,
    setIsMapFullscreen,
    caseTitle,
    language,
    T,
    onDiscussNode
}, ref) => {
    const svgRef = useRef<SVGSVGElement | null>(null);
    const containerRef = useRef<HTMLDivElement | null>(null);
    const [isLoading, setIsLoading] = useState(true);
    const simulationRef = useRef<any>(null);
    const zoomRef = useRef<any>(null);
    const gRef = useRef<any>(null);

    const [contextMenu, setContextMenu] = useState<{ position: { x: number; y: number }; node: KnowledgeNode } | null>(null);
    const [explanationModal, setExplanationModal] = useState<{ source: KnowledgeNode; target: KnowledgeNode } | null>(null);

    const nodes = useMemo(() => data.nodes.map(n => ({ ...n })), [data.nodes]);
    const links = useMemo(() => data.links.map(l => ({ ...l })), [data.links]);

    useImperativeHandle(ref, () => ({
        async captureAsImage(): Promise<string> {
            if (svgRef.current) {
                return await svgToDataURL(svgRef.current);
            }
            return '';
        }
    }));

    const handleNodeRightClick = (event: MouseEvent, node: KnowledgeNode) => {
        event.preventDefault();
        setContextMenu({ position: { x: event.clientX, y: event.clientY }, node });
    };

    const handleExplainConnection = (targetNode: KnowledgeNode) => {
        if (contextMenu) {
            setExplanationModal({ source: contextMenu.node, target: targetNode });
        }
    };

    const resetZoom = useCallback(() => {
        if (!svgRef.current || !gRef.current || !containerRef.current || !zoomRef.current) return;
        const svg = d3.select(svgRef.current);
        const g = gRef.current;

        const bounds = g.node().getBBox();
        const parent = svg.node().parentElement;
        if (!parent) return;

        const fullWidth = parent.clientWidth;
        const fullHeight = parent.clientHeight;
        const { width, height, x, y } = bounds;

        if (width === 0 || height === 0) return;

        const midX = x + width / 2;
        const midY = y + height / 2;
        const scale = Math.min(1.2, 0.8 / Math.max(width / fullWidth, height / fullHeight));
        const translate = [fullWidth / 2 - scale * midX, fullHeight / 2 - scale * midY];

        const transform = d3.zoomIdentity.translate(translate[0], translate[1]).scale(scale);

        svg.transition().duration(750).call(zoomRef.current.transform, transform);
    }, []);

    const handleZoomIn = useCallback(() => {
        if (zoomRef.current && svgRef.current) {
            d3.select(svgRef.current).transition().duration(250).call(zoomRef.current.scaleBy, 1.3);
        }
    }, []);

    const handleZoomOut = useCallback(() => {
        if (zoomRef.current && svgRef.current) {
            d3.select(svgRef.current).transition().duration(250).call(zoomRef.current.scaleBy, 0.7);
        }
    }, []);

    useEffect(() => {
        const observer = new ResizeObserver(() => {
            resetZoom();
        });
        if (containerRef.current) {
            observer.observe(containerRef.current);
        }
        return () => {
            observer.disconnect();
        };
    }, [resetZoom]);

    useEffect(() => {
        if (!svgRef.current || !containerRef.current) return;

        setIsLoading(true);

        const svg = d3.select(svgRef.current);
        svg.selectAll('*').remove();

        const defs = svg.append("defs");

        // High-Fidelity Arrow Marker
        defs.append("marker")
            .attr("id", "arrow-head-map")
            .attr("viewBox", "0 -3 6 6")
            .attr("refX", 5.5) 
            .attr("refY", 0)
            .attr("markerWidth", 5)
            .attr("markerHeight", 5)
            .attr("orient", "auto")
            .attr("markerUnits", "strokeWidth")
            .append("path")
            .attr("d", "M0,-2.5 L6,0 L0,2.5")
            .attr("fill", "#94a3b8");

        // Glow/Shadow for nodes
        const filter = defs.append("filter")
            .attr("id", "node-shadow")
            .attr("x", "-20%")
            .attr("y", "-20%")
            .attr("width", "140%")
            .attr("height", "140%");

        filter.append("feGaussianBlur")
            .attr("in", "SourceAlpha")
            .attr("stdDeviation", "2")
            .attr("result", "blur");

        filter.append("feOffset")
            .attr("in", "blur")
            .attr("dx", "1")
            .attr("dy", "2")
            .attr("result", "offsetBlur");

        const feMerge = filter.append("feMerge");
        feMerge.append("feMergeNode").attr("in", "offsetBlur");
        feMerge.append("feMergeNode").attr("in", "SourceGraphic");

        // Gradients for nodes
        Object.entries(DisciplineColors).forEach(([discipline, color]) => {
            const grad = defs.append("linearGradient")
                .attr("id", `grad-${discipline.replace(/\s+/g, '-')}`)
                .attr("x1", "0%").attr("y1", "0%").attr("x2", "0%").attr("y2", "100%");
            grad.append("stop").attr("offset", "0%").attr("stop-color", color).attr("stop-opacity", 1);
            grad.append("stop").attr("offset", "100%").attr("stop-color", color).attr("stop-opacity", 0.85);
        });


        const { width, height } = containerRef.current.getBoundingClientRect();

        const g = svg.append('g');
        gRef.current = g;

        const zoom = d3.zoom().scaleExtent([0.1, 4]).on('zoom', (event: any) => {
            g.attr('transform', event.transform);
        });
        zoomRef.current = zoom;
        svg.call(zoom);
        svg.on("click", onClearSelection);

        simulationRef.current = d3.forceSimulation(nodes)
            .force('link', d3.forceLink(links).id((d: any) => d.id).distance(240).strength(0.35))
            .force('charge', d3.forceManyBody().strength(-2200))
            .force('center', d3.forceCenter(width / 2, height / 2))
            .force('collide', d3.forceCollide().radius(115).iterations(4))
            .on('end', () => {
                setIsLoading(false);
                resetZoom();
            });

        // --- Links ---
        const linkLines = g.append("g")
            .attr("class", "links")
            .selectAll("path")
            .data(links)
            .join("path")
            .attr("fill", "none")
            .attr("stroke", "#e2e8f0")
            .attr("stroke-opacity", 0.7)
            .attr("stroke-width", 1.5)
            .attr("marker-end", "url(#arrow-head-map)");

        const linkLabels = g.append("g")
            .attr("class", "link-labels")
            .selectAll("g")
            .data(links)
            .join("g")
            .attr("class", "opacity-50 transition-opacity hover:opacity-100");

        linkLabels.append("rect")
            .attr("rx", 5)
            .attr("ry", 5)
            .attr("fill", "white")
            .attr("fill-opacity", 0.9)
            .attr("stroke", "#f1f5f9")
            .attr("stroke-width", 0.5);

        linkLabels.append("text")
            .text((d: any) => d.description)
            .attr("font-size", "8px")
            .attr("fill", "#94a3b8")
            .attr("font-weight", "600")
            .attr("text-anchor", "middle")
            .attr("dy", "0.35em")
            .attr("font-family", "Inter, sans-serif")
            .attr("pointer-events", "none")
            .each(function(d: any) {
                const bbox = (this as any).getBBox();
                d.labelWidth = bbox.width + 8;
                d.labelHeight = bbox.height + 4;
            });

        linkLabels.select("rect")
            .attr("width", (d: any) => d.labelWidth)
            .attr("height", (d: any) => d.labelHeight)
            .attr("x", (d: any) => -d.labelWidth / 2)
            .attr("y", (d: any) => -d.labelHeight / 2);


        // --- Nodes (Attractive High-Fidelity Pills) ---
        const node = g.append('g')
            .attr("class", "nodes")
            .selectAll('g')
            .data(nodes)
            .join('g')
            .attr('class', 'node-group cursor-pointer transition-transform hover:scale-105')
            .call(d3.drag()
                .on('start', (event: any, d: any) => {
                    if (!event.active) simulationRef.current.alphaTarget(0.3).restart();
                    d.fx = d.x;
                    d.fy = d.y;
                })
                .on('drag', (event: any, d: any) => {
                    d.fx = event.x;
                    d.fy = event.y;
                })
                .on('end', (event: any, d: any) => {
                    if (!event.active) simulationRef.current.alphaTarget(0);
                    d.fx = null;
                    d.fy = null;
                }))
            .on('click', (event: MouseEvent, d: any) => {
                event.stopPropagation(); 
                onNodeClick(d);
            })
            .on('contextmenu', (event: MouseEvent, d: any) => handleNodeRightClick(event, d));

        // Attractive Pill background
        node.append('rect')
            .attr('rx', 22)
            .attr('ry', 22)
            .attr('fill', (d: any) => `url(#grad-${d.discipline.replace(/\s+/g, '-')})`)
            .attr('stroke', '#fff')
            .attr('stroke-width', 2.5)
            .style('filter', 'url(#node-shadow)');

        // Node main label
        node.append('text')
            .text((d: any) => d.label)
            .attr("font-family", "Inter, sans-serif")
            .attr('font-size', '13px')
            .attr('font-weight', '700')
            .attr('fill', '#ffffff')
            .attr('text-anchor', 'middle')
            .attr('dy', '0.15em')
            .each(function(d: any) {
                const bbox = (this as any).getBBox();
                d.pillWidth = Math.max(110, bbox.width + 40);
                d.pillHeight = 46;
            });

        node.select('rect')
            .attr('width', (d: any) => d.pillWidth)
            .attr('height', (d: any) => d.pillHeight)
            .attr('x', (d: any) => -d.pillWidth / 2)
            .attr('y', (d: any) => -d.pillHeight / 2);

        // Sub-text for discipline
        node.append('text')
            .text((d: any) => d.discipline.toUpperCase())
            .attr('font-size', '7px')
            .attr('font-weight', '800')
            .attr('fill', '#ffffff')
            .attr('opacity', 0.6)
            .attr('letter-spacing', '0.05em')
            .attr('text-anchor', 'middle')
            .attr('dy', '1.6em');

        // Precise arrow connection helper
        function intersectRect(rect: any, point: any) {
            const cx = rect.x;
            const cy = rect.y;
            const dx = point.x - cx;
            const dy = point.y - cy;
            const w = (rect.pillWidth || 0) / 2;
            const h = (rect.pillHeight || 0) / 2;
            if (w === 0 || h === 0) return { x: cx, y: cy }; 

            if (Math.abs(dy * w) < Math.abs(dx * h)) {
                if (dx > 0) return { x: cx + w, y: cy + dy * w / dx };
                else return { x: cx - w, y: cy - dy * w / dx };
            } else {
                if (dy > 0) return { x: cx + dx * h / dy, y: cy + h };
                else return { x: cx - dx * h / dy, y: cy - h };
            }
        }

        simulationRef.current.on('tick', () => {
            linkLines.attr('d', (d: any) => {
                if (!d.source.x || !d.target.x) return null;
                const sourcePoint = intersectRect(d.source, d.target);
                const targetPoint = intersectRect(d.target, d.source);
                return `M ${sourcePoint.x} ${sourcePoint.y} L ${targetPoint.x} ${targetPoint.y}`;
            });

            linkLabels.attr('transform', (d: any) => {
                if (!d.source.x || !d.target.x) return null;
                const midX = (d.source.x + d.target.x) / 2;
                const midY = (d.source.y + d.target.y) / 2;
                const dx = d.target.x - d.source.x;
                const dy = d.target.y - d.source.y;
                let angle = Math.atan2(dy, dx) * 180 / Math.PI;
                if (angle > 90 || angle < -90) angle += 180;
                return `translate(${midX}, ${midY}) rotate(${angle})`;
            });

            node.attr('transform', (d: any) => `translate(${d.x}, ${d.y})`);
        });

        return () => {
            simulationRef.current.stop();
        };
    }, [data, nodes, links, onNodeClick, resetZoom, onClearSelection]);

    useEffect(() => {
        if(isMapFullscreen) {
            setTimeout(resetZoom, 150);
        }
    }, [isMapFullscreen, resetZoom]);

    useEffect(() => {
        const nodeElements = d3.selectAll('.node-group');
        const linkElements = d3.selectAll('.links path');
        const labelElements = d3.selectAll('.link-labels g');

        if (selectedNodeInfo) {
            const selectedId = selectedNodeInfo.node.id;
            const linkedNodeIds = new Set([selectedId]);
            const linkedEdgeIds = new Set();

            links.forEach((link: any) => {
                const sourceId = typeof link.source === 'object' ? link.source.id : link.source;
                const targetId = typeof link.target === 'object' ? link.target.id : link.target;

                if (sourceId === selectedId) {
                    linkedNodeIds.add(targetId);
                    linkedEdgeIds.add(link.index);
                } else if (targetId === selectedId) {
                    linkedNodeIds.add(sourceId);
                    linkedEdgeIds.add(link.index);
                }
            });

            nodeElements
                .transition().duration(300)
                .style('opacity', (d: any) => linkedNodeIds.has(d.id) ? 1 : 0.1);

            linkElements
                .transition().duration(300)
                .style('opacity', (d: any) => linkedEdgeIds.has(d.index) ? 1 : 0.05);

            labelElements
                .transition().duration(300)
                .style('opacity', (d: any) => linkedEdgeIds.has(d.index) ? 1 : 0);

        } else {
            nodeElements.transition().duration(300).style('opacity', 1);
            linkElements.transition().duration(300).style('opacity', 0.7);
            labelElements.transition().duration(300).style('opacity', 0.5);
        }
    }, [selectedNodeInfo, links]);

    return (
        <div
            ref={containerRef}
            className={`w-full h-full bg-slate-50 shadow-inner border border-gray-200 overflow-hidden ${
                isMapFullscreen
                    ? 'fixed inset-0 z-40'
                    : 'relative rounded-xl'
            }`}
        >
            {isLoading && <div className="absolute inset-0 z-20 flex items-center justify-center bg-slate-50/50 backdrop-blur-sm"><LoadingSpinner /></div>}
            <svg ref={svgRef} className="w-full h-full touch-none"></svg>
            <MapControls
                onZoomIn={handleZoomIn}
                onZoomOut={handleZoomOut}
