        if (width === 0 || height === 0) return;
        const scale = Math.min(1.2, 0.8 / Math.max(width / parent.clientWidth, height / parent.clientHeight));
        const transform = d3.zoomIdentity.translate(parent.clientWidth / 2 - scale * (x + width / 2), parent.clientHeight / 2 - scale * (y + height / 2)).scale(scale);
        svg.transition().duration(750).call(zoomRef.current.transform, transform);
    }, []);
    useEffect(() => {
        if (!svgRef.current || !containerRef.current) return;
