        const defs = svg.append("defs");
        defs.append("marker").attr("id", "arrow-head-map").attr("viewBox", "0 -3 6 6").attr("refX", 5.5).attr("refY", 0).attr("markerWidth", 5).attr("markerHeight", 5).attr("orient", "auto").attr("markerUnits", "strokeWidth").append("path").attr("d", "M0,-2.5 L6,0 L0,2.5").attr("fill", "#94a3b8");
        const filter = defs.append("filter").attr("id", "node-shadow").attr("x", "-20%").attr("y", "-20%").attr("width", "140%").attr("height", "140%");
        filter.append("feGaussianBlur").attr("in", "SourceAlpha").attr("stdDeviation", "2").attr("result", "blur");
        filter.append("feOffset").attr("in", "blur").attr("dx", "1").attr("dy", "2").attr("result", "offsetBlur");
        const feMerge = filter.append("feMerge"); feMerge.append("feMergeNode").attr("in", "offsetBlur"); feMerge.append("feMergeNode").attr("in", "SourceGraphic");
        Object.entries(DisciplineColors).forEach(([discipline, color]) => {
            const grad = defs.append("linearGradient").attr("id", `grad-${discipline.replace(/\s+/g, '-')}`).attr("x1", "0%").attr("y1", "0%").attr("x2", "0%").attr("y2", "100%");
            grad.append("stop").attr("offset", "0%").attr("stop-color", color).attr("stop-opacity", 1);
            grad.append("stop").attr("offset", "100%").attr("stop-color", color).attr("stop-opacity", 0.85);
        });
        const { width, height } = containerRef.current.getBoundingClientRect();
        const g = svg.append('g'); gRef.current = g;
        const zoom = d3.zoom().scaleExtent([0.1, 4]).on('zoom', (event: any) => g.attr('transform', event.transform));
        zoomRef.current = zoom; svg.call(zoom); svg.on("click", onClearSelection);
        simulationRef.current = d3.forceSimulation(nodes).force('link', d3.forceLink(links).id((d: any) => d.id).distance(220).strength(0.35)).force('charge', d3.forceManyBody().strength(-2000)).force('center', d3.forceCenter(width / 2, height / 2)).force('collide', d3.forceCollide().radius(110).iterations(3)).on('end', () => { setIsLoading(false); resetZoom(); });
        const linkLines = g.append("g").attr("class", "links").selectAll("path").data(links).join("path").attr("fill", "none").attr("stroke", "#e2e8f0").attr("stroke-opacity", 0.7).attr("stroke-width", 1.5).attr("marker-end", "url(#arrow-head-map)");
        const linkLabels = g.append("g").attr("class", "link-labels").selectAll("g").data(links).join("g").attr("class", "opacity-50 transition-opacity hover:opacity-100");
        linkLabels.append("rect").attr("rx", 5).attr("ry", 5).attr("fill", "white").attr("fill-opacity", 0.9).attr("stroke", "#f1f5f9").attr("stroke-width", 0.5);
        linkLabels.append("text").text((d: any) => d.description).attr("font-size", "8px").attr("fill", "#94a3b8").attr("font-weight", "600").attr("text-anchor", "middle").attr("dy", "0.35em").attr("font-family", "Inter, sans-serif").attr("pointer-events", "none").each(function(d: any) { const bbox = (this as any).getBBox(); d.labelWidth = bbox.width + 8; d.labelHeight = bbox.height + 4; });
        linkLabels.select("rect").attr("width", (d: any) => d.labelWidth).attr("height", (d: any) => d.labelHeight).attr("x", (d: any) => -d.labelWidth / 2).attr("y", (d: any) => -d.labelHeight / 2);
        const node = g.append('g').attr("class", "nodes").selectAll('g').data(nodes).join('g').attr('class', 'node-group cursor-pointer').call(d3.drag().on('start', (event: any, d: any) => { if (!event.active) simulationRef.current.alphaTarget(0.3).restart(); d.fx = d.x; d.fy = d.y; }).on('drag', (event: any, d: any) => { d.fx = event.x; d.fy = event.y; }).on('end', (event: any, d: any) => { if (!event.active) simulationRef.current.alphaTarget(0); d.fx = null; d.fy = null; })).on('click', (event: MouseEvent, d: any) => { event.stopPropagation(); onNodeClick(d); }).on('contextmenu', (event: MouseEvent, d: any) => { event.preventDefault(); setContextMenu({ position: { x: event.clientX, y: event.clientY }, node: d }); });
        node.append('title').text((d: any) => `Concept: ${d.label} (${d.discipline})\nClick to view summary.`);
        node.append('rect').attr('rx', 20).attr('ry', 20).attr('fill', (d: any) => `url(#grad-${d.discipline.replace(/\s+/g, '-')})`).attr('stroke', '#fff').attr('stroke-width', 2.5).style('filter', 'url(#node-shadow)');
        node.append('text').text((d: any) => d.label).attr("font-family", "Inter, sans-serif").attr('font-size', '13px').attr('font-weight', '700').attr('fill', '#ffffff').attr('text-anchor', 'middle').attr('dy', '0.15em').each(function(d: any) { const bbox = (this as any).getBBox(); d.pillWidth = Math.max(110, bbox.width + 40); d.pillHeight = 44; });
        node.select('rect').attr('width', (d: any) => d.pillWidth).attr('height', (d: any) => d.pillHeight).attr('x', (d: any) => -d.pillWidth / 2).attr('y', (d: any) => -d.pillHeight / 2);
        node.append('text').text((d: any) => d.discipline.toUpperCase()).attr('font-size', '7px').attr('font-weight', '800').attr('fill', '#ffffff').attr('opacity', 0.6).attr('letter-spacing', '0.05em').attr('text-anchor', 'middle').attr('dy', '1.6em');
        function intersectRect(rect: any, point: any) { const cx = rect.x, cy = rect.y, dx = point.x - cx, dy = point.y - cy, w = (rect.pillWidth || 0) / 2, h = (rect.pillHeight || 0) / 2; if (w === 0 || h === 0) return { x: cx, y: cy }; if (Math.abs(dy * w) < Math.abs(dx * h)) return dx > 0 ? { x: cx + w, y: cy + dy * w / dx } : { x: cx - w, y: cy - dy * w / dx }; else return dy > 0 ? { x: cx + dx * h / dy, y: cy + h } : { x: cx - dx * h / dy, y: cy - h }; }
        simulationRef.current.on('tick', () => { linkLines.attr('d', (d: any) => { if (!d.source.x || !d.target.x) return null; const s = intersectRect(d.source, d.target), t = intersectRect(d.target, d.source); return `M ${s.x} ${s.y} L ${t.x} ${t.y}`; }); linkLabels.attr('transform', (d: any) => { if (!d.source.x || !d.target.x) return null; const midX = (d.source.x + d.target.x) / 2, midY = (d.source.y + d.target.y) / 2, dx = d.target.x - d.source.x, dy = d.target.y - d.source.y; let angle = Math.atan2(dy, dx) * 180 / Math.PI; if (angle > 90 || angle < -90) angle += 180; return `translate(${midX}, ${midY}) rotate(${angle})`; }); node.attr('transform', (d: any) => `translate(${d.x}, ${d.y})`); });
        return () => simulationRef.current.stop();
    }, [data, nodes, links, onNodeClick, resetZoom, onClearSelection]);
    return (
        <div ref={containerRef} className={`w-full h-full bg-slate-50 shadow-inner border border-gray-200 overflow-hidden ${isMapFullscreen ? 'fixed inset-0 z-40' : 'relative rounded-xl'}`}>
            {isLoading && <div className="absolute inset-0 z-20 flex items-center justify-center bg-slate-50/50 backdrop-blur-sm"><LoadingSpinner /></div>}
