  const handleCopy = () => { navigator.clipboard.writeText(formatCaseForClipboard(patientCase, T)).then(() => { setIsCopied(true); setTimeout(() => setIsCopied(false), 2000); }); };
  const handleTriggerIllustration = (desc: string, sourceIndex: number) => { setActiveImageGenerator({ content: { title: 'Clinical Illustration', description: desc, type: EducationalContentType.IMAGE, reference: 'AI Generated' }, index: sourceIndex }); };
  const handleImageGenerated = useCallback((idx: number, img: string) => { setPatientCase(prev => { const edu = [...(prev.educationalContent || [])]; if (idx >= 0 && edu[idx]) { edu[idx] = { ...edu[idx], imageData: img }; } return { ...prev, educationalContent: edu }; }); setActiveImageGenerator(null); }, [setPatientCase]);
  const handleEnrichSources = async () => { setIsEnrichingEvidence(true); try { const { newEvidence, newReadings, groundingSources: gs } = await enrichCaseWithWebSources(patientCase, language); setPatientCase(prev => ({ ...prev, traceableEvidence: [...(prev.traceableEvidence || []), ...newEvidence], furtherReadings: [...(prev.furtherReadings || []), ...newReadings] })); setGroundingSources(gs); } catch (e) { console.error(e); } finally { setIsEnrichingEvidence(false); } };
  const EditableText: React.FC<{ value: string; onChange: (e: React.ChangeEvent<HTMLTextAreaElement>) => void; isEditing: boolean; }> = ({ value, onChange, isEditing }) => {
    const ref = useRef<HTMLTextAreaElement>(null);
    useEffect(() => { if (isEditing && ref.current) { ref.current.style.height = 'auto'; ref.current.style.height = `${ref.current.scrollHeight}px`; } }, [isEditing, value]);
    return isEditing ? <textarea ref={ref} value={value} onChange={onChange} className="w-full p-2 border border-blue-200 rounded-md focus:ring-2 bg-blue-50/50 text-black resize-none" /> : <SmartContent content={value} language={language} T={T} onTriggerIllustration={(d) => handleTriggerIllustration(d, -1)} />;
  };
  return (
    <div className="p-4 sm:p-6 relative">
      <header className="sticky top-0 -mx-4 sm:-mx-6 -mt-4 sm:-mt-6 p-3 sm:p-4 bg-white/80 backdrop-blur-sm border-b border-gray-200 z-10">
        <div className="flex justify-between items-center">
          <h2 className="text-xl sm:text-2xl font-bold text-brand-text truncate pr-2">{patientCase.title}</h2>
          <div className="flex items-center space-x-1">
            {isEditing ? (
              <>
                <button onClick={undo} disabled={!canUndo} title="Undo Changes" className="p-2 text-gray-500 hover:bg-gray-100 disabled:opacity-30"><svg className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M10 2a1 1 0 00-1 1v1.135a4.002 4.002 0 00-2.995 2.562l-1.34-1.34a1 1 0 10-1.414 1.414l1.586 1.586A4.002 4.002 0 008 10a4 4 0 104-4V3a1 1 0 00-1-1zm0 8a2 2 0 100-4 2 2 0 000 4z" /></svg></button>
                <button onClick={redo} disabled={!canRedo} title="Redo Changes" className="p-2 text-gray-500 hover:bg-gray-100 disabled:opacity-30"><svg className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M10 18a1 1 0 001-1v-1.135a4.002 4.002 0 002.995-2.562l1.34 1.34a1 1 0 101.414-1.414l-1.586-1.586A4.002 4.002 0 0012 10a4 4 0 10-4 4V17a1 1 0 001 1zm0-8a2 2 0 100 4 2 2 0 000 4z" /></svg></button>
                <button onClick={handleSave} title="Finalize text edits" className="bg-green-600 text-white font-semibold py-1 px-3 rounded-md text-sm shadow-sm">{T.saveButton}</button>
                <button onClick={handleCancel} title="Discard current edits" className="bg-gray-200 text-gray-700 font-semibold py-1 px-3 rounded-md text-sm">{T.cancelButton}</button>
              </>
            ) : (
              <>
                <button onClick={onOpenShare} title="Share this medical case" className="p-2 text-gray-500 hover:bg-gray-100 transition"><svg className="h-5 w-5" fill="currentColor" viewBox="0 0 20 20"><path d="M15 8a3 3 0 10-2.977-2.63l-4.94 2.47a3 3 0 100 4.319l4.94 2.47a3 3 0 10.895-1.789l-4.94-2.47a3.027 3.027 0 000-.74l4.94-2.47C13.456 7.68 14.19 8 15 8z" /></svg></button>
                <button onClick={handleCopy} title="Copy full case overview" className="p-2 text-gray-500 hover:bg-gray-100 transition">{isCopied ? <svg className="h-5 w-5 text-green-500" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" /></svg> : <svg className="h-5 w-5" fill="currentColor" viewBox="0 0 20 20"><path d="M7 9a2 2 0 012-2h6a2 2 0 012 2v6a2 2 0 01-2 2H9a2 2 0 01-2-2V9z" /><path d="M5 3a2 2 0 00-2 2v6a2 2 0 002 2V5h8a2 2 0 00-2-2H5z" /></svg>}</button>
                <button onClick={() => setIsEditing(true)} title="Modify case details" className="p-2 text-gray-500 hover:bg-gray-100 transition"><svg className="h-5 w-5" fill="currentColor" viewBox="0 0 20 20"><path d="M17.414 2.586a2 2 0 00-2.828 0L7 10.172V13h2.828l7.586-7.586a2 2 0 000-2.828z" /><path d="M2 6a2 2 0 012-2h4a1 1 0 010 2H4v10h10v-4a1 1 0 112 0v4a2 2 0 01-2 2H4a2 2 0 01-2-2V6z" /></svg></button>
              </>
            )}
          </div>
        </div>
      </header>
      <div className="space-y-4">
        <Section title={T.patientProfile} onCopy={() => handleTextChange} onSaveSnippet={() => onSaveSnippet(T.patientProfile, patientCase.patientProfile)} T={T}><EditableText value={patientCase.patientProfile} onChange={(e) => handleTextChange(e, 'patientProfile')} isEditing={isEditing} /></Section>
        <Section title={T.presentingComplaint} onCopy={() => handleTextChange} onSaveSnippet={() => onSaveSnippet(T.presentingComplaint, patientCase.presentingComplaint)} T={T}><EditableText value={patientCase.presentingComplaint} onChange={(e) => handleTextChange(e, 'presentingComplaint')} isEditing={isEditing} /></Section>
        <Section title={T.history} onCopy={() => handleTextChange} onSaveSnippet={() => onSaveSnippet(T.history, patientCase.history)} T={T}><EditableText value={patientCase.history} onChange={(e) => handleTextChange(e, 'history')} isEditing={isEditing} /></Section>
        { patientCase.biochemicalPathway ? (
            <Section title={T.biochemicalPathwaySection} onCopy={() => {}} onSaveSnippet={() => onSaveSnippet(patientCase.biochemicalPathway!.title, patientCase.biochemicalPathway!.description)} T={T}>
                <div className="flex items-center justify-between mb-2">
                    <div className="flex items-center space-x-2"><h4 className="text-md font-semibold text-gray-800">{patientCase.biochemicalPathway.title}</h4><TextToSpeechPlayer textToRead={`${patientCase.biochemicalPathway.title}. ${patientCase.biochemicalPathway.description}`} language={language} /></div>
                    <button onClick={() => onOpenDiscussion({ aspect: patientCase.biochemicalPathway!.title, consideration: patientCase.biochemicalPathway!.description })} title="Discuss this pathway with the AI tutor" className="text-sm bg-blue-100 hover:bg-blue-200 text-brand-blue font-semibold py-1 px-3 rounded-md transition">{T.discussButton}</button>
                </div>
                <p className="text-xs text-gray-500 italic mb-2">{patientCase.biochemicalPathway.reference}</p>
                <MarkdownRenderer content={patientCase.biochemicalPathway.description} />
                {patientCase.biochemicalPathway.diagramData && <div className="mt-4 h-80 rounded-lg border border-gray-200 shadow-sm overflow-hidden"><InteractiveDiagram id="diagram-biochem" data={patientCase.biochemicalPathway.diagramData} /></div>}
            </Section>
        ) : isGeneratingDetails ? <Section title={T.biochemicalPathwaySection} onCopy={() => {}} onSaveSnippet={() => {}} T={T}><SkeletonLoader /></Section> : null }
        { patientCase.multidisciplinaryConnections ? (
            <Section title={T.multidisciplinaryConnections} onCopy={() => {}} onSaveSnippet={() => onSaveSnippet(T.multidisciplinaryConnections, patientCase.multidisciplinaryConnections!.map(c => `${c.discipline}: ${c.connection}`).join('\n'))} T={T}>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    {patientCase.multidisciplinaryConnections.map((conn, idx) => (
                        <div key={idx} className="bg-gray-50 border border-gray-200 rounded-lg p-4 transition hover:shadow-md hover:border-blue-300 flex flex-col justify-between h-full group">
                            <div><div className="flex items-center mb-2"><div className="p-2 rounded-full mr-3" style={{ backgroundColor: `${DisciplineColors[conn.discipline]}20` }}><DisciplineIcon discipline={conn.discipline} className="h-5 w-5" style={{ color: DisciplineColors[conn.discipline] }} /></div><h5 className="font-bold text-gray-800">{conn.discipline}</h5></div><div className="text-sm text-gray-700 leading-relaxed mb-3"><MarkdownRenderer content={conn.connection} /></div></div>
                            <button onClick={() => onOpenDiscussion({ aspect: conn.discipline, consideration: conn.connection })} title={`Deep dive into ${conn.discipline} factors`} className="self-end flex items-center space-x-1 text-xs bg-white border border-blue-200 text-brand-blue hover:bg-blue-50 font-semibold py-1.5 px-3 rounded-md transition shadow-sm"><svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 8l4 4m0 0l-4 4m4-4H3"></path></svg><span>{T.discussButton}</span></button>
                        </div>
                    ))}
                </div>
            </Section>
        ) : isGeneratingDetails ? <Section title={T.multidisciplinaryConnections} onCopy={() => {}} onSaveSnippet={() => {}} T={T}><SkeletonLoader /></Section> : null }
        { patientCase.disciplineSpecificConsiderations ? (
            <Section title={T.managementConsiderations} onCopy={() => {}} onSaveSnippet={() => onSaveSnippet(T.managementConsiderations, patientCase.disciplineSpecificConsiderations!.map(c => `${c.aspect}: ${c.consideration}`).join('\n'))} T={T}>
                <ul className="space-y-3">
                    {patientCase.disciplineSpecificConsiderations.map((item, idx) => (
                        <li key={idx}><div className="flex justify-between items-center"><strong className="text-gray-800">{item.aspect}</strong><button onClick={() => onOpenDiscussion(item)} title="Ask specific questions about this management point" className="text-sm bg-blue-100 hover:bg-blue-200 text-brand-blue font-semibold py-1 px-3 rounded-md transition">{T.discussButton}</button></div><div className="mt-1"><SmartContent content={item.consideration} language={language} T={T} onTriggerIllustration={(d) => handleTriggerIllustration(d, -1)} /></div></li>
                    ))}
                </ul>
            </Section>
        ) : isGeneratingDetails ? <Section title={T.managementConsiderations} onCopy={() => {}} onSaveSnippet={() => {}} T={T}><SkeletonLoader /></Section> : null }
        { (patientCase.traceableEvidence || patientCase.furtherReadings) ? (
            <Section title={T.evidenceAndReading} onCopy={() => {}} onSaveSnippet={() => {}} T={T} onEnrich={handleEnrichSources} isEnriching={isEnrichingEvidence} groundingSources={groundingSources}>
                {patientCase.traceableEvidence && (
                    <div className="mb-4"><h4 className="font-semibold text-gray-800">{T.traceableEvidence}</h4><ul className="list-disc list-inside space-y-2 mt-2">{patientCase.traceableEvidence.map((e, i) => <li key={i}><span className="font-medium">"{e.claim}"</span> <span className="text-xs ml-1 text-gray-600">(<SourceRenderer text={e.source} onSearchClick={() => setActiveSourceSearch(e.source)} />)</span></li>)}</ul></div>
                )}
                {patientCase.furtherReadings && (
                    <div><h4 className="font-semibold text-gray-800">{T.furtherReading}</h4><ul className="list-disc list-inside space-y-2 mt-2">{patientCase.furtherReadings.map((r, i) => <li key={i}><span className="font-medium">{r.topic}:</span> <span className="text-xs ml-1 text-gray-600"><SourceRenderer text={r.reference} onSearchClick={() => setActiveSourceSearch(r.reference)} /></span></li>)}</ul></div>
                )}
            </Section>
        ) : isGeneratingDetails ? <Section title={T.evidenceAndReading} onCopy={() => {}} onSaveSnippet={() => {}} T={T}><SkeletonLoader /></Section> : null }
        { patientCase.quiz ? <QuizView quiz={patientCase.quiz} T={T} /> : isGeneratingDetails ? <Section title={T.quizTitle} onCopy={() => {}} onSaveSnippet={() => {}} T={T}><SkeletonLoader /></Section> : null }
      </div>
      {activeImageGenerator && <ImageGenerator content={activeImageGenerator.content} onClose={() => setActiveImageGenerator(null)} language={language} T={T} onImageGenerated={(img) => handleImageGenerated(activeImageGenerator.index, img)} />}
      {activeSourceSearch && <SourceSearchModal isOpen={!!activeSourceSearch} onClose={() => setActiveSourceSearch(null)} sourceQuery={activeSourceSearch} language={language} T={T} />}
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { AudioVisualizer } from './AudioVisualizer';

interface ControlPanelProps {
  onGenerate: (condition: string, discipline: string, difficulty: string) => void;
  disabled: boolean;
  T: Record<string, any>;
  language: string;
  onSaveCase: () => void;
  onOpenSavedWork: () => void;
  onOpenClinicalTools: () => void;
  isCaseActive: boolean;
  onGenerateNew: () => void;
  mobileView: 'case' | 'map';
  onSetMobileView: (view: 'case' | 'map') => void;
}

const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
const isSpeechRecognitionSupported = !!SpeechRecognition;

const MicButton: React.FC<{ onClick: () => void, isListening: boolean, disabled: boolean, title: string }> = ({ onClick, isListening, disabled, title }) => {
    return (
        <button 
            type="button" 
            onClick={onClick} 
            disabled={disabled} 
            title={title}
            className="absolute right-0 top-0 h-full px-2.5 flex items-center text-gray-400 hover:text-brand-blue-light disabled:text-gray-300 disabled:cursor-not-allowed transition-colors gap-2"
        >
            <AudioVisualizer isListening={isListening} />
            {isListening ? (
                 <svg className="h-5 w-5 text-red-500 animate-pulse" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor">
                    <path d="M10 18a8 8 0 100-16 8 8 0 000 16zM8 8a2 2 0 00-2 2v.001a2 2 0 002 2h4a2 2 0 002-2V10a2 2 0 00-2-2H8z" />
                </svg>
            ) : (
                <svg className="h-5 w-5" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor">
                    <path fillRule="evenodd" d="M7 4a3 3 0 016 0v4a3 3 0 11-6 0V4zm-1 4a4 4 0 108 0V4a4 4 0 10-8 0v4zM2 11a1 1 0 011-1h1a1 1 0 011 1v.5a.5.5 0 001 0V11a3 3 0 013-3h0a3 3 0 013 3v.5a.5.5 0 001 0V11a1 1 0 011 1h1a1 1 0 110 2h-1a1 1 0 01-1-1v-.5a2.5 2.5 0 00-5 0v.5a1 1 0 01-1 1H3a1 1 0 01-1-1v-2z" clipRule="evenodd" />
                </svg>
            )}
        </button>
    );
};

export const ControlPanel: React.FC<ControlPanelProps> = ({ 
    onGenerate, disabled, T, language, onSaveCase, onOpenSavedWork, 
    onOpenClinicalTools, isCaseActive, onGenerateNew, mobileView, onSetMobileView 
}) => {
  const [conditionInput, setConditionInput] = useState("Type 2 Diabetes Mellitus");
  const [disciplineInput, setDisciplineInput] = useState("Medicine");
  const [difficulty, setDifficulty] = useState("intermediate");
  const [history, setHistory] = useState<{ condition: string; discipline: string }[]>([]);
  const [showHistory, setShowHistory] = useState(false);
  const historyRef = useRef<HTMLDivElement>(null);
  const [isListening, setIsListening] = useState(false);
  const [activeInput, setActiveInput] = useState<'condition' | 'discipline' | null>(null);
  const recognitionRef = useRef<any>(null);
  const [micError, setMicError] = useState<string | null>(null);
  const [isSavedWorkMenuOpen, setIsSavedWorkMenuOpen] = useState(false);
  const savedWorkMenuRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    try {
      const storedHistory = JSON.parse(localStorage.getItem('generationHistory') || '[]');
      if (Array.isArray(storedHistory)) setHistory(storedHistory);
    } catch (e) { setHistory([]); }
  }, []);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
        if (historyRef.current && !historyRef.current.contains(event.target as Node)) setShowHistory(false);
        if (savedWorkMenuRef.current && !savedWorkMenuRef.current.contains(event.target as Node)) setIsSavedWorkMenuOpen(false);
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  const handleMicClick = (targetInput: 'condition' | 'discipline') => {
      if (!isSpeechRecognitionSupported) return;
      if (isListening && activeInput === targetInput && recognitionRef.current) { recognitionRef.current.stop(); return; }
      setMicError(null); setActiveInput(targetInput);
      const recognition = new SpeechRecognition();
      recognition.continuous = false; recognition.interimResults = true; recognition.maxAlternatives = 1;
      recognition.lang = language === 'bem' ? 'en-US' : language;
      recognition.onstart = () => setIsListening(true);
      recognition.onend = () => { setIsListening(false); setActiveInput(null); recognitionRef.current = null; };
      recognition.onerror = (event: any) => { setIsListening(false); setActiveInput(null); setMicError(event.error === 'not-allowed' ? T.micPermissionError : T.micGenericError); };
      recognition.onresult = (event: any) => { const transcript = event.results[0][0].transcript; if (targetInput === 'condition') setConditionInput(transcript); else setDisciplineInput(transcript); };
      try { recognitionRef.current = recognition; recognition.start(); } catch (err: any) { setIsListening(false); setActiveInput(null); }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const condition = conditionInput.trim();
    const discipline = disciplineInput.trim();
    if (condition && discipline && !disabled) {
      onGenerate(condition, discipline, difficulty);
      setHistory(prev => {
        const newEntry = { condition, discipline };
        if (prev.some(item => item.condition.toLowerCase() === condition.toLowerCase() && item.discipline.toLowerCase() === discipline.toLowerCase())) return prev;
        const updated = [newEntry, ...prev].slice(0, 15);
        localStorage.setItem('generationHistory', JSON.stringify(updated));
        return updated;
      });
    }
  };

  return (
    <div className="bg-white p-4 rounded-lg shadow-md border border-gray-200">
      {!isCaseActive ? (
        <form onSubmit={handleSubmit} className="flex flex-col sm:flex-row sm:flex-wrap gap-4 sm:items-end">
          <div className="flex flex-col sm:flex-1 sm:min-w-[240px]">
              <label htmlFor="condition-input" className="font-semibold text-gray-700 text-sm mb-1">{T.conditionLabel}</label>
              <div className="relative">
                  <input type="text" id="condition-input" value={conditionInput} onChange={(e) => setConditionInput(e.target.value)} disabled={disabled} placeholder={T.conditionPlaceholder} className="p-2 border border-gray-300 rounded-md focus:ring-2 focus:ring-brand-blue-light w-full bg-gray-50 text-black pr-10" />
                  {isSpeechRecognitionSupported && <MicButton onClick={() => handleMicClick('condition')} isListening={isListening && activeInput === 'condition'} disabled={disabled} title="Voice Input for Medical Condition" />}
              </div>
          </div>
          <div className="flex flex-col sm:flex-1 sm:min-w-[240px]">
              <label htmlFor="discipline-input" className="font-semibold text-gray-700 text-sm mb-1">{T.disciplineLabel}</label>
              <div className="relative">
                  <input type="text" id="discipline-input" value={disciplineInput} onChange={(e) => setDisciplineInput(e.target.value)} disabled={disabled} placeholder={T.disciplinePlaceholder} className="p-2 border border-gray-300 rounded-md focus:ring-2 focus:ring-brand-blue-light w-full bg-gray-50 text-black pr-10" />
                  {isSpeechRecognitionSupported && <MicButton onClick={() => handleMicClick('discipline')} isListening={isListening && activeInput === 'discipline'} disabled={disabled} title="Voice Input for Academic Discipline" />}
              </div>
          </div>
          <div className="flex flex-col w-full sm:w-auto">
              <label htmlFor="difficulty-select" className="font-semibold text-gray-700 text-sm mb-1">{T.difficultyLabel}</label>
              <select id="difficulty-select" value={difficulty} onChange={(e) => setDifficulty(e.target.value)} disabled={disabled} className="bg-gray-50 p-2 border border-gray-300 rounded-md h-[42px] pr-8 text-black" title="Select medical complexity level">
                  <option value="beginner">{T.difficultyBeginner}</option>
                  <option value="intermediate">{T.difficultyIntermediate}</option>
                  <option value="advanced">{T.difficultyAdvanced}</option>
              </select>
          </div>
          <div className="w-full sm:w-auto flex items-end space-x-2">
              <div className="relative" ref={historyRef}>
                  <button type="button" onClick={() => setShowHistory(s => !s)} disabled={disabled} title="View previously generated cases" className="h-[42px] bg-gray-100 hover:bg-gray-200 text-gray-700 font-bold p-2 rounded-md transition flex items-center justify-center"><svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm1-12a1 1 0 10-2 0v4a1 1 0 00.293.707l2.828 2.829a1 1 0 101.414-1.415L11 9.586V6z" clipRule="evenodd" /></svg></button>
                  {showHistory && (
                      <div className="absolute bottom-full mb-2 right-0 w-80 bg-white rounded-lg shadow-2xl border border-gray-200 z-20 max-h-80 overflow-y-auto animate-fade-in">
                          <div className="p-3 border-b border-gray-200 flex justify-between items-center sticky top-0 bg-white"><h4 className="font-semibold text-gray-800">{T.historyTitle}</h4>{history.length > 0 && <button onClick={() => { setHistory([]); localStorage.removeItem('generationHistory'); setShowHistory(false); }} className="text-xs text-red-500 hover:text-red-700 font-medium">Clear</button>}</div>
                          {history.length === 0 ? <p className="p-4 text-sm text-gray-500 text-center">{T.noHistoryMessage}</p> : <ul className="divide-y divide-gray-100">{history.map((item, index) => <li key={index} onClick={() => { setConditionInput(item.condition); setDisciplineInput(item.discipline); setShowHistory(false); }} className="p-3 hover:bg-gray-50 cursor-pointer transition"><p className="font-medium text-sm text-gray-800 truncate">{item.condition}</p><p className="text-xs text-gray-500 truncate">{item.discipline}</p></li>)}</ul>}
                      </div>
                  )}
              </div>
              <button type="submit" disabled={disabled || !conditionInput.trim() || !disciplineInput.trim()} title="Launch AI case synthesis (approx 15 seconds)" className="flex-grow h-[42px] bg-brand-blue hover:bg-blue-800 text-white font-bold py-2 px-4 rounded-md transition disabled:bg-gray-400 flex items-center justify-center space-x-2"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 3v2m6-2v2M9 19v2m6-2v2M5 9H3m2 6H3m18-6h-2m2 6h-2M12 6V3m0 18v-3"></path></svg><span>{T.generateButton}</span></button>
          </div>
        </form>
      ) : (
        <div className="flex items-center justify-between">
            <div className="flex flex-wrap items-center gap-2">
                <div className="relative" ref={savedWorkMenuRef}>
                    <button onClick={() => setIsSavedWorkMenuOpen(!isSavedWorkMenuOpen)} disabled={disabled} title="Access your saved medical cases and snippets" className="bg-gray-600 hover:bg-gray-700 text-white font-bold py-2 px-4 rounded-md transition flex items-center justify-center space-x-2 text-sm"><svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path d="M2 6a2 2 0 012-2h5l2 2h5a2 2 0 012 2v6a2 2 0 01-2 2H4a2 2 0 01-2-2V6z" /></svg><span className="hidden sm:inline">Collection</span></button>
                    {isSavedWorkMenuOpen && (
