const SmartContent: React.FC<{ content: string; language: string; T: Record<string, any>; onTriggerIllustration: (desc: string) => void }> = ({ content, language, T, onTriggerIllustration }) => {
    const graphMatch = content.match(/\[GRAPH: (.*?)\]/);
    const illustrateMatch = content.match(/\[ILLUSTRATE: (.*?)\]/);
    const diagramMatch = content.match(/\[DIAGRAM: (.*?)\]/);
    const cleanContent = content.replace(/\[GRAPH:.*?\]/g, '').replace(/\[ILLUSTRATE:.*?\]/g, '').replace(/\[DIAGRAM:.*?\]/g, '').trim();
    return (
        <div className="space-y-4">
            <MarkdownRenderer content={cleanContent} />
            <div className="pt-2">
                <SourceRenderer text={content} />
            </div>
            {graphMatch && <div className="mt-4"><ScientificGraph type={graphMatch[1] as any} title="Clinical Relationship" /></div>}
            {illustrateMatch && (
                <div className="flex justify-center mt-2">
                    <button onClick={() => onTriggerIllustration(illustrateMatch[1])} title="Visualize this scene using AI Image Generation" className="flex items-center gap-2 px-4 py-2 bg-blue-50 dark:bg-blue-900/30 text-brand-blue dark:text-blue-300 border border-blue-200 dark:border-blue-800 rounded-lg hover:bg-blue-100 dark:hover:bg-blue-900/50 transition text-xs font-bold shadow-sm">
                        <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h14a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
                        Clinical Illustration
                    </button>
                </div>
            )}
        </div>
    );
};

export const PatientCaseView: React.FC<PatientCaseViewProps> = ({ patientCase: initialCase, isGeneratingDetails, onSave, language, T, onSaveSnippet, onOpenShare, onOpenDiscussion, onGetMapImage, mapData }) => {
  const { state: patientCase, setState: setPatientCase, undo, redo, canUndo, canRedo, resetState } = useHistoryState<PatientCase>(initialCase);
