            {isEditing ? (
              <>
                <button onClick={undo} disabled={!canUndo} title="Undo Changes" className="p-2 text-gray-500 hover:bg-gray-100 dark:hover:bg-slate-800 disabled:opacity-30"><svg className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M10 2a1 1 0 00-1 1v1.135a4.002 4.002 0 00-2.995 2.562l-1.34-1.34a1 1 0 10-1.414 1.414l1.586 1.586A4.002 4.002 0 008 10a4 4 0 104-4V3a1 1 0 00-1-1zm0 8a2 2 0 100-4 2 2 0 000 4z" /></svg></button>
                <button onClick={redo} disabled={!canRedo} title="Redo Changes" className="p-2 text-gray-500 hover:bg-gray-100 dark:hover:bg-slate-800 disabled:opacity-30"><svg className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M10 18a1 1 0 001-1v-1.135a4.002 4.002 0 002.995-2.562l1.34 1.34a1 1 0 101.414-1.414l-1.586-1.586A4.002 4.002 0 0012 10a4 4 0 10-4 4V17a1 1 0 001 1zm0-8a2 2 0 100 4 2 2 0 000 4z" /></svg></button>
