const isSpeechRecognitionSupported = !!SpeechRecognition;

const getBCP47Language = (lang: string): string => {
    const map: Record<string, string> = {
        'en': 'en-US', 'es': 'es-ES', 'fr': 'fr-FR', 'zh': 'zh-CN', 'hi': 'hi-IN',
        'sw': 'sw-KE', 'ar': 'ar-SA', 'pt': 'pt-PT', 'ru': 'ru-RU', 'el': 'el-GR',
    };
    return map[lang] || 'en-US';
};

const cleanTextForDownload = (text: string): string => {
    return text
        .replace(/\[ILLUSTRATE:.*?\]/g, '')
        .replace(/\[DIAGRAM:.*?\]/g, '')
        .replace(/\[GRAPH:.*?\]/g, '')
        .replace(/\$t_{1\/2}\$/g, 'T½')
        .replace(/\$t_\{1\/2\}\$/g, 'T½')
        .replace(/\$CO_2\$/g, 'CO₂')
        .replace(/\$O_2\$/g, 'O₂')
        .replace(/\$H_2O\$/g, 'H₂O')
        .replace(/\$SpO_2\$/g, 'SpO₂')
        .replace(/\$Na\^+\$/g, 'Na⁺')
        .replace(/\$K\^+\$/g, 'K⁺')
        .replace(/\$Cl^-\$/g, 'Cl⁻')
        .replace(/\$HCO_3^-\$/g, 'HCO₃⁻')
        .replace(/\$/g, '')
        .replace(/\*\*\*/g, '')
        .replace(/\*\*/g, '')
        .replace(/\*/g, '')
        .replace(/__/g, '')
        .replace(/_/g, '')
        .replace(/#+\s/g, '')
        .replace(/\[(.*?)\]\(.*?\)/g, '$1')
        .trim();
};

function parseMarkdownTable(text: string) {
    const lines = text.trim().split('\n');
    if (lines.length < 3) return null;
    const rows = lines
        .filter(line => line.trim().startsWith('|'))
        .map(line => line.split('|').filter(cell => cell.trim() !== '').map(cell => cell.trim()));
    if (rows.length < 2) return null;
    const header = rows[0];
    const data = rows.slice(2);
    if (header.length === 0) return null;
    return { header, data };
}

function splitMessageContent(text: string) {
    const parts: {type: 'text' | 'table', content?: string, table?: {header: string[], data: string[][]}}[] = [];
    const lines = text.split('\n');
    let currentText = '';
    let inTable = false;
    let tableLines: string[] = [];

    for (let i = 0; i < lines.length; i++) {
        const line = lines[i];
        const isTableRow = line.trim().startsWith('|');

        if (isTableRow) {
            if (!inTable) {
                if (currentText.trim()) parts.push({type: 'text', content: currentText.trim()});
                currentText = '';
                inTable = true;
                tableLines = [line];
            } else {
                tableLines.push(line);
            }
        } else {
            if (inTable) {
                const table = parseMarkdownTable(tableLines.join('\n'));
                if (table) parts.push({type: 'table', table});
                else currentText += (currentText ? '\n' : '') + tableLines.join('\n');
                inTable = false;
                tableLines = [];
            }
            currentText += (currentText ? '\n' : '') + line;
        }
    }
    if (inTable) {
        const table = parseMarkdownTable(tableLines.join('\n'));
        if (table) parts.push({type: 'table', table});
        else currentText += (currentText ? '\n' : '') + tableLines.join('\n');
    }
    if (currentText.trim()) parts.push({type: 'text', content: currentText.trim()});
    return parts;
}

const svgToDataURL = async (svgEl: SVGSVGElement): Promise<string> => {
    const g = svgEl.querySelector('g');
    if (!g) return '';
    const bbox = g.getBBox();
    if (bbox.width === 0 || bbox.height === 0) return '';
    const padding = 40;
    const width = bbox.width + padding * 2;
    const height = bbox.height + padding * 2;
    const svgClone = svgEl.cloneNode(true) as SVGSVGElement;
    svgClone.setAttribute('width', width.toString());
    svgClone.setAttribute('height', height.toString());
    svgClone.setAttribute('viewBox', `${bbox.x - padding} ${bbox.y - padding} ${width} ${height}`);
    const gClone = svgClone.querySelector('g');
    if (gClone) gClone.removeAttribute('transform');
    const bgRect = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
    bgRect.setAttribute('width', width.toString());
    bgRect.setAttribute('height', height.toString());
    bgRect.setAttribute('fill', 'white');
    bgRect.setAttribute('x', `${bbox.x - padding}`);
    bgRect.setAttribute('y', `${bbox.y - padding}`);
    svgClone.prepend(bgRect);
    const xml = new XMLSerializer().serializeToString(svgClone);
    const svg64 = btoa(unescape(encodeURIComponent(xml)));
    const image64 = `data:image/svg+xml;base64,${svg64}`;
    return new Promise((resolve) => {
        const img = new Image();
        img.onload = () => {
            const canvas = document.createElement('canvas');
            const scale = 2;
            canvas.width = width * scale;
            canvas.height = height * scale;
            const ctx = canvas.getContext('2d');
            if (ctx) {
                ctx.scale(scale, scale);
                ctx.drawImage(img, 0, 0, width, height);
                resolve(canvas.toDataURL('image/png', 1.0));
            } else resolve('');
        };
        img.onerror = () => resolve('');
        img.src = image64;
    });
};

