    const chatRef = useRef<Chat | null>(null);
    const messagesEndRef = useRef<HTMLDivElement | null>(null);
    const shareMenuRef = useRef<HTMLDivElement | null>(null);
    const [isListening, setIsListening] = useState(false);
    const [micError, setMicError] = useState<string | null>(null);
    const recognitionRef = useRef<any>(null);

    useEffect(() => {
        if (isOpen) {
            const systemInstruction = `You are an expert medical tutor. Facilitate a deep Socratic discussion about "${topic.aspect}" for "${caseTitle}". Jump immediately into the dialogue. Provide technical details using Markdown Tables for comparisons. Cite PMIDs/DOIs for claims. Visual tags: [GRAPH: oxygen_dissociation], [DIAGRAM: description], [ILLUSTRATE: description]. Language: ${language}.`;
            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
            let chatHistory: Content[] | undefined = undefined;
            if (initialHistory && initialHistory.length > 0) {
                setMessages(initialHistory);
                chatHistory = initialHistory.filter(m => m.role !== 'system').map(m => ({ role: m.role as 'user' | 'model', parts: [{ text: m.text }] }));
                setIsSaved(true);
            } else {
                setMessages([{ role: 'system', text: T.chatWelcomeMessage }]);
                setIsSaved(false);
            }
            chatRef.current = ai.chats.create({
              model: 'gemini-3-pro-preview',
              config: { systemInstruction, thinkingConfig: { thinkingBudget: 32768 } },
              history: chatHistory
            });
        } else {
            chatRef.current = null;
            if (recognitionRef.current) recognitionRef.current.abort();
        }
    }, [isOpen, topic, caseTitle, language, T, initialHistory]);

    const handleMicClick = () => {
        if (!isSpeechRecognitionSupported) return;
        if (isListening) { recognitionRef.current?.stop(); return; }
        setMicError(null);
        const recognition = new SpeechRecognition();
        recognition.lang = getBCP47Language(language);
        recognition.continuous = false;
        recognition.interimResults = true;
        recognition.onstart = () => setIsListening(true);
        // FIX: Removed undefined setActiveInput(null) call from the mic recognition handler.
        recognition.onend = () => { setIsListening(false); };
        recognition.onerror = () => { setMicError(T.micGenericError); setIsListening(false); };
        recognition.onresult = (e: any) => setUserInput(e.results[0][0].transcript);
        recognitionRef.current = recognition;
        recognition.start();
    };

    useEffect(() => {
        messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }, [messages, isLoading]);

    const handleSendMessage = async (e?: React.FormEvent, customMsg?: string) => {
        if (e) e.preventDefault();
        const text = customMsg || userInput;
        if (!text.trim() || isLoading || !chatRef.current) return;
        const userMsg: ChatMessage = { role: 'user', text, timestamp: Date.now() };
        setMessages(prev => [...prev, userMsg]);
        setUserInput('');
        setIsLoading(true);
        setIsSaved(false); 
        try {
            const result = await retryWithBackoff(() => chatRef.current!.sendMessageStream({ message: text })) as AsyncIterable<GenerateContentResponse>;
            let currentResponse = '';
            setMessages(prev => [...prev, { role: 'model', text: '', timestamp: Date.now() }]);
            for await (const chunk of result) {
                currentResponse += chunk.text || '';
                setMessages(prev => {
                    const newMessages = [...prev];
                    newMessages[newMessages.length - 1] = { ...newMessages[newMessages.length - 1], text: currentResponse };
                    return newMessages;
                });
            }
        } catch (error) {
            setMessages(prev => [...prev, { role: 'system', text: T.errorChat }]);
        } finally { setIsLoading(false); }
    };

    // FIX: Added handleImageGenerated function to handle successful AI image generation within the discussion.
    const handleImageGenerated = (index: number, imageData: string) => {
        setMessages(prev => {
            const newMessages = [...prev];
            if (newMessages[index]) {
                newMessages[index] = { ...newMessages[index], imageData };
            }
            return newMessages;
        });
        setIsSaved(false);
        setActiveImagePrompt(null);
    };

    const handleConclude = () => {
        handleSendMessage(undefined, "Please provide a final summary of our discussion and list all the medical references and sources we used, including their PMIDs and DOIs.");
