// FIX: Added ConnectionExplanationModal component to resolve the "Cannot find name 'ConnectionExplanationModal'" error.
const ConnectionExplanationModal: React.FC<{
    isOpen: boolean;
    onClose: () => void;
    sourceNode: KnowledgeNode | null;
    targetNode: KnowledgeNode | null;
    caseTitle: string;
    language: string;
    T: Record<string, any>;
}> = ({ isOpen, onClose, sourceNode, targetNode, caseTitle, language, T }) => {
    const [explanation, setExplanation] = useState('');
    const [isLoading, setIsLoading] = useState(false);

    useEffect(() => {
        if (isOpen && sourceNode && targetNode) {
            const fetchExplanation = async () => {
                setIsLoading(true);
                try {
                    const res = await getConceptConnectionExplanation(sourceNode.label, targetNode.label, caseTitle, language);
                    setExplanation(res);
                } catch (e) {
                    setExplanation('Failed to generate connection explanation.');
                } finally {
                    setIsLoading(false);
                }
            };
            fetchExplanation();
        } else {
            setExplanation('');
        }
    }, [isOpen, sourceNode, targetNode, caseTitle, language]);

    if (!isOpen || !sourceNode || !targetNode) return null;

    return (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-[60] flex items-center justify-center p-4 animate-fade-in" onClick={onClose}>
