    position: { x: number; y: number } | null;
    onClose: () => void;
    onExplainConnection: (node: KnowledgeNode) => void;
    sourceNode: KnowledgeNode | null;
    allNodes: KnowledgeNode[];
}> = ({ position, onClose, onExplainConnection, sourceNode, allNodes }) => {
    if (!position || !sourceNode) return null;

    return (
        <div 
            className="fixed z-50 bg-white dark:bg-slate-800 border border-gray-200 dark:border-dark-border rounded-lg shadow-2xl py-2 w-56 animate-fade-in"
            style={{ top: position.y, left: position.x }}
            onMouseLeave={onClose}
        >
            <div className="px-4 py-1 border-b border-gray-100 dark:border-dark-border mb-1">
                <p className="text-[10px] font-bold text-gray-400 uppercase tracking-wider">Investigate Link</p>
            </div>
            <div className="max-h-60 overflow-y-auto">
                {allNodes.filter(n => n.id !== sourceNode.id).map(node => (
                    <button
                        key={node.id}
