interface KnowledgeMapProps {
    data: KnowledgeMapData;
    onNodeClick: (node: KnowledgeNode) => void;
    selectedNodeInfo: { node: KnowledgeNode; abstract: string; loading: boolean } | null;
    onClearSelection: () => void;
    isMapFullscreen: boolean;
    setIsMapFullscreen: (isFullscreen: boolean) => void;
    caseTitle: string;
    language: string;
    T: Record<string, any>;
    onDiscussNode: (nodeInfo: { node: KnowledgeNode; abstract: string; loading: boolean }) => void;
}

export const KnowledgeMap = forwardRef<any, KnowledgeMapProps>(({ data, onNodeClick, selectedNodeInfo, onClearSelection, isMapFullscreen, setIsMapFullscreen, caseTitle, language, T, onDiscussNode }, ref) => {
    const svgRef = useRef<SVGSVGElement | null>(null);
    const containerRef = useRef<HTMLDivElement | null>(null);
    const [isLoading, setIsLoading] = useState(true);
    const simulationRef = useRef<any>(null);
    const zoomRef = useRef<any>(null);
    const gRef = useRef<any>(null);
    const [contextMenu, setContextMenu] = useState<{ position: { x: number; y: number }; node: KnowledgeNode } | null>(null);
    const [explanationModal, setExplanationModal] = useState<{ source: KnowledgeNode; target: KnowledgeNode } | null>(null);
    const nodes = useMemo(() => data.nodes.map(n => ({ ...n })), [data.nodes]);
    const links = useMemo(() => data.links.map(l => ({ ...l })), [data.links]);
    useImperativeHandle(ref, () => ({ async captureAsImage() { if (svgRef.current) return await svgToDataURL(svgRef.current); return ''; } }));

    const resetZoom = useCallback(() => {
        if (!svgRef.current || !gRef.current || !containerRef.current || !zoomRef.current) return;
        const svg = d3.select(svgRef.current);
        const g = gRef.current;
        const bounds = g.node().getBBox();
        const parent = svg.node().parentElement;
        if (!parent) return;
        const { width, height } = parent.getBoundingClientRect();
        if (bounds.width === 0 || bounds.height === 0) return;
        const scale = Math.min(1.2, 0.85 / Math.max(bounds.width / width, bounds.height / height));
        const transform = d3.zoomIdentity.translate(width / 2 - scale * (bounds.x + bounds.width / 2), height / 2 - scale * (bounds.y + bounds.height / 2)).scale(scale);
        svg.transition().duration(750).call(zoomRef.current.transform, transform);
    }, []);

    useEffect(() => {
        if (!svgRef.current || !containerRef.current) return;
        setIsLoading(true);
        const svg = d3.select(svgRef.current);
        svg.selectAll('*').remove();
        const defs = svg.append("defs");

        defs.append("marker").attr("id", "arrow-head-map").attr("viewBox", "0 -3 6 6").attr("refX", 5.5).attr("refY", 0).attr("markerWidth", 5).attr("markerHeight", 5).attr("orient", "auto").attr("markerUnits", "strokeWidth").append("path").attr("d", "M0,-2.5 L6,0 L0,2.5").attr("fill", "#94a3b8");
        const filter = defs.append("filter").attr("id", "node-shadow-heavy").attr("x", "-50%").attr("y", "-50%").attr("width", "200%").attr("height", "200%");
        filter.append("feGaussianBlur").attr("in", "SourceAlpha").attr("stdDeviation", "3").attr("result", "blur");
        filter.append("feOffset").attr("in", "blur").attr("dx", "2").attr("dy", "4").attr("result", "offsetBlur");
        const feMerge = filter.append("feMerge"); feMerge.append("feMergeNode").attr("in", "offsetBlur"); feMerge.append("feMergeNode").attr("in", "SourceGraphic");

        Object.entries(DisciplineColors).forEach(([discipline, color]) => {
            const grad = defs.append("linearGradient").attr("id", `grad-${discipline.replace(/\s+/g, '-')}`).attr("x1", "0%").attr("y1", "0%").attr("x2", "0%").attr("y2", "100%");
            grad.append("stop").attr("offset", "0%").attr("stop-color", color).attr("stop-opacity", 1);
            grad.append("stop").attr("offset", "100%").attr("stop-color", d3.color(color).darker(0.3)).attr("stop-opacity", 1);
        });

        const { width, height } = containerRef.current.getBoundingClientRect();
        const g = svg.append('g'); gRef.current = g;
        const zoom = d3.zoom().scaleExtent([0.1, 4]).on('zoom', (event: any) => g.attr('transform', event.transform));
        zoomRef.current = zoom; svg.call(zoom); svg.on("click", onClearSelection);

        simulationRef.current = d3.forceSimulation(nodes)
            .force('link', d3.forceLink(links).id((d: any) => d.id).distance(220).strength(0.4))
            .force('charge', d3.forceManyBody().strength(-2500))
            .force('center', d3.forceCenter(width / 2, height / 2))
            .force('collide', d3.forceCollide().radius(120).iterations(3))
            .on('end', () => { setIsLoading(false); resetZoom(); });

        const linkLines = g.append("g").attr("class", "links").selectAll("path").data(links).join("path").attr("fill", "none").attr("stroke", "#cbd5e1").attr("stroke-opacity", 0.5).attr("stroke-width", 2).attr("marker-end", "url(#arrow-head-map)");
        const linkLabels = g.append("g").attr("class", "link-labels").selectAll("g").data(links).join("g").attr("class", "opacity-40 transition-opacity hover:opacity-100");
        linkLabels.append("rect").attr("rx", 5).attr("ry", 5).attr("fill", "white").attr("fill-opacity", 0.95).attr("stroke", "#e2e8f0").attr("stroke-width", 0.5);
        linkLabels.append("text").text((d: any) => d.description).attr("font-size", "9px").attr("fill", "#64748b").attr("font-weight", "600").attr("text-anchor", "middle").attr("dy", "0.35em").attr("font-family", "Inter, sans-serif").attr("pointer-events", "none").each(function(d: any) { const bbox = (this as any).getBBox(); d.labelWidth = bbox.width + 10; d.labelHeight = bbox.height + 6; });
        linkLabels.select("rect").attr("width", (d: any) => d.labelWidth).attr("height", (d: any) => d.labelHeight).attr("x", (d: any) => -d.labelWidth / 2).attr("y", (d: any) => -d.labelHeight / 2);

        const node = g.append('g').attr("class", "nodes").selectAll('g').data(nodes).join('g').attr('class', 'node-group cursor-pointer').call(d3.drag().on('start', (event: any, d: any) => { if (!event.active) simulationRef.current.alphaTarget(0.3).restart(); d.fx = d.x; d.fy = d.y; }).on('drag', (event: any, d: any) => { d.fx = event.x; d.fy = event.y; }).on('end', (event: any, d: any) => { if (!event.active) simulationRef.current.alphaTarget(0); d.fx = null; d.fy = null; })).on('click', (event: MouseEvent, d: any) => { event.stopPropagation(); onNodeClick(d); }).on('contextmenu', (event: MouseEvent, d: any) => { event.preventDefault(); setContextMenu({ position: { x: event.clientX, y: event.clientY }, node: d }); });

        node.append('title').text((d: any) => `Concept: ${d.label} (${d.discipline})\nClick to view summary.`);

        node.append('rect')
            .attr('rx', 25).attr('ry', 25)
            .attr('fill', (d: any) => DisciplineColors[d.discipline] || '#6b7280')
            .attr('stroke', '#ffffff')
            .attr('stroke-width', 2.5)
            .style('filter', 'url(#node-shadow-heavy)');

        node.append('text')
            .text((d: any) => d.label)
            .attr("font-family", "'Inter', sans-serif")
            .attr('font-size', '14px')
            .attr('font-weight', '800')
            .attr('fill', (d: any) => getContrastColor(DisciplineColors[d.discipline] || '#6b7280'))
            .attr('text-anchor', 'middle')
            .attr('dy', '0.15em')
            .each(function(d: any) { 
                const bbox = (this as any).getBBox(); 
                d.pillWidth = Math.max(130, bbox.width + 48); 
                d.pillHeight = 50; 
            });

        node.select('rect')
            .attr('width', (d: any) => d.pillWidth)
            .attr('height', (d: any) => d.pillHeight)
            .attr('x', (d: any) => -d.pillWidth / 2)
            .attr('y', (d: any) => -d.pillHeight / 2);

        node.append('text')
            .text((d: any) => (d.discipline || '').toUpperCase())
            .attr('font-size', '8.5px')
            .attr('font-weight', '900')
            .attr('fill', (d: any) => getContrastColor(DisciplineColors[d.discipline] || '#6b7280'))
            .attr('opacity', 0.8)
            .attr('letter-spacing', '0.06em')
            .attr('text-anchor', 'middle')
            .attr('dy', '1.75em');

        function intersectRect(rect: any, point: any) { const cx = rect.x, cy = rect.y, dx = point.x - cx, dy = point.y - cy, w = (rect.pillWidth || 0) / 2, h = (rect.pillHeight || 0) / 2; if (w === 0 || h === 0) return { x: cx, y: cy }; if (Math.abs(dy * w) < Math.abs(dx * h)) return dx > 0 ? { x: cx + w, y: cy + dy * w / dx } : { x: cx - w, y: cy - dy * w / dx }; else return dy > 0 ? { x: cx + dx * h / dy, y: cy + h } : { x: cx - dx * h / dy, y: cy - h }; }

        simulationRef.current.on('tick', () => { 
            linkLines.attr('d', (d: any) => { if (!d.source.x || !d.target.x) return null; const s = intersectRect(d.source, d.target), t = intersectRect(d.target, d.source); return `M ${s.x} ${s.y} L ${t.x} ${t.y}`; }); 
            linkLabels.attr('transform', (d: any) => { if (!d.source.x || !d.target.x) return null; const midX = (d.source.x + d.target.x) / 2, midY = (d.source.y + d.target.y) / 2, dx = d.target.x - d.source.x, dy = d.target.y - d.source.y; let angle = Math.atan2(dy, dx) * 180 / Math.PI; if (angle > 90 || angle < -90) angle += 180; return `translate(${midX}, ${midY}) rotate(${angle})`; }); 
            node.attr('transform', (d: any) => `translate(${d.x}, ${d.y})`); 
        });

        return () => simulationRef.current.stop();
    }, [data, nodes, links, onNodeClick, resetZoom, onClearSelection]);

    return (
        <div ref={containerRef} className={`w-full h-full bg-slate-50 dark:bg-slate-900 shadow-inner border border-gray-200 dark:border-dark-border overflow-hidden transition-colors duration-300 ${isMapFullscreen ? 'fixed inset-0 z-40' : 'relative rounded-xl'}`}>
            {isLoading && <div className="absolute inset-0 z-20 flex items-center justify-center bg-slate-50/50 dark:bg-dark-bg/50 backdrop-blur-sm"><LoadingSpinner /></div>}
            <svg ref={svgRef} className="w-full h-full touch-none"></svg>
            <MapControls onZoomIn={() => zoomRef.current && d3.select(svgRef.current).transition().call(zoomRef.current.scaleBy, 1.3)} onZoomOut={() => zoomRef.current && d3.select(svgRef.current).transition().call(zoomRef.current.scaleBy, 0.7)} onReset={resetZoom} onToggleFullscreen={() => setIsMapFullscreen(!isMapFullscreen)} isFullscreen={isMapFullscreen} />
            {selectedNodeInfo && <ConceptCard nodeInfo={selectedNodeInfo} onClose={onClearSelection} onDiscuss={onDiscussNode} T={T} />}
            <ContextMenu position={contextMenu?.position || null} onClose={() => setContextMenu(null)} onExplainConnection={targetNode => { if (contextMenu) setExplanationModal({ source: contextMenu.node, target: targetNode }); }} sourceNode={contextMenu?.node || null} allNodes={nodes as any} />
            <ConnectionExplanationModal isOpen={!!explanationModal} onClose={() => setExplanationModal(null)} sourceNode={explanationModal?.source || null} targetNode={explanationModal?.target || null} caseTitle={caseTitle} language={language} T={T} />
        </div>
    );
});

