export const enrichCaseWithWebSources = async (patientCase: PatientCase, language: string): Promise<{ newEvidence: TraceableEvidence[]; newReadings: FurtherReading[]; groundingSources: any[] }> => {
    const ai = getAiClient();
    const prompt = `Find 2 recent robust evidence-based clinical claims with PMIDs and 2 meta-analyses readings for "${patientCase.title}". Language: ${language}. Format as JSON.`;
    const response: GenerateContentResponse = await retryWithBackoff(() => ai.models.generateContent({
        model: FAST_MODEL,
        contents: prompt,
        config: { tools: [{ googleSearch: {} }], temperature: 0.2 },
    }));
    const jsonMatch = (response.text || "").match(/```json\n([\s\S]*?)\n```/);
