const getAiClient = () => {
    return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

export async function retryWithBackoff<T>(
    fn: () => Promise<T>,
    maxRetries: number = 3,
    initialDelay: number = 1000
): Promise<T> {
    let lastError: any;
    for (let i = 0; i < maxRetries; i++) {
        try {
            return await fn();
        } catch (error: any) {
            lastError = error;
            const status = error?.status || error?.response?.status;
            if (status !== 429 && (status < 500 || status >= 600)) {
                throw error;
            }
            const delay = initialDelay * Math.pow(2, i);
            await new Promise(resolve => setTimeout(resolve, delay));
        }
    }
    throw lastError;
}

const THINKING_MODEL = "gemini-3-pro-preview"; 
const FAST_MODEL = "gemini-3-flash-preview"; 

const SYNTHESIS_GUIDELINE = `
**CRITICAL CLINICAL FIDELITY & FORMATTING RULES:**
1. **Robust Evidence (MANDATORY):** Every major clinical claim MUST be supported by a verified reference. Use format: "Claim [PMID: 12345678]".
2. **High-Fidelity Tables (STRICT REQUIREMENT):** You MUST render ALL Vital Signs, Lab Panels, and Medications as properly formatted Markdown Tables. DO NOT use plain text or lists for this data.
   - **Vital Signs Table Structure:**
     | Parameter | Value |
     | :--- | :--- |
     | BP | 120/80 mmHg |
     | HR | 72 bpm |
   - **Lab Panel Table Structure:**
     | Analyte | Result | Reference |
     | :--- | :--- | :--- |
     | HbA1c | 7.5% | <6.5% |
   - **Medications Table Structure:**
     | Medication | Dose | Frequency |
     | :--- | :--- | :--- |
     | Metformin | 500mg | BD |
3. **Visual Triggers:** Strategically embed: \`[GRAPH: oxygen_dissociation]\`, \`[DIAGRAM: description]\`, or \`[ILLUSTRATE: description]\`.
4. **Quiz:** Generate exactly 5 high-quality multiple-choice questions.
5. **Holistic Connections:** In 'multidisciplinaryConnections', include ALL disciplines relevant to comprehensive management.
6. **Map Disciplines:** Only use these exact labels: Biochemistry, Pharmacology, Physiology, Psychology, Sociology, Pathology, Immunology, Genetics, Diagnostics, Treatment, Physiotherapy, Occupational Therapy, Anaesthesia, Pain Management, Nursing, Nutrition & Dietetics, Social Work, Speech & Language Therapy.
`;

const diagramNodeSchema = {
    type: Type.OBJECT,
    properties: {
        id: { type: Type.STRING },
        label: { type: Type.STRING },
        description: { type: Type.STRING },
    },
    required: ["id", "label"]
};

const diagramLinkSchema = {
    type: Type.OBJECT,
    properties: {
        source: { type: Type.STRING },
        target: { type: Type.STRING },
        label: { type: Type.STRING }
    },
    required: ["source", "target", "label"]
};

const diagramDataSchema = {
    type: Type.OBJECT,
    properties: {
        nodes: { type: Type.ARRAY, items: diagramNodeSchema },
        links: { type: Type.ARRAY, items: diagramLinkSchema }
    },
    required: ["nodes", "links"],
    nullable: true
};

const educationalContentSchema = {
    type: Type.OBJECT,
    properties: {
        type: { type: Type.STRING, enum: ["Diagram", "Graph", "Formula", "Image"] },
        title: { type: Type.STRING },
        description: { type: Type.STRING },
        reference: { type: Type.STRING },
        diagramData: { ...diagramDataSchema }
    },
    required: ["type", "title", "description", "reference"]
};

const quizQuestionSchema = {
    type: Type.OBJECT,
    properties: {
        question: { type: Type.STRING },
        options: { type: Type.ARRAY, items: { type: Type.STRING } },
        correctAnswerIndex: { type: Type.INTEGER },
        explanation: { type: Type.STRING }
    },
    required: ["question", "options", "correctAnswerIndex", "explanation"]
};

const corePatientCaseSchema = {
    type: Type.OBJECT,
    properties: {
        title: { type: Type.STRING },
        patientProfile: { type: Type.STRING },
        presentingComplaint: { type: Type.STRING },
        history: { type: Type.STRING },
        procedureDetails: {
            type: Type.OBJECT,
            properties: {
                procedureName: { type: Type.STRING },
                asaScore: { type: Type.STRING, enum: ['1', '2', '3', '4', '5', '6', '1E', '2E', '3E', '4E', '5E', '6E'] }
            },
            required: ["procedureName", "asaScore"],
            nullable: true
        }
    },
    required: ["title", "patientProfile", "presentingComplaint", "history"]
};

const mainDetailsSchema = {
    type: Type.OBJECT,
    properties: {
        biochemicalPathway: { ...educationalContentSchema },
        multidisciplinaryConnections: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              discipline: { type: Type.STRING },
