interface KnowledgeMapProps {
    data: KnowledgeMapData;
    onNodeClick: (node: KnowledgeNode) => void;
    selectedNodeInfo: { node: KnowledgeNode; abstract: string; loading: boolean } | null;
    onClearSelection: () => void;
    isMapFullscreen: boolean;
    setIsMapFullscreen: (isFullscreen: boolean) => void;
    caseTitle: string;
    language: string;
    T: Record<string, any>;
    onDiscussNode: (nodeInfo: { node: KnowledgeNode; abstract: string; loading: boolean }) => void;
}

export const KnowledgeMap = forwardRef<any, KnowledgeMapProps>(({ data, onNodeClick, selectedNodeInfo, onClearSelection, isMapFullscreen, setIsMapFullscreen, caseTitle, language, T, onDiscussNode }, ref) => {
    const svgRef = useRef<SVGSVGElement | null>(null);
    const containerRef = useRef<HTMLDivElement | null>(null);
    const [isLoading, setIsLoading] = useState(true);
    const simulationRef = useRef<any>(null);
    const zoomRef = useRef<any>(null);
    const gRef = useRef<any>(null);
    const [hoveredNode, setHoveredNode] = useState<{ node: KnowledgeNode; position: { x: number; y: number } } | null>(null);
    const [hoveredLink, setHoveredLink] = useState<KnowledgeLink | null>(null);

    const nodes = useMemo(() => data.nodes.map(n => ({ ...n })), [data.nodes]);
    const links = useMemo(() => data.links.map(l => ({ ...l })), [data.links]);

    useImperativeHandle(ref, () => ({ async captureAsImage() { if (svgRef.current) return await svgToDataURL(svgRef.current); return ''; } }));

    const resetZoom = useCallback(() => {
        if (!svgRef.current || !gRef.current || !containerRef.current || !zoomRef.current) return;
        const svg = d3.select(svgRef.current);
        const g = gRef.current;
        const bounds = g.node().getBBox();
        const { width, height } = containerRef.current.getBoundingClientRect();
        if (bounds.width === 0 || bounds.height === 0) return;
        const scale = Math.min(1.2, 0.85 / Math.max(bounds.width / width, bounds.height / height));
        const transform = d3.zoomIdentity.translate(width / 2 - scale * (bounds.x + bounds.width / 2), height / 2 - scale * (bounds.y + bounds.height / 2)).scale(scale);
        svg.transition().duration(750).call(zoomRef.current.transform, transform);
    }, []);

    useEffect(() => {
        if (!containerRef.current) return;
        const observer = new ResizeObserver(() => {
            if (svgRef.current && gRef.current && !isLoading) {
                 const { width, height } = containerRef.current!.getBoundingClientRect();
                 if (width > 0 && height > 0 && simulationRef.current) {
                    simulationRef.current.force('center', d3.forceCenter(width / 2, height / 2));
                    simulationRef.current.alpha(0.1).restart();
                 }
            }
        });
        observer.observe(containerRef.current);
        return () => observer.disconnect();
    }, [isLoading]);

    useEffect(() => {
        if (!svgRef.current || !containerRef.current) return;
        setIsLoading(true);
        const svg = d3.select(svgRef.current);
        svg.selectAll('*').remove();

        // Marker definition for sharper arrows
        svg.append('defs').append('marker')
            .attr('id', 'map-arrowhead')
            .attr('viewBox', '0 -5 10 10')
            .attr('refX', 8) // Pulls arrow slightly back from the point
            .attr('refY', 0)
            .attr('markerWidth', 6)
            .attr('markerHeight', 6)
            .attr('orient', 'auto')
            .append('path')
            .attr('d', 'M0,-5L10,0L0,5')
            .attr('fill', '#94a3b8');

        const { width, height } = containerRef.current.getBoundingClientRect();
        const g = svg.append('g'); gRef.current = g;
        const zoom = d3.zoom().scaleExtent([0.1, 4]).on('zoom', (event: any) => g.attr('transform', event.transform));
        zoomRef.current = zoom; svg.call(zoom);

        simulationRef.current = d3.forceSimulation(nodes)
            .force('link', d3.forceLink(links).id((d: any) => d.id).distance(220).strength(0.6))
            .force('charge', d3.forceManyBody().strength(-2500))
            .force('center', d3.forceCenter(width / 2, height / 2))
            .force('collide', d3.forceCollide().radius(120).iterations(2))
            .velocityDecay(0.4)
            .on('end', () => { setIsLoading(false); resetZoom(); });

        const linkPaths = g.append("g").selectAll("path").data(links).join("path")
            .attr("fill", "none")
            .attr("stroke", "#cbd5e1")
            .attr("stroke-opacity", 0.6)
            .attr("stroke-width", 2)
            .attr("marker-end", "url(#map-arrowhead)")
            .attr("class", "link-path transition-all cursor-help")
            .on('mouseenter', (event: any, d: any) => {
                d3.select(event.currentTarget).attr("stroke", "#3b82f6").attr("stroke-opacity", 1).attr("stroke-width", 3);
                setHoveredLink(d);
            })
            .on('mouseleave', (event: any) => {
                d3.select(event.currentTarget).attr("stroke", "#cbd5e1").attr("stroke-opacity", 0.6).attr("stroke-width", 2);
                setHoveredLink(null);
            });

        const node = g.append('g').selectAll('g').data(nodes).join('g').attr('class', 'node-group cursor-pointer')
            .call(d3.drag().on('start', (event: any, d: any) => { if (!event.active) simulationRef.current.alphaTarget(0.3).restart(); d.fx = d.x; d.fy = d.y; }).on('drag', (event: any, d: any) => { d.fx = event.x; d.fy = event.y; }).on('end', (event: any, d: any) => { if (!event.active) simulationRef.current.alphaTarget(0); d.fx = null; d.fy = null; }))
            .on('click', (event: MouseEvent, d: any) => { event.stopPropagation(); onNodeClick(d); })
            .on('mouseenter', (event: MouseEvent, d: any) => {
                setHoveredNode({ node: d, position: { x: event.clientX, y: event.clientY } });
                d3.select(event.currentTarget as any).select('rect').transition().duration(200).attr('stroke-width', 4).attr('stroke', '#3b82f6');
            })
            .on('mousemove', (event: MouseEvent) => {
                setHoveredNode(prev => prev ? { ...prev, position: { x: event.clientX, y: event.clientY } } : null);
            })
            .on('mouseleave', (event: MouseEvent) => {
                setHoveredNode(null);
                d3.select(event.currentTarget as any).select('rect').transition().duration(200).attr('stroke-width', 2.5).attr('stroke', '#ffffff');
            });

        node.append('rect')
            .attr('rx', 25).attr('ry', 25)
            .attr('fill', (d: any) => DisciplineColors[d.discipline] || '#6b7280')
            .attr('stroke', '#ffffff')
            .attr('stroke-width', 2.5)
            .attr('filter', 'drop-shadow(0px 4px 6px rgba(0,0,0,0.1))');

        node.append('text')
            .text((d: any) => d.label)
            .attr("font-family", "Inter, sans-serif")
            .attr('font-size', '13px')
            .attr('font-weight', '800')
            .attr('fill', (d: any) => getContrastColor(DisciplineColors[d.discipline] || '#6b7280'))
            .attr('text-anchor', 'middle')
            .attr('dy', '0.15em')
            .each(function(d: any) { 
                const bbox = (this as any).getBBox(); 
                d.pillWidth = Math.max(120, bbox.width + 40); 
                d.pillHeight = 46; 
            });

        node.select('rect')
            .attr('width', (d: any) => d.pillWidth)
            .attr('height', (d: any) => d.pillHeight)
            .attr('x', (d: any) => -d.pillWidth / 2)
            .attr('y', (d: any) => -d.pillHeight / 2);

        node.append('text')
            .text((d: any) => (d.discipline || '').toUpperCase())
            .attr('font-size', '8px')
            .attr('font-weight', '900')
            .attr('fill', (d: any) => getContrastColor(DisciplineColors[d.discipline] || '#6b7280'))
            .attr('opacity', 0.8)
            .attr('letter-spacing', '0.08em')
            .attr('text-anchor', 'middle')
            .attr('dy', '1.6em');

        simulationRef.current.on('tick', () => { 
            linkPaths.attr('d', (d: any) => {
                if (!d.source.x || !d.target.x) return null;
                // Calculate curved path points based on intersection
                const s = intersectRect(d.source, d.target);
                const t = intersectRect(d.target, d.source);
                const dx = t.x - s.x;
                const dy = t.y - s.y;
                const dr = Math.sqrt(dx * dx + dy * dy) * 1.5; // Curvature factor
                return `M${s.x},${s.y}A${dr},${dr} 0 0,1 ${t.x},${t.y}`;
            }); 
            node.attr('transform', (d: any) => `translate(${d.x}, ${d.y})`); 
        });

        return () => simulationRef.current.stop();
    }, [data, nodes, links, onNodeClick, resetZoom]);

    return (
        <div ref={containerRef} className={`w-full h-full bg-slate-50 dark:bg-slate-900 shadow-inner border border-gray-200 dark:border-dark-border overflow-hidden transition-colors duration-300 ${isMapFullscreen ? 'fixed inset-0 z-40' : 'relative rounded-xl'}`}>
            {isLoading && <div className="absolute inset-0 z-20 flex items-center justify-center bg-slate-50/50 dark:bg-dark-bg/50 backdrop-blur-sm"><LoadingSpinner /></div>}
            <svg ref={svgRef} className="w-full h-full touch-none" onClick={onClearSelection}></svg>
            <MapControls onZoomIn={() => zoomRef.current && d3.select(svgRef.current).transition().call(zoomRef.current.scaleBy, 1.3)} onZoomOut={() => zoomRef.current && d3.select(svgRef.current).transition().call(zoomRef.current.scaleBy, 0.7)} onReset={resetZoom} onToggleFullscreen={() => setIsMapFullscreen(!isMapFullscreen)} isFullscreen={isMapFullscreen} />
            <NodeTooltip node={hoveredNode?.node || null} position={hoveredNode?.position || null} />

            {hoveredLink && (
                <div className="absolute bottom-4 right-4 bg-white/90 dark:bg-slate-800/90 p-2 px-3 rounded-lg shadow-lg border border-brand-blue/20 text-[10px] max-w-[200px] animate-fade-in pointer-events-none">
                    <p className="font-black uppercase text-gray-400 mb-1">Relationship</p>
                    <p className="text-gray-800 dark:text-slate-200 leading-tight italic font-medium">{hoveredLink.description}</p>
                </div>
            )}

            {selectedNodeInfo && <ConceptCard nodeInfo={selectedNodeInfo} onClose={onClearSelection} onDiscuss={onDiscussNode} T={T} />}
        </div>
    );
});

import React, { useEffect, useRef, useCallback } from 'react';

declare const d3: any;

interface ScientificGraphProps {
    type: 'oxygen_dissociation' | 'other';
    title: string;
    className?: string;
}

export const ScientificGraph: React.FC<ScientificGraphProps> = ({ type, title, className }) => {
    const containerRef = useRef<HTMLDivElement>(null);

    const renderGraph = useCallback(() => {
        if (!containerRef.current) return;
        const container = d3.select(containerRef.current);
        container.selectAll('*').remove();

        const rect = containerRef.current.getBoundingClientRect();
        if (rect.width === 0) return; // Wait for size

        const margin = { top: 50, right: 40, bottom: 60, left: 70 };
        const width = rect.width - margin.left - margin.right;
        const height = 350 - margin.top - margin.bottom;

        if (width <= 0 || height <= 0) return;

        const isDark = document.documentElement.classList.contains('dark');
        const textColor = isDark ? '#e2e8f0' : '#1e293b';
        const gridColor = isDark ? '#334155' : '#e2e8f0';

        const svg = container.append('svg')
            .attr('width', width + margin.left + margin.right)
            .attr('height', height + margin.top + margin.bottom)
            .attr('class', 'overflow-visible')
            .append('g')
            .attr('transform', `translate(${margin.left},${margin.top})`);

        if (type === 'oxygen_dissociation') {
            const n = 2.8;
            const p50Normal = 26.6;
            const p50Right = 34.6;
            const p50Left = 18.6;

            const calcSaO2 = (p: number, p50: number) => (Math.pow(p, n) / (Math.pow(p, n) + Math.pow(p50, n))) * 100;

            const generateData = (p50Val: number) => {
                const arr = [];
                for (let p = 0; p <= 115; p += 0.5) {
                    arr.push({ x: p, y: calcSaO2(p, p50Val) });
                }
                return arr;
            };

            const dataNormal = generateData(p50Normal);
            const dataRight = generateData(p50Right);
            const dataLeft = generateData(p50Left);

            const x = d3.scaleLinear().domain([0, 110]).range([0, width]);
            const y = d3.scaleLinear().domain([0, 105]).range([height, 0]);

            // Gridlines
            svg.append('g').attr('class', 'grid').attr('transform', `translate(0,${height})`).call(d3.axisBottom(x).ticks(5).tickSize(-height).tickFormat('')).attr('stroke', gridColor).attr('stroke-opacity', 0.1);
            svg.append('g').attr('class', 'grid').call(d3.axisLeft(y).ticks(5).tickSize(-width).tickFormat('')).attr('stroke', gridColor).attr('stroke-opacity', 0.1);

            // Axes
            const xAxis = svg.append('g').attr('transform', `translate(0,${height})`).call(d3.axisBottom(x).ticks(10));
            xAxis.selectAll('text').attr('fill', textColor).attr('font-size', '10px');
            xAxis.selectAll('line').attr('stroke', textColor);
            xAxis.select('.domain').attr('stroke', textColor);

            const yAxis = svg.append('g').call(d3.axisLeft(y).ticks(10));
            yAxis.selectAll('text').attr('fill', textColor).attr('font-size', '10px');
            yAxis.selectAll('line').attr('stroke', textColor);
            yAxis.select('.domain').attr('stroke', textColor);

            // Labels
            svg.append('text').attr('x', width / 2).attr('y', height + 45).attr('text-anchor', 'middle').attr('font-size', '12px').attr('fill', textColor).attr('font-weight', '700').text('PO₂ (mmHg)');
            svg.append('text').attr('transform', 'rotate(-90)').attr('y', -50).attr('x', -height / 2).attr('text-anchor', 'middle').attr('font-size', '12px').attr('fill', textColor).attr('font-weight', '700').text('SaO₂ (%)');
            svg.append('text').attr('x', width / 2).attr('y', -25).attr('text-anchor', 'middle').attr('font-weight', '900').attr('fill', textColor).attr('font-size', '16px').attr('letter-spacing', '-0.02em').text(title);

            const line = d3.line().x((d: any) => x(d.x)).y((d: any) => y(d.y)).curve(d3.curveBasis);

            // Left Shift Path
            svg.append('path').datum(dataLeft).attr('fill', 'none').attr('stroke', '#38bdf8').attr('stroke-width', 2).attr('stroke-dasharray', '5,3').attr('d', line).attr('opacity', 0.6);
            // Right Shift Path
            svg.append('path').datum(dataRight).attr('fill', 'none').attr('stroke', '#f87171').attr('stroke-width', 2).attr('stroke-dasharray', '5,3').attr('d', line).attr('opacity', 0.6);
            // Normal Path
            svg.append('path').datum(dataNormal).attr('fill', 'none').attr('stroke', isDark ? '#60a5fa' : '#1e3a8a').attr('stroke-width', 4).attr('d', line);

            // Interactivity Overlay
            const focus = svg.append('g').style('display', 'none');

            focus.append('line').attr('class', 'x-hover-line hover-line').attr('y1', 0).attr('y2', height).attr('stroke', textColor).attr('stroke-width', 1).attr('stroke-dasharray', '3,3');
            focus.append('circle').attr('r', 5).attr('fill', '#1e3a8a').attr('stroke', '#fff').attr('stroke-width', 2);

            const tooltip = focus.append('g').attr('class', 'tooltip-container');
            tooltip.append('rect').attr('width', 120).attr('height', 50).attr('rx', 8).attr('fill', isDark ? '#1e293b' : '#ffffff').attr('stroke', isDark ? '#334155' : '#e2e8f0').attr('stroke-width', 1).attr('filter', 'drop-shadow(0 4px 6px rgba(0,0,0,0.1))');
            const tooltipText = tooltip.append('text').attr('x', 10).attr('y', 20).attr('font-size', '11px').attr('font-weight', '700').attr('fill', textColor);
            const po2Label = tooltipText.append('tspan').attr('x', 10).attr('dy', '0em');
            const sao2Label = tooltipText.append('tspan').attr('x', 10).attr('dy', '1.4em');

            const bisect = d3.bisector((d: any) => d.x).left;

            svg.append('rect')
                .attr('width', width)
                .attr('height', height)
                .attr('fill', 'none')
                .attr('pointer-events', 'all')
                .on('mouseover', () => focus.style('display', null))
                .on('mouseout', () => focus.style('display', 'none'))
                .on('mousemove', function(event: any) {
                    const mouseX = d3.pointer(event)[0];
                    const x0 = x.invert(mouseX);
                    const i = bisect(dataNormal, x0, 1);
                    const d0 = dataNormal[i - 1];
                    const d1 = dataNormal[i];
                    const d = x0 - d0.x > d1.x - x0 ? d1 : d0;

                    focus.select('circle').attr('transform', `translate(${x(d.x)},${y(d.y)})`);
                    focus.select('.x-hover-line').attr('transform', `translate(${x(d.x)},0)`);

                    po2Label.text(`PO₂: ${d.x.toFixed(1)} mmHg`);
                    sao2Label.text(`SaO₂: ${d.y.toFixed(1)}%`);

                    let tx = x(d.x) + 15;
                    let ty = y(d.y) - 60;
                    if (tx + 120 > width) tx = x(d.x) - 135;
                    if (ty < 0) ty = y(d.y) + 15;
                    tooltip.attr('transform', `translate(${tx},${ty})`);
                });

            const addInfoTrigger = (xPos: number, yPos: number, color: string, titleStr: string, desc: string) => {
                const group = svg.append('g').attr('class', 'info-trigger cursor-help');
                group.append('circle').attr('cx', xPos).attr('cy', yPos).attr('r', 8).attr('fill', color).attr('stroke', '#fff').attr('stroke-width', 2);
                group.append('text').attr('x', xPos).attr('y', yPos).attr('dy', '0.35em').attr('text-anchor', 'middle').attr('fill', '#fff').attr('font-size', '10px').attr('font-weight', 'bold').text('?');

                const infoBox = group.append('g').style('opacity', 0).attr('pointer-events', 'none');
                infoBox.append('rect').attr('x', xPos + 12).attr('y', yPos - 20).attr('width', 200).attr('height', 80).attr('rx', 8).attr('fill', isDark ? '#1e293b' : '#ffffff').attr('stroke', color).attr('stroke-width', 2).attr('filter', 'drop-shadow(0 10px 15px rgba(0,0,0,0.1))');
                const iText = infoBox.append('text').attr('x', xPos + 22).attr('y', yPos + 2).attr('font-size', '11px').attr('fill', textColor);
                iText.append('tspan').attr('font-weight', 'bold').attr('fill', color).text(titleStr);
                const lines = desc.split('\n');
                lines.forEach((l, idx) => iText.append('tspan').attr('x', xPos + 22).attr('dy', idx === 0 ? '1.4em' : '1.2em').attr('font-weight', 'normal').attr('fill', textColor).text(l));

                group.on('mouseenter', () => infoBox.transition().duration(200).style('opacity', 1))
                     .on('mouseleave', () => infoBox.transition().duration(200).style('opacity', 0));
            };

            addInfoTrigger(x(20), y(75), '#0ea5e9', 'Left Shift (↑Affinity)', 'Causes: ↓Temp, ↑pH, ↓2,3-DPG, HbF.\nHb holds O₂ tighter, hindering\ntissue unloading.');
            addInfoTrigger(x(65), y(70), '#ef4444', 'Right Shift (↓Affinity)', 'Causes: ↑Temp, ↓pH, ↑2,3-DPG, ↑CO₂.\nFacilitates O₂ release to tissues\nduring high metabolic activity.');
        }
    }, [type, title]);

    useEffect(() => {
        if (!containerRef.current) return;
        const observer = new ResizeObserver(() => renderGraph());
        observer.observe(containerRef.current);
        return () => observer.disconnect();
    }, [renderGraph]);

    const showMetadata = type === 'oxygen_dissociation';

    return (
        <div className={`bg-white dark:bg-slate-900 p-6 border-2 border-gray-100 dark:border-dark-border rounded-2xl shadow-inner overflow-hidden transition-all group ${className || ''}`}>
            <div ref={containerRef} className="w-full min-h-[300px] select-none"></div>

            {showMetadata && (
                <>
                    <div className="flex flex-wrap justify-center gap-x-8 gap-y-3 mt-6 pt-4 border-t border-gray-50 dark:border-dark-border text-[11px] font-bold uppercase tracking-widest">
                        <div className="flex items-center gap-2 text-sky-500">
                            <div className="w-4 h-0.5 border-t-2 border-dashed border-sky-400"></div>
                            <span>Left Shift</span>
                        </div>
                        <div className="flex items-center gap-2 text-brand-blue dark:text-blue-400">
                            <div className="w-5 h-1.5 bg-brand-blue dark:bg-blue-500 rounded-full"></div>
                            <span>Normal (P₅₀ ≈ 26.6)</span>
                        </div>
                        <div className="flex items-center gap-2 text-red-500">
                            <div className="w-4 h-0.5 border-t-2 border-dashed border-red-400"></div>
                            <span>Right Shift</span>
                        </div>
                    </div>
                    <p className="text-[10px] text-center text-gray-400 mt-4 italic font-medium">Hover over the curve for values. Hover over '?' for physiological explanations.</p>
                </>
            )}
        </div>
    );
};

