/**
 * Extracts JSON from a markdown code block if present, otherwise returns original text.
 */
const extractJson = (text: string) => {
    const jsonMatch = text.match(/```json\n([\s\S]*?)\n```/) || text.match(/```\n([\s\S]*?)\n```/);
    if (jsonMatch) return jsonMatch[1].trim();
    return text.trim();
};

export const generateCorePatientCase = async (condition: string, discipline: string, difficulty: string, language: string): Promise<PatientCase> => {
    const ai = getAiClient();
    const prompt = `Act as a senior medical consultant. Create a high-fidelity multidisciplinary patient case for "${condition}". Student Discipline: ${discipline}. Difficulty: ${difficulty}. Language: ${language}. ${SYNTHESIS_GUIDELINE} 

Remember: No citations in the narrative fields. Return JSON.`;
    const response: GenerateContentResponse = await retryWithBackoff(() => ai.models.generateContent({
        model: FAST_MODEL,
        contents: prompt,
        config: { 
            responseMimeType: "application/json", 
            responseSchema: corePatientCaseSchema,
            thinkingConfig: { thinkingBudget: 0 } 
        },
    }));
    return JSON.parse(response.text || "{}") as PatientCase;
};

const generateCasePart = async (coreCase: PatientCase, discipline: string, difficulty: string, language: string, taskDescription: string, responseSchema: any, useSearch: boolean = false) => {
    const ai = getAiClient();
    const prompt = `For the case "${coreCase.title}", generate ${taskDescription}. Student Discipline: ${discipline}. Difficulty: ${difficulty}. Language: ${language}. ${SYNTHESIS_GUIDELINE} Return JSON.`;

    const config: any = {
        thinkingConfig: { thinkingBudget: 0 }
    };

    if (useSearch) {
        config.tools = [{ googleSearch: {} }];
    } else {
        config.responseMimeType = "application/json";
        config.responseSchema = responseSchema;
    }

    const response: GenerateContentResponse = await retryWithBackoff(() => ai.models.generateContent({
        model: FAST_MODEL,
        contents: prompt,
        config,
    }));

    const rawText = response.text || "{}";
    const text = useSearch ? extractJson(rawText) : rawText;
    const sources = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];

    let parsedData = {};
    try {
        parsedData = JSON.parse(text);
    } catch (e) {
        console.warn("AI returned malformed JSON, attempting recovery:", text);
        // Minimal recovery: if search was used, AI sometimes adds intro text. 
        // We already use extractJson, but if that failed, we fallback to empty.
    }

    return { data: parsedData, sources };
};

