import React, { useEffect, useRef, useCallback } from 'react';

declare const d3: any;

type GraphType = 'oxygen_dissociation' | 'cerebral_pressure_volume' | 'cerebral_autoregulation' | 'other';

interface ScientificGraphProps {
    type: GraphType;
    title: string;
    className?: string;
}

export const ScientificGraph: React.FC<ScientificGraphProps> = ({ type, title, className }) => {
    const containerRef = useRef<HTMLDivElement>(null);

    const isSupportedType = ['oxygen_dissociation', 'cerebral_pressure_volume', 'cerebral_autoregulation'].includes(type);

    const renderGraph = useCallback(() => {
        if (!containerRef.current || !isSupportedType) return;

        const container = d3.select(containerRef.current);
        container.selectAll('*').remove();

        const rect = containerRef.current.getBoundingClientRect();
        if (rect.width === 0) return;

        const margin = { top: 50, right: 40, bottom: 60, left: 70 };
        const width = rect.width - margin.left - margin.right;
        const height = 350 - margin.top - margin.bottom;

        if (width <= 0 || height <= 0) return;

        const isDark = document.documentElement.classList.contains('dark');
        const textColor = isDark ? '#e2e8f0' : '#1e293b';
        const gridColor = isDark ? '#334155' : '#e2e8f0';

        const svg = container.append('svg')
            .attr('width', width + margin.left + margin.right)
            .attr('height', height + margin.top + margin.bottom)
            .attr('class', 'overflow-visible')
            .append('g')
            .attr('transform', `translate(${margin.left},${margin.top})`);

        const x = d3.scaleLinear().range([0, width]);
        const y = d3.scaleLinear().range([height, 0]);

        if (type === 'oxygen_dissociation') {
            const n = 2.8;
            const p50Normal = 26.6;
            const p50Right = 34.6;
            const p50Left = 18.6;
            const calcSaO2 = (p: number, p50: number) => (Math.pow(p, n) / (Math.pow(p, n) + Math.pow(p50, n))) * 100;
            const generateData = (p50Val: number) => {
                const arr = [];
                for (let p = 0; p <= 115; p += 0.5) arr.push({ x: p, y: calcSaO2(p, p50Val) });
                return arr;
            };

            x.domain([0, 110]);
            y.domain([0, 105]);

            const dataNormal = generateData(p50Normal);
            const line = d3.line().x((d: any) => x(d.x)).y((d: any) => y(d.y)).curve(d3.curveBasis);

            svg.append('path').datum(generateData(p50Left)).attr('fill', 'none').attr('stroke', '#38bdf8').attr('stroke-width', 2).attr('stroke-dasharray', '5,3').attr('d', line).attr('opacity', 0.6);
            svg.append('path').datum(generateData(p50Right)).attr('fill', 'none').attr('stroke', '#f87171').attr('stroke-width', 2).attr('stroke-dasharray', '5,3').attr('d', line).attr('opacity', 0.6);
            svg.append('path').datum(dataNormal).attr('fill', 'none').attr('stroke', isDark ? '#60a5fa' : '#1e3a8a').attr('stroke-width', 4).attr('d', line);

            // X-Axis Label
            svg.append('text').attr('x', width/2).attr('y', height + 45).attr('text-anchor', 'middle').attr('fill', textColor).attr('font-size', '12px').text('PO₂ (mmHg)');
            svg.append('text').attr('transform', 'rotate(-90)').attr('y', -50).attr('x', -height/2).attr('text-anchor', 'middle').attr('fill', textColor).attr('font-size', '12px').text('SaO₂ (%)');

        } else if (type === 'cerebral_pressure_volume') {
            // Monro-Kellie / ICP Curve
            x.domain([0, 100]);
            y.domain([0, 80]);

            const curveData = [];
            for (let v = 0; v <= 100; v += 1) {
                // Exponential increase: P = P0 * e^(k*V)
                const p = 5 * Math.exp(0.03 * v);
                curveData.push({ x: v, y: p });
            }

            const line = d3.line().x((d: any) => x(d.x)).y((d: any) => y(d.y)).curve(d3.curveBasis);
            svg.append('path').datum(curveData).attr('fill', 'none').attr('stroke', '#ef4444').attr('stroke-width', 4).attr('d', line);

            svg.append('text').attr('x', width/2).attr('y', height + 45).attr('text-anchor', 'middle').attr('fill', textColor).attr('font-size', '12px').text('Intracranial Volume (Relative)');
            svg.append('text').attr('transform', 'rotate(-90)').attr('y', -50).attr('x', -height/2).attr('text-anchor', 'middle').attr('fill', textColor).attr('font-size', '12px').text('ICP (mmHg)');

        } else if (type === 'cerebral_autoregulation') {
            // Lassen's Curve
            x.domain([0, 200]);
            y.domain([0, 100]);

            const curveData = [];
            for (let map = 0; map <= 200; map += 5) {
                let cbf = 50;
                if (map < 50) cbf = map; // Linear drop below 50
                else if (map > 150) cbf = 50 + (map - 150); // Breakthrough above 150
                curveData.push({ x: map, y: cbf });
            }

            const line = d3.line().x((d: any) => x(d.x)).y((d: any) => y(d.y)).curve(d3.curveBasis);
            svg.append('path').datum(curveData).attr('fill', 'none').attr('stroke', '#10b981').attr('stroke-width', 4).attr('d', line);

            svg.append('text').attr('x', width/2).attr('y', height + 45).attr('text-anchor', 'middle').attr('fill', textColor).attr('font-size', '12px').text('Mean Arterial Pressure (mmHg)');
            svg.append('text').attr('transform', 'rotate(-90)').attr('y', -50).attr('x', -height/2).attr('text-anchor', 'middle').attr('fill', textColor).attr('font-size', '12px').text('CBF (mL/100g/min)');
        }

        // Common Grid and Axes
        svg.append('g').attr('transform', `translate(0,${height})`).call(d3.axisBottom(x).ticks(5).tickSize(-height).tickFormat('')).attr('stroke', gridColor).attr('stroke-opacity', 0.1);
        svg.append('g').call(d3.axisLeft(y).ticks(5).tickSize(-width).tickFormat('')).attr('stroke', gridColor).attr('stroke-opacity', 0.1);

        const xAxis = svg.append('g').attr('transform', `translate(0,${height})`).call(d3.axisBottom(x));
        xAxis.selectAll('text').attr('fill', textColor);
        xAxis.selectAll('line').attr('stroke', textColor);

        const yAxis = svg.append('g').call(d3.axisLeft(y));
        yAxis.selectAll('text').attr('fill', textColor);
        yAxis.selectAll('line').attr('stroke', textColor);

        svg.append('text').attr('x', width / 2).attr('y', -25).attr('text-anchor', 'middle').attr('font-weight', '900').attr('fill', textColor).attr('font-size', '16px').text(title);

    }, [type, title, isSupportedType]);

    useEffect(() => {
        if (!containerRef.current || !isSupportedType) return;
        const observer = new ResizeObserver(() => renderGraph());
        observer.observe(containerRef.current);
        return () => observer.disconnect();
    }, [renderGraph, isSupportedType]);

    if (!isSupportedType) return null;

    return (
        <div className={`bg-white dark:bg-slate-900 p-4 sm:p-6 border-2 border-gray-100 dark:border-dark-border rounded-2xl shadow-inner overflow-hidden transition-all group ${className || ''}`}>
            <div ref={containerRef} className="w-full min-h-[250px] sm:min-h-[300px] select-none"></div>

            {type === 'oxygen_dissociation' && (
                <>
                    <div className="flex flex-wrap justify-center gap-x-8 gap-y-3 mt-4 pt-4 border-t border-gray-50 dark:border-dark-border text-[10px] font-bold uppercase tracking-widest">
                        <div className="flex items-center gap-2 text-sky-500">
                            <div className="w-4 h-0.5 border-t-2 border-dashed border-sky-400"></div>
                            <span>Left Shift</span>
                        </div>
                        <div className="flex items-center gap-2 text-brand-blue dark:text-blue-400">
                            <div className="w-5 h-1.5 bg-brand-blue dark:bg-blue-500 rounded-full"></div>
                            <span>Normal (P₅₀ ≈ 26.6)</span>
                        </div>
                        <div className="flex items-center gap-2 text-red-500">
                            <div className="w-4 h-0.5 border-t-2 border-dashed border-red-400"></div>
                            <span>Right Shift</span>
                        </div>
                    </div>
                    <p className="text-[9px] text-center text-gray-400 mt-4 italic font-medium">Visualization based on standard physiological models.</p>
                </>
            )}
        </div>
    );
};

