import React, { useEffect, useRef, useCallback } from 'react';

declare const d3: any;

type GraphType = 'oxygen_dissociation' | 'cerebral_pressure_volume' | 'cerebral_autoregulation' | 'other';

interface ScientificGraphProps {
    type: GraphType;
    title: string;
    className?: string;
}

export const ScientificGraph: React.FC<ScientificGraphProps> = ({ type, title, className }) => {
    const containerRef = useRef<HTMLDivElement>(null);

    const isSupportedType = ['oxygen_dissociation', 'cerebral_pressure_volume', 'cerebral_autoregulation'].includes(type);

    const renderGraph = useCallback(() => {
        if (!containerRef.current || !isSupportedType) return;

        const container = d3.select(containerRef.current);
        container.selectAll('*').remove();

        const rect = containerRef.current.getBoundingClientRect();
        if (rect.width === 0) return;

        const margin = { top: 50, right: 60, bottom: 60, left: 70 };
        const width = rect.width - margin.left - margin.right;
        const height = 350 - margin.top - margin.bottom;

        if (width <= 0 || height <= 0) return;

        const isDark = document.documentElement.classList.contains('dark');
        const textColor = isDark ? '#e2e8f0' : '#1e293b';
        const gridColor = isDark ? '#334155' : '#e2e8f0';

        const svg = container.append('svg')
            .attr('width', width + margin.left + margin.right)
            .attr('height', height + margin.top + margin.bottom)
            .attr('class', 'overflow-visible')
            .append('g')
            .attr('transform', `translate(${margin.left},${margin.top})`);

        const x = d3.scaleLinear().range([0, width]);
        const y = d3.scaleLinear().range([height, 0]);

        // Helper for Tooltips and Markers
        const addMarker = (xVal: number, yVal: number, color: string, infoTitle: string, infoDesc: string) => {
            const marker = svg.append('g')
                .attr('class', 'info-marker cursor-help')
                .attr('transform', `translate(${x(xVal)}, ${y(yVal)})`);

            marker.append('circle')
                .attr('r', 8)
                .attr('fill', color)
                .attr('stroke', '#fff')
                .attr('stroke-width', 2);

            marker.append('text')
                .attr('text-anchor', 'middle')
                .attr('dy', '0.35em')
                .attr('fill', '#fff')
                .attr('font-size', '10px')
                .attr('font-weight', 'bold')
                .text('?');

            const tooltip = marker.append('g')
                .attr('class', 'marker-tooltip')
                .style('opacity', 0)
                .style('pointer-events', 'none');

            tooltip.append('rect')
                .attr('x', 12)
                .attr('y', -40)
                .attr('width', 180)
