    const { data } = await generateCasePart(coreCase, discipline, difficulty, language, "a knowledge map with 8-10 highly connected nodes", knowledgeMapSchema);
    const validNodeIds = new Set((data as any).nodes?.map((n: KnowledgeNode) => n.id) || []);
