// Helper for generating distinct colors for each node
const getNodeColor = (id: string, discipline: string) => {
    // Generate a hue based on the node ID hash
    let hash = 0;
    for (let i = 0; i < id.length; i++) {
        hash = id.charCodeAt(i) + ((hash << 5) - hash);
    }
    const h = Math.abs(hash) % 360;
    // Blend with discipline base color for thematic consistency but visual distinction
    return `hsl(${h}, 70%, 50%)`;
};

