import { GoogleGenAI, Type, GenerateContentResponse, Modality } from "@google/genai";
import type { PatientCase, KnowledgeMapData, KnowledgeNode, KnowledgeLink, TraceableEvidence, FurtherReading, DiagramData, EcgFindings } from '../types';

const getAiClient = () => {
    return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

export async function retryWithBackoff<T>(
    fn: () => Promise<T>,
    maxRetries: number = 3,
    initialDelay: number = 1000
): Promise<T> {
    let lastError: any;
    for (let i = 0; i < maxRetries; i++) {
        try {
            return await fn();
        } catch (error: any) {
            lastError = error;
            const status = error?.status || error?.response?.status;
            if (status !== 429 && (status < 500 || status >= 600)) {
                throw error;
            }
            const delay = initialDelay * Math.pow(2, i);
            await new Promise(resolve => setTimeout(resolve, delay));
        }
    }
    throw lastError;
}

const FAST_MODEL = "gemini-3-flash-preview"; 

const SYNTHESIS_GUIDELINE = `
**STRICT PROFESSIONAL MEDICAL SYNTHESIS RULES:**
1. **Clean Formatting (CRITICAL):** Remove all unnecessary symbols, artifacts, or raw technical markers from visible text. Ensure the narrative is clean, legible, and professional. 
2. **Formula Handling:** Use standard scientific notation. Use LaTeX ONLY for complex chemical or physiological formulas (e.g., $MAP = DBP + 1/3(SBP-DBP)$). DO NOT use "$" symbols for plain text emphasis or currency.
3. **Narrative Integrity:** No citations or PMIDs in 'patientProfile', 'presentingComplaint', or 'history'. These fields must read like a real clinical record.
4. **Real-Time Accuracy:** You MUST use the googleSearch tool to verify the latest 2024-2025 clinical guidelines and research.
5. **High-Fidelity Tables:** Present all Vitals, Labs, and Medications as clean Markdown Tables. 
6. **Visual Triggers (MANDATORY):** Embed exactly one relevant tag per section where appropriate:
   - \`[GRAPH: oxygen_dissociation]\`
   - \`[GRAPH: frank_starling]\`
   - \`[GRAPH: pressure_volume_loop]\`
   - \`[GRAPH: cerebral_pressure_volume]\`
   - \`[GRAPH: cerebral_autoregulation]\`
7. **Quiz Quality:** Generate exactly 5 high-yield clinical MCQs with detailed physiological explanations.
8. **Academic Tone:** Use formal, precise medical terminology. Avoid colloquialisms.
`;

