// Helper for generating randomized distinct colors for each node
const getNodeColor = (id: string, index: number) => {
    // Generate a unique hue based on index and ID string hash for randomization
    let hash = 0;
    for (let i = 0; i < id.length; i++) {
        hash = id.charCodeAt(i) + ((hash << 5) - hash);
    }
    const hue = (Math.abs(hash) + (index * 137)) % 360; // 137 is a prime for better spread
    return `hsl(${hue}, 70%, 45%)`;
};

