/**
 * Sanitizes AI output to remove common professional text artifacts.
 */
const sanitizeContent = (text: string): string => {
    if (!text) return '';
    return text
        // Remove stray $ symbols that aren't wrapping valid math (e.g., "$ Patient presents...")
        // We preserve valid LaTeX formulas like $SaO_2$ or $$block$$
        .replace(/(^|\s)\$(?!\s*\S+\s*\$)/g, '$1') 
        .replace(/(\S)\$(\s|$)/g, '$1$2')
        // Clean up double spaces
        .replace(/\s{2,}/g, ' ')
        // Ensure bold markdown doesn't have messy trailing characters
        .replace(/\*\*:\s/g, '**: ')
        .trim();
};

export const MarkdownRenderer: React.FC<MarkdownRendererProps> = ({ content, className }) => {
