export async function retryWithBackoff<T>(
    fn: () => Promise<T>,
    maxRetries: number = 3,
    initialDelay: number = 1000
): Promise<T> {
    let lastError: any;
    for (let i = 0; i < maxRetries; i++) {
        try {
            return await fn();
        } catch (error: any) {
            lastError = error;
            const status = error?.status || error?.response?.status;
            if (status !== 429 && (status < 500 || status >= 600)) {
                throw error;
            }
            const delay = initialDelay * Math.pow(2, i);
            await new Promise(resolve => setTimeout(resolve, delay));
        }
    }
    throw lastError;
}

const FAST_MODEL = "gemini-3-flash-preview"; 

const SYNTHESIS_GUIDELINE = `
**STRICT PROFESSIONAL MEDICAL SYNTHESIS RULES:**
1. **Clean Formatting:** Remove unnecessary symbols/artifacts. Do NOT use raw LaTeX delimiters ($) for simple variables.
2. **Accurate Symbol Rendering:** Use Unicode for physiological variables (e.g., PaO₂, SaO₂, PvO₂, CO₂, H₂O, P_c, P_i, T½). Use subscripts/superscripts directly where possible.
3. **Formula Handling:** ONLY use LaTeX ($...$) for complex, multi-variable mathematical equations.
4. **Narrative Integrity:** No citations/PMIDs in 'patientProfile', 'presentingComplaint', or 'history'.
5. **Physiological Relevancy (SENSITIVE):** Embed a graph tag ONLY if it is directly relevant.
   Available Tags:
   - \`[GRAPH: oxygen_dissociation]\` (ARDS, Anemia, Sepsis)
   - \`[GRAPH: frank_starling]\` (CHF, Fluid resuscitation, Shock)
   - \`[GRAPH: pressure_volume_loop]\` (Valvular disease, Heart Failure)
   - \`[GRAPH: cerebral_pressure_volume]\` (TBI, ICH, ICP)
   - \`[GRAPH: cerebral_autoregulation]\` (Stroke, Neuro-anaesthesia)
6. **Quiz Quality:** Exactly 5 high-yield MCQs.
7. **Phased Management Structuring:** Categorize 'disciplineSpecificConsiderations' into "Preoperative", "Intraoperative", and "Postoperative" (or equivalent acute/recovery phases).
8. **Discipline Authenticity (CRITICAL):** Use technical language specific to the discipline (e.g., NANDA-I for Nursing, Pharmacokinetics for Pharmacology).
9. **Multidisciplinary Spectrum:** Provide 4-6 distinct items covering both Acute and Rehabilitation phases.
`;

const diagramNodeSchema = {
    type: Type.OBJECT,
    properties: {
        id: { type: Type.STRING },
