import React, { useMemo } from 'react';
import ReactMarkdown from 'react-markdown';
import remarkMath from 'remark-math';
import remarkGfm from 'remark-gfm';
import rehypeKatex from 'rehype-katex';

interface MarkdownRendererProps {
    content: string;
    className?: string;
}

/**
 * Aggressively sanitizes AI output to remove LaTeX artifacts and formatting glitches.
 * Targets symbols like $\, \$, and raw backslashes that interfere with readability.
 */
const sanitizeContent = (text: string): string => {
    if (!text) return '';
    return text
        // 1. Remove specific problematic LaTeX escaping artifacts found in discussions
        .replace(/\\\$/g, '$')           // Convert \$ to $
        .replace(/\$\\/g, '$')           // Convert $\ to $
        .replace(/\\_/g, '_')            // Convert \_ to _
        .replace(/\\\^/g, '^')           // Convert \^ to ^
        .replace(/\\\[/g, '[')           // Convert \[ to [
        .replace(/\\\]/g, ']')           // Convert \] to ]

        // 2. Clean up common medical/chemical variables to Unicode
        .replace(/\bPaO2\b/g, 'PaO₂')
        .replace(/\bSaO2\b/g, 'SaO₂')
        .replace(/\bPvO2\b/g, 'PvO₂')
        .replace(/\bCO2\b/g, 'CO₂')
        .replace(/\bO2\b/g, 'O₂')
        .replace(/\bH2O\b/g, 'H₂O')
        .replace(/\bt1\/2\b/gi, 'T½')

        // 3. Normalize spacing: Ensure words are properly separated if AI smushed them
        // This regex looks for lowercase followed by uppercase with no space (camelCase) in non-code text
        // and adds a space, though we must be careful with medical acronyms.
        // Instead, let's just focus on normalizing multiple spaces and newlines.
        .replace(/[ \t]+/g, ' ') 

        // 4. Remove stray $ that aren't part of a pair
        .replace(/(^|[^\$])\$([^\$]|$)/g, (match, p1, p2) => {
            // If it's a single $, just remove it unless it's followed by a number (currency)
            if (/\d/.test(p2)) return match;
            return p1 + p2;
        })

        // 5. Final pass for clean bullets and lines
        .replace(/^\s*[\-\*]\s+/gm, '• ')
        .trim();
