                                        <DiscussionBadge messages={patientCase.discussions?.[item.aspect]} />
                                        <button onClick={() => onOpenDiscussion(item)} className="text-[8px] bg-blue-50 dark:bg-blue-900/30 text-brand-blue dark:text-blue-300 font-black py-1 px-2.5 rounded-full border border-blue-100 dark:border-blue-900 transition-all hover:bg-brand-blue hover:text-white uppercase tracking-widest shadow-xs">{T.discussButton}</button>
                                    </div>
                                </div>
                                <div className="mt-1"><SmartContent content={item.consideration} language={language} T={T} onTriggerIllustration={(d) => handleTriggerIllustration(d, -1)} /></div>
                            </div>
                        );
                    })}
                </div>
            </Section>
        ) : isGeneratingDetails ? <Section title={T.managementConsiderations} onCopy={() => {}} onSaveSnippet={() => {}} T={T}><SkeletonLoader /></Section> : null }

        { archivedDiscussions.length > 0 && (
            <Section title="Session Discussions Archive" onCopy={() => {}} onSaveSnippet={() => {}} T={T}>
                <div className="grid grid-cols-1 gap-2 mt-2">
                    {archivedDiscussions.map(([topicId, msgs]) => (
                        <div key={topicId} className="bg-slate-50 dark:bg-slate-800/20 rounded-lg p-3 border border-gray-100 dark:border-dark-border flex items-center justify-between gap-4">
                            <div className="min-w-0">
                                <h5 className="font-bold text-gray-900 dark:text-slate-100 text-xs truncate">{topicId}</h5>
                                <p className="text-[10px] text-gray-500 dark:text-gray-400 italic truncate mt-0.5">Last: "{msgs[msgs.length - 1].text.substring(0, 60)}..."</p>
                            </div>
                            <button onClick={() => onOpenDiscussion({ aspect: topicId, consideration: '' })} className="flex-shrink-0 bg-white dark:bg-slate-700 px-3 py-1.5 rounded-lg border border-blue-100 dark:border-blue-900 text-brand-blue dark:text-blue-300 font-black text-[9px] uppercase tracking-widest shadow-xs hover:bg-brand-blue hover:text-white transition-all">Reopen History</button>
                        </div>
                    ))}
                </div>
            </Section>
        )}

        { (Array.isArray(patientCase.traceableEvidence) && patientCase.traceableEvidence.length > 0) || (Array.isArray(patientCase.furtherReadings) && patientCase.furtherReadings.length > 0) ? (
            <Section title={T.evidenceAndReading} onCopy={() => {}} onSaveSnippet={() => {}} T={T} onEnrich={handleEnrichSources} isEnriching={isEnrichingEvidence} groundingSources={groundingSources}>
                {Array.isArray(patientCase.traceableEvidence) && patientCase.traceableEvidence.length > 0 && (
                    <div className="mb-2"><h4 className="font-black text-xs text-gray-900 dark:text-slate-100 mb-1 flex items-center gap-1.5"><svg className="w-3.5 h-3.5 text-green-500" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M2.166 4.9L9.03 9.069a2.25 2.25 0 002.248 0l6.863-4.17A2.25 2.25 0 0015.83 2H4.477a2.25 2.25 0 00-2.311 2.9z" /><path d="M11 11.235V20l7-4.24V8.765l-7 2.47z" /><path d="M9 11.235V20L2 15.76V8.765l7 2.47z" /></svg>{T.traceableEvidence}</h4><ul className="space-y-1">{patientCase.traceableEvidence.map((e, i) => <li key={i} className="bg-slate-50 dark:bg-slate-800/20 p-2 rounded-lg border-l-4 border-green-500"><span className="font-bold block text-[10px] text-gray-800 dark:text-slate-100 mb-0.5">"{e.claim}"</span> <span className="block text-[9px]"><SourceRenderer text={e.source} onSearchClick={() => setActiveSourceSearch(e.source)} /></span></li>)}</ul></div>
                )}
            </Section>
        ) : isGeneratingDetails ? <Section title={T.evidenceAndReading} onCopy={() => {}} onSaveSnippet={() => {}} T={T}><SkeletonLoader /></Section> : null }

        { patientCase.quiz ? <QuizView quiz={patientCase.quiz} T={T} /> : isGeneratingDetails ? <Section title={T.quizTitle} onCopy={() => {}} onSaveSnippet={() => {}} T={T}><SkeletonLoader /></Section> : null }
      </div>
      {activeImageGenerator && <ImageGenerator content={activeImageGenerator.content} onClose={() => setActiveImageGenerator(null)} language={language} T={T} onImageGenerated={(img) => handleImageGenerated(activeImageGenerator.index, img)} />}
      {activeSourceSearch && <SourceSearchModal isOpen={!!activeSourceSearch} onClose={() => setActiveSourceSearch(null)} sourceQuery={activeSourceSearch} language={language} T={T} />}
    </div>
  );
};

import React, { useState, useEffect, useCallback } from 'react';
import type { PatientCase, ChatMessage } from '../types';
import { Document, Packer, Paragraph, HeadingLevel, AlignmentType, ImageRun, Table, TableRow, TableCell, WidthType, TextRun } from 'docx';

interface ShareModalProps {
    isOpen: boolean;
    onClose: () => void;
    patientCase: PatientCase | null;
    T: Record<string, any>;
}

// Helper: Compresses a JSON object into a URL-safe Base64 string
async function compressAndEncode(object: object): Promise<string> {
    try {
        const jsonString = JSON.stringify(object);
        const stream = new Blob([jsonString], { type: 'application/json' }).stream();
        const compressedStream = stream.pipeThrough(new CompressionStream('gzip'));
        const reader = compressedStream.getReader();
        const chunks: Uint8Array[] = [];
        while (true) {
            const { done, value } = await reader.read();
            if (done) break;
            chunks.push(value);
        }
        const buffer = await new Blob(chunks).arrayBuffer();
        const base64 = btoa(String.fromCharCode(...new Uint8Array(buffer)));
        return base64.replace(/\+/g, '-').replace(/\//g, '_').replace(/=/g, '');
    } catch (error) {
        console.error("Compression failed:", error);
        return '';
    }
}

// Helper: Formats the case data into a readable text string for download
const formatCaseForTextFile = (patientCase: PatientCase, T: Record<string, any>): string => {
    let text = `Title: ${patientCase.title}\r\n\r\n`;

    text += `## ${T.patientProfile}\r\n`;
    text += `${patientCase.patientProfile}\r\n\r\n`;

    text += `## ${T.presentingComplaint}\r\n`;
    text += `${patientCase.presentingComplaint}\r\n\r\n`;

    text += `## ${T.history}\r\n`;
    text += `${patientCase.history}\r\n\r\n`;

    if (patientCase.procedureDetails) {
        text += `## ${T.anestheticDataSection}\r\n`;
        text += `- **${T.procedureLabel}:** ${patientCase.procedureDetails.procedureName}\r\n`;
        text += `- **${T.asaScoreLabel}:** ${patientCase.procedureDetails.asaScore}\r\n\r\n`;
    }

    if (patientCase.biochemicalPathway) {
        text += `## ${T.biochemicalPathwaySection}\r\n`;
        text += `### ${patientCase.biochemicalPathway.title}\r\n`;
        text += `${patientCase.biochemicalPathway.description}\r\n\r\n`;
    }

    if (patientCase.disciplineSpecificConsiderations && patientCase.disciplineSpecificConsiderations.length > 0) {
        text += `## ${T.managementConsiderations}\r\n`;
        patientCase.disciplineSpecificConsiderations.forEach(item => {
            text += `- **${item.aspect}:** ${item.consideration}\r\n`;
        });
        text += '\r\n';
    }

    // APPEND DISCUSSIONS
    if (patientCase.discussions && Object.keys(patientCase.discussions).length > 0) {
        text += `\r\n========================================\r\n`;
        text += `## SESSION DISCUSSIONS APPENDIX\r\n`;
        text += `========================================\r\n\r\n`;

        // FIX: Explicitly cast Object.entries result to fix 'unknown' type error for 'messages'.
        (Object.entries(patientCase.discussions) as [string, ChatMessage[]][]).forEach(([topic, messages]) => {
            if (messages.length <= 1) return;
            text += `TOPIC: ${topic}\r\n`;
            text += `----------------------------------------\r\n`;
            messages.forEach(m => {
                if (m.role === 'system') return;
                text += `[${m.role.toUpperCase()}]: ${m.text}\r\n\r\n`;
            });
            text += `\r\n`;
        });
    }

    return text;
};

export const ShareModal: React.FC<ShareModalProps> = ({ isOpen, onClose, patientCase, T }) => {
    const [shareLink, setShareLink] = useState('');
    const [isGeneratingLink, setIsGeneratingLink] = useState(true);
    const [isCopied, setIsCopied] = useState(false);
    const isWebShareSupported = !!navigator.share;

    useEffect(() => {
        if (isOpen && patientCase) {
            setIsGeneratingLink(true);
            compressAndEncode(patientCase).then(encodedData => {
                const url = new URL(window.location.origin + window.location.pathname);
                url.searchParams.set('case', encodedData);
                setShareLink(url.toString());
                setIsGeneratingLink(false);
            });
        }
    }, [isOpen, patientCase]);

    const handleCopyLink = useCallback(() => {
        if (!shareLink) return;
        navigator.clipboard.writeText(shareLink).then(() => {
            setIsCopied(true);
            setTimeout(() => setIsCopied(false), 2000);
        });
    }, [shareLink]);

    const handleNativeShare = useCallback(() => {
        if (isWebShareSupported && shareLink && patientCase) {
            navigator.share({
                title: `Ungana Medical Case: ${patientCase.title}`,
                text: `Check out this medical case I generated with Ungana Medical.`,
                url: shareLink,
            }).catch(error => console.error("Web Share API error:", error));
        }
    }, [isWebShareSupported, shareLink, patientCase]);

    const handleDownloadFormat = async (format: 'json' | 'text' | 'pdf' | 'word') => {
        if (!patientCase) return;

        if (format === 'json') {
            const content = JSON.stringify(patientCase, null, 2);
            const blob = new Blob([content], { type: 'application/json' });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = `${patientCase.title.replace(/ /g, '_')}.json`;
            a.click();
        } else if (format === 'text') {
            const content = formatCaseForTextFile(patientCase, T);
            const blob = new Blob([content], { type: 'text/plain' });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = `${patientCase.title.replace(/ /g, '_')}.txt`;
            a.click();
        } else if (format === 'word') {
            const sections: any[] = [];
            sections.push(new Paragraph({ text: patientCase.title, heading: HeadingLevel.HEADING_1, alignment: AlignmentType.CENTER, spacing: { after: 400 } }));

            const addTxt = (h: string, c: string) => {
                if(!c) return;
                sections.push(new Paragraph({ text: h, heading: HeadingLevel.HEADING_2, spacing: { before: 200, after: 100 } }));
                sections.push(new Paragraph({ text: c }));
            }

            addTxt(T.patientProfile, patientCase.patientProfile);
            addTxt(T.presentingComplaint, patientCase.presentingComplaint);
            addTxt(T.history, patientCase.history);

            // Discussions Appendix in Word
            if (patientCase.discussions && Object.keys(patientCase.discussions).length > 0) {
                sections.push(new Paragraph({ text: 'Session Discussions Archive', heading: HeadingLevel.HEADING_1, alignment: AlignmentType.CENTER, spacing: { before: 800, after: 400 } }));

                // FIX: Explicitly cast Object.entries result to [string, ChatMessage[]][] to fix 'unknown' type errors for messages on lines 163 and 166.
                (Object.entries(patientCase.discussions) as [string, ChatMessage[]][]).forEach(([topic, messages]) => {
                    if (messages.length <= 1) return;
                    sections.push(new Paragraph({ text: `Discussion Topic: ${topic}`, heading: HeadingLevel.HEADING_3, spacing: { before: 300, after: 100 } }));

                    messages.forEach(m => {
                        if (m.role === 'system') return;
                        sections.push(new Paragraph({
                            children: [
                                new TextRun({ text: `${m.role.toUpperCase()}: `, bold: true, color: m.role === 'user' ? '1e3a8a' : '6b7280' }),
                                new TextRun({ text: m.text })
                            ],
                            spacing: { after: 150 }
                        }));
                    });
                });
            }

            const doc = new Document({ sections: [{ children: sections }] });
            const blob = await Packer.toBlob(doc);
            const a = document.createElement('a');
            a.href = URL.createObjectURL(blob);
            a.download = `${patientCase.title.replace(/ /g, '_')}.docx`;
            a.click();
        } else if (format === 'pdf') {
            alert("Please use the Export menu in the main case view to generate a high-quality PDF with diagrams.");
        }
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-black bg-opacity-60 flex items-center justify-center z-50 p-4 animate-fade-in" aria-modal="true" role="dialog">
            <div className="bg-white rounded-xl shadow-2xl w-full max-w-lg max-h-[95vh] sm:max-h-[80vh] flex flex-col">
                <header className="p-4 border-b border-gray-200 flex justify-between items-center">
                    <h2 className="text-lg font-bold text-gray-800">{T.shareModalTitle}</h2>
                    <button onClick={onClose} className="text-gray-400 hover:text-gray-600 transition" aria-label="Close">
                        <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg>
                    </button>
                </header>

                <main className="p-6 overflow-y-auto flex-grow space-y-5">
                    <div>
                        <label className="block text-sm font-medium text-gray-700">{T.shareLinkDescription}</label>
                        <div className="mt-1 flex rounded-md shadow-sm">
                            <input type="text" readOnly value={isGeneratingLink ? 'Generating link...' : shareLink} className="flex-1 block w-full rounded-none rounded-l-md p-2 border border-gray-300 bg-gray-50 text-gray-600 text-sm" />
                            <button onClick={handleCopyLink} disabled={isGeneratingLink || isCopied} className="inline-flex items-center px-4 py-2 border border-l-0 border-gray-300 rounded-r-md bg-gray-50 text-sm font-medium text-gray-700 hover:bg-gray-100 disabled:bg-gray-200">{isCopied ? T.linkCopied : T.copyLinkButton}</button>
                        </div>
                    </div>

                    <div className="grid grid-cols-2 gap-3">
                        <button onClick={() => handleDownloadFormat('word')} className="flex items-center justify-center space-x-2 bg-blue-600 hover:bg-blue-700 text-white font-bold py-2 px-4 rounded-md transition text-sm">
                             <svg className="h-4 w-4" fill="currentColor" viewBox="0 0 24 24"><path d="M12 2c5.514 0 10 4.486 10 10s-4.486 10-10 10-10-4.486-10-10 4.486-10 10-10zm0-2c-6.627 0-12 5.373-12 12s5.373 12 12 12 12-5.373 12-12-5.373-12-12-12zm-3 8h6v1h-6v-1zm0 2h6v1h-6v-1zm0 2h6v1h-6v-1zm0 2h6v1h-6v-1zm0 2h6v1h-6v-1z" /></svg>
                             <span>Full Archive (.docx)</span>
                        </button>
                        <button onClick={() => handleDownloadFormat('text')} className="flex items-center justify-center space-x-2 bg-gray-600 hover:bg-gray-700 text-white font-bold py-2 px-4 rounded-md transition text-sm">
                             <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M3 17a1 1 0 011-1h12a1 1 0 110 2H4a1 1 0 01-1-1zm3.293-7.707a1 1 0 011.414 0L9 10.586V3a1 1 0 112 0v7.586l1.293-1.293a1 1 0 111.414 1.414l-3 3a1 1 0 01-1.414 0l-3-3a1 1 0 010-1.414z" clipRule="evenodd" /></svg>
                            <span>Download Text</span>
                        </button>
                    </div>

