import React, { useEffect, useRef } from 'react';

interface AudioVisualizerProps {
    isListening: boolean;
}

export const AudioVisualizer: React.FC<AudioVisualizerProps> = ({ isListening }) => {
    const canvasRef = useRef<HTMLCanvasElement | null>(null);
    const audioContextRef = useRef<AudioContext | null>(null);
    const analyzerRef = useRef<AnalyserNode | null>(null);
    const animationFrameRef = useRef<number | null>(null);

    useEffect(() => {
        if (!isListening) {
            if (animationFrameRef.current) cancelAnimationFrame(animationFrameRef.current);
            return;
        }

        const startVisualizer = async () => {
            try {
                // High-fidelity microphone constraints
                const stream = await navigator.mediaDevices.getUserMedia({ 
                    audio: { 
                        echoCancellation: true, 
                        noiseSuppression: true, 
                        autoGainControl: true,
                        sampleRate: 48000
                    } 
                });
                audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
                const source = audioContextRef.current.createMediaStreamSource(stream);
                analyzerRef.current = audioContextRef.current.createAnalyser();
                // Increased fftSize for better visual fidelity
                analyzerRef.current.fftSize = 256;
                source.connect(analyzerRef.current);

                const bufferLength = analyzerRef.current.frequencyBinCount;
                const dataArray = new Uint8Array(bufferLength);
                const canvas = canvasRef.current;
                if (!canvas) return;
                const ctx = canvas.getContext('2d');
                if (!ctx) return;

                const draw = () => {
                    if (!isListening) return;
                    animationFrameRef.current = requestAnimationFrame(draw);
                    analyzerRef.current?.getByteFrequencyData(dataArray);

                    ctx.clearRect(0, 0, canvas.width, canvas.height);

                    const barWidth = (canvas.width / bufferLength) * 2;
                    let x = 0;

                    for (let i = 0; i < bufferLength; i++) {
                        // Increased visual sensitivity scaling
                        const barHeight = (dataArray[i] / 255) * canvas.height * 2.5;

                        // Vibrant medical blue color with reactive opacity
                        ctx.fillStyle = `rgba(59, 130, 246, ${0.4 + (dataArray[i] / 400)})`;
                        ctx.fillRect(x, canvas.height - barHeight, barWidth, barHeight);

                        x += barWidth + 1;
                    }
                };
                draw();
            } catch (err) {
                console.error("Visualizer failed", err);
            }
        };

        startVisualizer();

        return () => {
            if (animationFrameRef.current) cancelAnimationFrame(animationFrameRef.current);
            audioContextRef.current?.close();
        };
    }, [isListening]);

    if (!isListening) return null;

    return (
        <canvas 
            ref={canvasRef} 
            width="40" 
            height="20" 
            className="rounded-sm opacity-90 shadow-sm"
        />
    );
};

import React, { useState, useEffect, useRef } from 'react';
import { AudioVisualizer } from './AudioVisualizer';

interface ControlPanelProps {
  onGenerate: (condition: string, discipline: string, difficulty: string) => void;
  disabled: boolean;
  T: Record<string, any>;
  language: string;
  onSaveCase: () => void;
  onOpenSavedWork: () => void;
  onOpenClinicalTools: () => void;
  isCaseActive: boolean;
  onGenerateNew: () => void;
  mobileView: 'case' | 'map';
  onSetMobileView: (view: 'case' | 'map') => void;
}

const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
const isSpeechRecognitionSupported = !!SpeechRecognition;

const getBCP47Language = (lang: string): string => {
    const map: Record<string, string> = {
        'en': 'en-US', 'es': 'es-ES', 'fr': 'fr-FR', 'zh': 'zh-CN', 'hi': 'hi-IN',
        'sw': 'sw-KE', 'sn': 'sn-ZW', 'nd': 'nd-ZW', 'bem': 'en-ZM', 'ny': 'ny-MW',
        'ar': 'ar-SA', 'pt': 'pt-PT', 'ru': 'ru-RU', 'tn': 'tn-ZA', 'el': 'el-GR',
    };
    return map[lang] || 'en-US';
};

