                if (tx + 130 > width) tx = posX - 148;
                if (ty < -40) ty = posY + 20;
                tooltipGroup.attr('transform', `translate(${tx}, ${ty})`);
            });

    }, [type, title, isSupportedType]);

    useEffect(() => {
