                )}
            </Section>
        ) : isGeneratingDetails ? <Section title={T.evidenceAndReading} onCopy={() => {}} onSaveSnippet={() => {}} T={T}><SkeletonLoader /></Section> : null }

        { patientCase.quiz ? <QuizView quiz={patientCase.quiz} T={T} /> : isGeneratingDetails ? <Section title={T.quizTitle} onCopy={() => {}} onSaveSnippet={() => {}} T={T}><SkeletonLoader /></Section> : null }
      </div>
      {activeImageGenerator && <ImageGenerator content={activeImageGenerator.content} onClose={() => setActiveImageGenerator(null)} language={language} T={T} onImageGenerated={(img) => handleImageGenerated(activeImageGenerator.index, img)} />}
      {activeSourceSearch && <SourceSearchModal isOpen={!!activeSourceSearch} onClose={() => setActiveSourceSearch(null)} sourceQuery={activeSourceSearch} language={language} T={T} />}
    </div>
  );
};

import React, { useMemo } from 'react';
import ReactMarkdown from 'react-markdown';
import remarkMath from 'remark-math';
import remarkGfm from 'remark-gfm';
import rehypeKatex from 'rehype-katex';

interface MarkdownRendererProps {
    content: string;
    className?: string;
}

/**
 * High-fidelity sanitization for medical text.
 * Converts specific LaTeX artifacts to Unicode while preserving complex math syntax.
 */
const sanitizeContent = (text: string): string => {
    if (!text) return '';

    let cleaned = text
        // 1. Replace specific common LaTeX commands with Unicode where they often appear in plain text
        // We use lookaheads/lookbehinds to avoid clobbering math blocks if possible, 
        // but primarily we want to fix the "escaped" look of text.
        .replace(/\\rightarrow/gi, ' → ')
        .replace(/\\leftarrow/gi, ' ← ')
        .replace(/\\Delta/g, ' Δ ')
        .replace(/\\alpha/gi, ' α ')
        .replace(/\\beta/gi, ' β ')
        .replace(/\\gamma/gi, ' γ ')
        .replace(/\\approx/gi, ' ≈ ')
        .replace(/\\pm/gi, ' ± ')

        // 2. Clean up LaTeX escaping artifacts for characters that shouldn't be escaped in Markdown
        .replace(/\\_/g, '_')            
        .replace(/\\\^/g, '^')           
        .replace(/\\\[/g, '[')           
        .replace(/\\\]/g, ']')           

        // 3. Normalize spacing for medical units
        .replace(/(\d)(mg|mcg|mL|mmHg|bpm|mmol|meq)/gi, '$1 $2')

        // 4. Unicode for standard medical variables
        .replace(/\bPaO2\b/g, 'PaO₂')
        .replace(/\bSaO2\b/g, 'SaO₂')
        .replace(/\bPvO2\b/g, 'PvO₂')
        .replace(/\bCO2\b/g, 'CO₂')
        .replace(/\bO2\b/g, 'O₂')
        .replace(/\bH2O\b/g, 'H₂O')
        .replace(/\bt1\/2\b/gi, 'T½')

        // 5. Final cleanup - CRITICAL: Removed .replace(/\\/g, '') which was breaking math
        .replace(/[ \t]+/g, ' ')
        .replace(/\n{3,}/g, '\n\n')

        // 6. Fix bullet formatting
        .replace(/^\s*[\-\*]\s+/gm, '• ');

    return cleaned.trim();
};

export const MarkdownRenderer: React.FC<MarkdownRendererProps> = ({ content, className }) => {
    const cleanContent = useMemo(() => sanitizeContent(content), [content]);

    return (
        <ReactMarkdown
            remarkPlugins={[remarkMath, remarkGfm]}
